/**
 * JsonDatabase - A simple JSON-based database system
 * Provides SQL-like operations on JSON files
 * Supports two formats:
 * 1. Table format: {"users": [{"id":1,"name":"John"}]}
 * 2. Flat format: {"maxQuota": 50, "formActive": true}
 */
class JsonDatabase {
    private $basePath;
    private $currentFile;
    private $data;
    private $isFlat = false; // Detect flat structure
    
    public function __construct($basePath = './json_db/') {
        $this->basePath = rtrim($basePath, '/') . '/';
        if (!is_dir($this->basePath)) {
            mkdir($this->basePath, 0755, true);
        }
    }
    
    /**
     * Select a JSON file (equivalent to selecting a database)
     */
    public function selectFile($filename) {
        $this->currentFile = $this->basePath . basename($filename);
        if (!file_exists($this->currentFile)) {
            file_put_contents($this->currentFile, json_encode([], JSON_PRETTY_PRINT));
        }
        $this->loadData();
        return true;
    }
    
    /**
     * Set file path directly (for external files)
     */
    public function setFilePath($fullPath) {
        if (!file_exists($fullPath)) {
            throw new Exception('File not found: ' . $fullPath);
        }
        if (pathinfo($fullPath, PATHINFO_EXTENSION) !== 'json') {
            throw new Exception('File must be a JSON file');
        }
        $this->currentFile = $fullPath;
        $this->loadData();
        return true;
    }
    
    /**
     * Load data from current JSON file
     */
    private function loadData() {
        if (!$this->currentFile) {
            throw new Exception('No file selected');
        }
        $content = file_get_contents($this->currentFile);
        $decoded = json_decode($content, true);
        
        if (!is_array($decoded)) {
            $this->data = [];
        } else {
            // Check if root is an array (not object)
            if (isset($decoded[0])) {
                // Root-level array: wrap it with default table name
                $this->data = ['data' => $decoded];
            } else {
                $this->data = $decoded;
            }
        }
        
        // Detect if this is a flat structure (key-value pairs)
        $this->isFlat = $this->detectFlatStructure();
    }
    
    /**
     * Detect if JSON is flat structure (config-style) or table structure
     */
    private function detectFlatStructure() {
        if (empty($this->data)) {
            return false;
        }
        
        // Check if all values are scalar or if any value is an array of objects
        $hasArrayOfObjects = false;
        foreach ($this->data as $key => $value) {
            if (is_array($value) && !empty($value)) {
                // Check if it's an array of objects (table format)
                // First element should be an associative array (object)
                $firstElement = reset($value);
                if (is_array($firstElement) && !isset($firstElement[0])) {
                    // It's an associative array (object), so this is table format
                    $hasArrayOfObjects = true;
                    break;
                }
            }
        }
        
        // If no array of objects found, it's a flat structure
        return !$hasArrayOfObjects;
    }
    
    /**
     * Save data to current JSON file
     */
    private function saveData() {
        if (!$this->currentFile) {
            throw new Exception('No file selected');
        }
        
        // Check if we need to unwrap the data (root-level array)
        $toSave = $this->data;
        if (isset($this->data['data']) && count($this->data) === 1) {
            // Check if original file was root-level array
            $content = file_get_contents($this->currentFile);
            $original = json_decode($content, true);
            if (isset($original[0])) {
                // Original was root-level array, unwrap it
                $toSave = $this->data['data'];
            }
        }
        
        $json = json_encode($toSave, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        return file_put_contents($this->currentFile, $json) !== false;
    }
    
    /**
     * Get list of all JSON files (equivalent to SHOW DATABASES)
     */
    public function listFiles() {
        $files = glob($this->basePath . '*.json');
        return array_map('basename', $files);
    }
    
    /**
     * Get list of "tables" (root keys in JSON)
     * For flat structure, returns single table "config"
     */
    public function listTables() {
        if (!is_array($this->data)) {
            return [];
        }
        
        if ($this->isFlat) {
            // Flat structure: treat entire file as one table
            return ['config'];
        }
        
        return array_keys($this->data);
    }
    
    /**
     * Get table structure (columns from first row)
     * For flat structure, returns key-value structure
     */
    public function getTableStructure($table) {
        if ($this->isFlat) {
            // Flat structure: return columns as key, value, type
            return [
                ['Field' => 'key', 'Type' => 'string', 'Null' => 'NO', 'Key' => 'PRI', 'Default' => null, 'Extra' => ''],
                ['Field' => 'value', 'Type' => 'mixed', 'Null' => 'YES', 'Key' => '', 'Default' => null, 'Extra' => ''],
                ['Field' => 'type', 'Type' => 'string', 'Null' => 'YES', 'Key' => '', 'Default' => null, 'Extra' => '']
            ];
        }
        
        if (!isset($this->data[$table]) || !is_array($this->data[$table]) || empty($this->data[$table])) {
            return [];
        }
        
        $firstRow = reset($this->data[$table]);
        if (!is_array($firstRow)) {
            return [];
        }
        
        $structure = [];
        foreach ($firstRow as $key => $value) {
            $structure[] = [
                'Field' => $key,
                'Type' => $this->guessType($value),
                'Null' => 'YES',
                'Key' => $key === 'id' ? 'PRI' : '',
                'Default' => null,
                'Extra' => ''
            ];
        }
        return $structure;
    }
    
    /**
     * Guess data type from value
     */
    private function guessType($value) {
        if (is_int($value)) return 'int';
        if (is_float($value)) return 'float';
        if (is_bool($value)) return 'boolean';
        if (is_array($value)) return 'json';
        if (is_null($value)) return 'null';
        return 'string';
    }
    
    /**
     * SELECT query
     * For flat structure, converts to key-value-type rows
     */
    public function select($table, $conditions = [], $orderBy = null, $orderDir = 'DESC', $limit = null, $offset = 0) {
        if ($this->isFlat) {
            // Convert flat structure to rows
            $results = [];
            foreach ($this->data as $key => $value) {
                $results[] = [
                    'key' => $key,
                    'value' => is_array($value) ? json_encode($value) : $value,
                    'type' => $this->guessType($value)
                ];
            }
            
            // Apply conditions
            if (!empty($conditions)) {
                $results = array_filter($results, function($row) use ($conditions) {
                    foreach ($conditions as $field => $condition) {
                        $operator = $condition['operator'] ?? '=';
                        $value = $condition['value'] ?? '';
                        
                        if (!isset($row[$field])) {
                            return false;
                        }
                        
                        $rowValue = $row[$field];
                        
                        switch ($operator) {
                            case '=':
                                if ($rowValue != $value) return false;
                                break;
                            case '!=':
                                if ($rowValue == $value) return false;
                                break;
                            case 'LIKE':
                                $pattern = str_replace('%', '.*', preg_quote($value, '/'));
                                if (!preg_match('/^' . $pattern . '$/i', $rowValue)) return false;
                                break;
                        }
                    }
                    return true;
                });
            }
            
            // Apply ordering
            if ($orderBy && !empty($results)) {
                usort($results, function($a, $b) use ($orderBy, $orderDir) {
                    $aVal = $a[$orderBy] ?? '';
                    $bVal = $b[$orderBy] ?? '';
                    
                    if ($aVal == $bVal) return 0;
                    
                    $comparison = $aVal < $bVal ? -1 : 1;
                    return $orderDir === 'DESC' ? -$comparison : $comparison;
                });
            }
            
            // Apply limit and offset
            if ($limit !== null) {
                $results = array_slice($results, $offset, $limit);
            }
            
            return array_values($results);
        }
        
        // Table structure handling
        if (!isset($this->data[$table])) {
            return [];
        }
        
        $results = $this->data[$table];

        // --- ENHANCEMENT: Wrap single objects or primitive arrays as rows ---
        if (is_array($results)) {
            // Is it a single associative array (object)?
            if (!empty($results) && !isset($results[0])) {
                $results = [$results]; // Wrap into a single row
            } 
            // Is it an array of primitives (like the 'databases' list)?
            elseif (!empty($results) && isset($results[0]) && !is_array($results[0])) {
                $wrapped = [];
                foreach ($results as $val) $wrapped[] = ['value' => $val];
                $results = $wrapped;
            }
        } else {
            // It's a single primitive value
            $results = [['value' => $results]];
        }
        
        // Apply conditions (WHERE clause)
        if (!empty($conditions)) {
            $results = array_filter($results, function($row) use ($conditions) {
                foreach ($conditions as $field => $condition) {
                    $operator = $condition['operator'] ?? '=';
                    $value = $condition['value'] ?? '';
                    
                    if (!isset($row[$field])) {
                        return false;
                    }
                    
                    $rowValue = $row[$field];
                    
                    switch ($operator) {
                        case '=':
                            if ($rowValue != $value) return false;
                            break;
                        case '!=':
                            if ($rowValue == $value) return false;
                            break;
                        case '>':
                            if ($rowValue <= $value) return false;
                            break;
                        case '<':
                            if ($rowValue >= $value) return false;
                            break;
                        case '>=':
                            if ($rowValue < $value) return false;
                            break;
                        case '<=':
                            if ($rowValue > $value) return false;
                            break;
                        case 'LIKE':
                            $pattern = str_replace('%', '.*', preg_quote($value, '/'));
                            if (!preg_match('/^' . $pattern . '$/i', $rowValue)) return false;
                            break;
                        case 'IN':
                            if (!in_array($rowValue, (array)$value)) return false;
                            break;
                    }
                }
                return true;
            });
        }
        
        // Apply ordering
        if ($orderBy && !empty($results)) {
            usort($results, function($a, $b) use ($orderBy, $orderDir) {
                $aVal = $a[$orderBy] ?? '';
                $bVal = $b[$orderBy] ?? '';
                
                if ($aVal == $bVal) return 0;
                
                $comparison = $aVal < $bVal ? -1 : 1;
                return $orderDir === 'DESC' ? -$comparison : $comparison;
            });
        }
        
        // Apply limit and offset
        if ($limit !== null) {
            $results = array_slice($results, $offset, $limit);
        }
        
        return array_values($results);
    }
    
    /**
     * Count rows
     */
    public function count($table, $conditions = []) {
        $results = $this->select($table, $conditions);
        return count($results);
    }
    
    /**
     * INSERT query
     * For flat structure, adds/updates key-value pair
     */
    public function insert($table, $data) {
        if ($this->isFlat) {
            // Flat structure: add/update key-value
            if (isset($data['key']) && isset($data['value'])) {
                $key = $data['key'];
                $value = $data['value'];
                
                // Try to decode JSON
                $decoded = json_decode($value, true);
                if (json_last_error() === JSON_ERROR_NONE) {
                    $value = $decoded;
                }
                
                // Convert string booleans
                if ($value === 'true') $value = true;
                if ($value === 'false') $value = false;
                
                // Convert numeric strings
                if (is_numeric($value)) {
                    $value = strpos($value, '.') !== false ? (float)$value : (int)$value;
                }
                
                $this->data[$key] = $value;
                return $this->saveData();
            }
            return false;
        }
        
        // Table structure handling
        if (!isset($this->data[$table])) {
            $this->data[$table] = [];
        }
        
        // Auto-generate ID if not provided
        if (!isset($data['id'])) {
            $maxId = 0;
            foreach ($this->data[$table] as $row) {
                if (isset($row['id']) && is_numeric($row['id']) && $row['id'] > $maxId) {
                    $maxId = $row['id'];
                }
            }
            $data['id'] = $maxId + 1;
        }
        
        $this->data[$table][] = $data;
        return $this->saveData();
    }
    
    /**
     * Duplicate row
     */
    public function duplicate_row($table, $pkVal) {
        if (!isset($this->data[$table])) return false;
        foreach ($this->data[$table] as $row) {
            if (isset($row['id']) && $row['id'] == $pkVal) {
                $newRow = $row;
                unset($newRow['id']); // Let insert re-generate it
                return $this->insert($table, $newRow);
            }
        }
        return false;
    }
    
    /**
     * UPDATE query
     * For flat structure, updates key-value pair
     */
    public function update($table, $data, $conditions) {
        if ($this->isFlat) {
            // Flat structure: update by key
            if (isset($conditions['key'])) {
                $key = $conditions['key']['value'];
                if (isset($this->data[$key]) && isset($data['value'])) {
                    $value = $data['value'];
                    
                    // Try to decode JSON
                    $decoded = json_decode($value, true);
                    if (json_last_error() === JSON_ERROR_NONE) {
                        $value = $decoded;
                    }
                    
                    // Convert string booleans
                    if ($value === 'true') $value = true;
                    if ($value === 'false') $value = false;
                    
                    // Convert numeric strings
                    if (is_numeric($value)) {
                        $value = strpos($value, '.') !== false ? (float)$value : (int)$value;
                    }
                    
                    $this->data[$key] = $value;
                    return $this->saveData() ? 1 : 0;
                }
            }
            return 0;
        }
        
        // Table structure handling
        if (!isset($this->data[$table])) {
            return false;
        }
        
        $updated = 0;
        foreach ($this->data[$table] as &$row) {
            $match = true;
            foreach ($conditions as $field => $condition) {
                $operator = $condition['operator'] ?? '=';
                $value = $condition['value'] ?? '';
                
                if (!isset($row[$field]) || $row[$field] != $value) {
                    $match = false;
                    break;
                }
            }
            
            if ($match) {
                foreach ($data as $key => $value) {
                    $row[$key] = $value;
                }
                $updated++;
            }
        }
        
        if ($updated > 0) {
            $this->saveData();
        }
        
        return $updated;
    }
    
    /**
     * DELETE query
     * For flat structure, removes key
     */
    public function delete($table, $conditions) {
        if ($this->isFlat) {
            // Flat structure: delete by key
            if (isset($conditions['key'])) {
                $key = $conditions['key']['value'];
                if (isset($this->data[$key])) {
                    unset($this->data[$key]);
                    return $this->saveData() ? 1 : 0;
                }
            }
            return 0;
        }
        
        // Table structure handling
        if (!isset($this->data[$table])) {
            return 0;
        }
        
        $originalCount = count($this->data[$table]);
        
        $this->data[$table] = array_filter($this->data[$table], function($row) use ($conditions) {
            foreach ($conditions as $field => $condition) {
                $operator = $condition['operator'] ?? '=';
                $value = $condition['value'] ?? '';
                
                if (isset($row[$field]) && $row[$field] == $value) {
                    return false; // Remove this row
                }
            }
            return true; // Keep this row
        });
        
        $this->data[$table] = array_values($this->data[$table]); // Re-index
        
        $deleted = $originalCount - count($this->data[$table]);
        
        if ($deleted > 0) {
            $this->saveData();
        }
        
        return $deleted;
    }
    
    /**
     * Create new table
     */
    public function createTable($table, $structure = []) {
        if (!isset($this->data[$table])) {
            $this->data[$table] = [];
            return $this->saveData();
        }
        return false;
    }
    
    /**
     * Drop table
     */
    public function dropTable($table) {
        if (isset($this->data[$table])) {
            unset($this->data[$table]);
            return $this->saveData();
        }
        return false;
    }
    
    /**
     * Truncate table
     */
    public function truncateTable($table) {
        if (isset($this->data[$table])) {
            $this->data[$table] = [];
            return $this->saveData();
        }
        return false;
    }
    
    /**
     * Get primary key field (assumes 'id' or first field)
     * For flat structure, returns 'key'
     */
    public function getPrimaryKey($table) {
        if ($this->isFlat) {
            return 'key';
        }
        
        $structure = $this->getTableStructure($table);
        if (empty($structure)) {
            return 'id';
        }
        
        foreach ($structure as $field) {
            if ($field['Key'] === 'PRI') {
                return $field['Field'];
            }
        }
        
        return $structure[0]['Field'] ?? 'id';
    }
    
    /**
     * Export table to array
     */
    public function exportTable($table) {
        return $this->data[$table] ?? [];
    }
    
    /**
     * Import data to table
     */
    public function importTable($table, $data) {
        if (!is_array($data)) {
            return false;
        }
        
        $this->data[$table] = $data;
        return $this->saveData();
    }
    
    /**
     * Get current file path
     */
    public function getCurrentFile() {
        return $this->currentFile;
    }
    
    /**
     * Get base path
     */
    public function getBasePath() {
        return $this->basePath;
    }
    
    /**
     * Create new JSON file
     */
    public function createFile($filename, $initialData = []) {
        $filepath = $this->basePath . basename($filename);
        if (file_exists($filepath)) {
            return false;
        }
        
        $json = json_encode($initialData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        return file_put_contents($filepath, $json) !== false;
    }
    
    /**
     * Delete JSON file
     */
    public function deleteFile($filename) {
        $filepath = $this->basePath . basename($filename);
        if (file_exists($filepath)) {
            return unlink($filepath);
        }
        return false;
    }
}
/**
 * ============================================================
 * 🔑 API MANAGEMENT & TASK SCHEDULER DOCUMENTATION
 * ============================================================
 *
 * =========================
 * 1. CREATE API KEY
 * =========================
 *
 * Via JavaScript:
 *
 * fetch('?api=api_manager', {
 *     method: 'POST',
 *     headers: {'Content-Type': 'application/x-www-form-urlencoded'},
 *     body: 'action=create_key&name=My App&rate_limit=1000'
 * })
 * .then(r => r.json())
 * .then(data => console.log(data.key));
 *
 *
 * =========================
 * 2. USE API (REST)
 * =========================
 *
 * # GET all records
 * curl -H "X-API-Key: YOUR_API_KEY" \
 *   https://yoursite.com/adminer.php/api/users
 *
 * # GET single record
 * curl -H "X-API-Key: YOUR_API_KEY" \
 *   https://yoursite.com/adminer.php/api/users/1
 *
 * # POST create record
 * curl -X POST \
 *   -H "X-API-Key: YOUR_API_KEY" \
 *   -H "Content-Type: application/json" \
 *   -d '{"name":"John","email":"john@example.com"}' \
 *   https://yoursite.com/adminer.php/api/users
 *
 * # PUT update record
 * curl -X PUT \
 *   -H "X-API-Key: YOUR_API_KEY" \
 *   -H "Content-Type: application/json" \
 *   -d '{"name":"John Updated"}' \
 *   https://yoursite.com/adminer.php/api/users/1
 *
 * # DELETE record
 * curl -X DELETE \
 *   -H "X-API-Key: YOUR_API_KEY" \
 *   https://yoursite.com/adminer.php/api/users/1
 *
 *
 * =========================
 * 3. API MANAGEMENT ACTIONS
 * =========================
 *
 * // Get all API keys
 * fetch('?api=api_manager&action=get_keys')
 *
 * // Delete API key
 * fetch('?api=api_manager', {
 *     method: 'POST',
 *     body: 'action=delete_key&key_id=key_xxx'
 * })
 *
 * // Toggle API key
 * fetch('?api=api_manager', {
 *     method: 'POST',
 *     body: 'action=toggle_key&key_id=key_xxx'
 * })
 *
 * // Get API logs
 * fetch('?api=api_manager&action=get_logs&limit=100')
 *
 * // Get API stats
 * fetch('?api=api_manager&action=get_stats')
 *
 * // Get API documentation
 * fetch('?api=api_manager&action=get_docs')
 * ============================================================================
 * API GENERATOR CLASS
 * Auto-generate REST API endpoints for database tables
 * ============================================================================
 */
class APIGenerator {
    private $configFile;
    private $logFile;
    private $pdo;
    private $dbMode;
    
    public function __construct($configFile, $pdo = null, $dbMode = 'sql') {
        $this->configFile = $configFile;
        $this->logFile = __DIR__ . '/api_logs.json';
        $this->pdo = $pdo;
        $this->dbMode = $dbMode;
    }
    
    public function validateApiKey($apiKey) {
        if (empty($apiKey)) return false;
        
        $config = load_config($this->configFile);
        $apiKeys = $config['api_keys'] ?? [];
        
        foreach ($apiKeys as $key) {
            if ($key['key'] === $apiKey && $key['enabled']) {
                if (!$this->checkRateLimit($key)) return false;
                return $key;
            }
        }
        return false;
    }
    
    private function checkRateLimit($keyConfig) {
        $limit = $keyConfig['rate_limit'] ?? 1000;
        $keyId = $keyConfig['id'];
        
        $config = load_config($this->configFile);
        $rateLimits = $config['api_rate_limits'] ?? [];
        
        $now = time();
        $hourAgo = $now - 3600;
        
        if (isset($rateLimits[$keyId])) {
            $rateLimits[$keyId] = array_filter($rateLimits[$keyId], function($timestamp) use ($hourAgo) {
                return $timestamp > $hourAgo;
            });
        } else {
            $rateLimits[$keyId] = [];
        }
        
        if (count($rateLimits[$keyId]) >= $limit) return false;
        
        $rateLimits[$keyId][] = $now;
        $config['api_rate_limits'] = $rateLimits;
        save_config($this->configFile, $config);
        
        return true;
    }
    
    public function handleRequest($table, $method, $id = null, $data = []) {
        $startTime = microtime(true);
        
        try {
            $result = null;
            
            switch ($method) {
                case 'GET':
                    $result = $id ? $this->getOne($table, $id) : $this->getAll($table, $data);
                    break;
                case 'POST':
                    $result = $this->create($table, $data);
                    break;
                case 'PUT':
                case 'PATCH':
                    $result = $this->update($table, $id, $data);
                    break;
                case 'DELETE':
                    $result = $this->delete($table, $id);
                    break;
                default:
                    throw new Exception('Method not allowed');
            }
            
            $duration = microtime(true) - $startTime;
            $this->logRequest($table, $method, $id, true, $duration);
            
            return [
                'success' => true,
                'data' => $result,
                'meta' => [
                    'timestamp' => time(),
                    'duration' => round($duration * 1000, 2) . 'ms'
                ]
            ];
            
        } catch (Exception $e) {
            $duration = microtime(true) - $startTime;
            $this->logRequest($table, $method, $id, false, $duration, $e->getMessage());
            
            return [
                'success' => false,
                'error' => $e->getMessage(),
                'meta' => [
                    'timestamp' => time(),
                    'duration' => round($duration * 1000, 2) . 'ms'
                ]
            ];
        }
    }
    
    private function getAll($table, $params) {
        if ($this->dbMode === 'sql' && $this->pdo) {
            $where = [];
            $bindings = [];
            
            $page = (int)($params['page'] ?? 1);
            $perPage = min((int)($params['per_page'] ?? 50), 100);
            $offset = ($page - 1) * $perPage;
            
            foreach ($params as $key => $value) {
                if (!in_array($key, ['page', 'per_page', 'sort', 'order'])) {
                    $where[] = "`$key` = ?";
                    $bindings[] = $value;
                }
            }
            
            $sort = $params['sort'] ?? 'id';
            $order = strtoupper($params['order'] ?? 'ASC');
            if (!in_array($order, ['ASC', 'DESC'])) $order = 'ASC';
            
            $sql = "SELECT * FROM `$table`";
            if (!empty($where)) {
                $sql .= " WHERE " . implode(' AND ', $where);
            }
            $sql .= " ORDER BY `$sort` $order LIMIT $perPage OFFSET $offset";
            
            $stmt = $this->pdo->prepare($sql);
            $stmt->execute($bindings);
            $data = $stmt->fetchAll(PDO::FETCH_ASSOC);
            
            $countSql = "SELECT COUNT(*) FROM `$table`";
            if (!empty($where)) {
                $countSql .= " WHERE " . implode(' AND ', $where);
            }
            $countStmt = $this->pdo->prepare($countSql);
            $countStmt->execute($bindings);
            $total = $countStmt->fetchColumn();
            
            return [
                'items' => $data,
                'pagination' => [
                    'page' => $page,
                    'per_page' => $perPage,
                    'total' => (int)$total,
                    'total_pages' => ceil($total / $perPage)
                ]
            ];
        }
        
        throw new Exception('Database not connected');
    }
    
    private function getOne($table, $id) {
        if ($this->dbMode === 'sql' && $this->pdo) {
            $stmt = $this->pdo->prepare("SELECT * FROM `$table` WHERE id = ? LIMIT 1");
            $stmt->execute([$id]);
            $data = $stmt->fetch(PDO::FETCH_ASSOC);
            
            if (!$data) {
                throw new Exception('Record not found');
            }
            
            return $data;
        }
        
        throw new Exception('Database not connected');
    }
    
    private function create($table, $data) {
        if ($this->dbMode === 'sql' && $this->pdo) {
            $fields = array_keys($data);
            $placeholders = array_fill(0, count($fields), '?');
            
            $sql = "INSERT INTO `$table` (`" . implode('`, `', $fields) . "`) VALUES (" . implode(', ', $placeholders) . ")";
            
            $stmt = $this->pdo->prepare($sql);
            $stmt->execute(array_values($data));
            
            $id = $this->pdo->lastInsertId();
            
            return $this->getOne($table, $id);
        }
        
        throw new Exception('Database not connected');
    }
    
    private function update($table, $id, $data) {
        if ($this->dbMode === 'sql' && $this->pdo) {
            $fields = [];
            foreach (array_keys($data) as $field) {
                $fields[] = "`$field` = ?";
            }
            
            $sql = "UPDATE `$table` SET " . implode(', ', $fields) . " WHERE id = ?";
            
            $values = array_values($data);
            $values[] = $id;
            
            $stmt = $this->pdo->prepare($sql);
            $stmt->execute($values);
            
            return $this->getOne($table, $id);
        }
        
        throw new Exception('Database not connected');
    }
    
    private function delete($table, $id) {
        if ($this->dbMode === 'sql' && $this->pdo) {
            $stmt = $this->pdo->prepare("DELETE FROM `$table` WHERE id = ?");
            $stmt->execute([$id]);
            
            return ['deleted' => true, 'id' => $id];
        }
        
        throw new Exception('Database not connected');
    }
    
    private function logRequest($table, $method, $id, $success, $duration, $error = null) {
        $logs = [];
        if (file_exists($this->logFile)) {
            $logs = json_decode(file_get_contents($this->logFile), true) ?? [];
        }
        
        $log = [
            'timestamp' => time(),
            'table' => $table,
            'method' => $method,
            'id' => $id,
            'success' => $success,
            'duration' => round($duration * 1000, 2),
            'error' => $error,
            'ip' => $_SERVER['REMOTE_ADDR'] ?? 'unknown'
        ];
        
        array_unshift($logs, $log);
        $logs = array_slice($logs, 0, 1000);
        
        file_put_contents($this->logFile, json_encode($logs, JSON_PRETTY_PRINT));
    }
    
    public function getLogs($limit = 100) {
        if (!file_exists($this->logFile)) {
            return [];
        }
        
        $logs = json_decode(file_get_contents($this->logFile), true) ?? [];
        return array_slice($logs, 0, $limit);
    }
    
    public function getStats() {
        $logs = $this->getLogs(1000);
        
        $stats = [
            'total_requests' => count($logs),
            'successful_requests' => count(array_filter($logs, fn($l) => $l['success'])),
            'failed_requests' => count(array_filter($logs, fn($l) => !$l['success'])),
            'avg_duration' => 0,
            'requests_by_method' => [],
            'requests_by_table' => []
        ];
        
        if (!empty($logs)) {
            $totalDuration = array_sum(array_column($logs, 'duration'));
            $stats['avg_duration'] = round($totalDuration / count($logs), 2);
            
            foreach ($logs as $log) {
                $method = $log['method'];
                $table = $log['table'];
                
                if (!isset($stats['requests_by_method'][$method])) {
                    $stats['requests_by_method'][$method] = 0;
                }
                $stats['requests_by_method'][$method]++;
                
                if (!isset($stats['requests_by_table'][$table])) {
                    $stats['requests_by_table'][$table] = 0;
                }
                $stats['requests_by_table'][$table]++;
            }
        }
        
        return $stats;
    }
    
    public function generateDocs($tables) {
        $docs = [
            'title' => 'Database API Documentation',
            'version' => '1.0.0',
            'base_url' => $this->getBaseUrl(),
            'authentication' => [
                'type' => 'API Key',
                'header' => 'X-API-Key',
                'description' => 'Include your API key in the X-API-Key header'
            ],
            'endpoints' => []
        ];
        
        foreach ($tables as $table) {
            $tableName = is_array($table) ? ($table['Name'] ?? $table['TABLE_NAME']) : $table;
            
            $docs['endpoints'][] = [
                'resource' => $tableName,
                'operations' => [
                    [
                        'method' => 'GET',
                        'path' => "/api/$tableName",
                        'description' => "Get all $tableName records",
                        'parameters' => [
                            'page' => 'Page number (default: 1)',
                            'per_page' => 'Records per page (default: 50, max: 100)',
                            'sort' => 'Sort field (default: id)',
                            'order' => 'Sort order: ASC or DESC (default: ASC)'
                        ]
                    ],
                    [
                        'method' => 'GET',
                        'path' => "/api/$tableName/{id}",
                        'description' => "Get single $tableName record by ID"
                    ],
                    [
                        'method' => 'POST',
                        'path' => "/api/$tableName",
                        'description' => "Create new $tableName record",
                        'body' => 'JSON object with record data'
                    ],
                    [
                        'method' => 'PUT',
                        'path' => "/api/$tableName/{id}",
                        'description' => "Update $tableName record",
                        'body' => 'JSON object with fields to update'
                    ],
                    [
                        'method' => 'DELETE',
                        'path' => "/api/$tableName/{id}",
                        'description' => "Delete $tableName record"
                    ]
                ]
            ];
        }
        
        return $docs;
    }
    
    private function getBaseUrl() {
        $protocol = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on' ? 'https' : 'http';
        $host = $_SERVER['HTTP_HOST'] ?? 'localhost';
        $script = dirname($_SERVER['SCRIPT_NAME']);
        return $protocol . '://' . $host . $script;
    }
}

/**

 * ============================================================
 * ⏰ TASK SCHEDULER
 * ============================================================
 *
 * =========================
 * 1. CREATE TASK
 * =========================
 *
 * // Scheduled Telegram Backup
 * fetch('?api=scheduler', {
 *     method: 'POST',
 *     headers: {'Content-Type': 'application/x-www-form-urlencoded'},
 *     body: new URLSearchParams({
 *         action: 'add_task',
 *         name: 'Daily Backup',
 *         type: 'backup_telegram',
 *         schedule: '1d',
 *         database: 'production_db'
 *     })
 * })
 *
 * // Scheduled Query
 * fetch('?api=scheduler', {
 *     method: 'POST',
 *     body: new URLSearchParams({
 *         action: 'add_task',
 *         name: 'Cleanup Old Logs',
 *         type: 'query',
 *         schedule: '1w',
 *         database: 'production_db',
 *         query: 'DELETE FROM logs WHERE created_at < DATE_SUB(NOW(), INTERVAL 30 DAY)'
 *     })
 * });
 *
 *
 * =========================
 * 2. SCHEDULE FORMAT
 * =========================
 *
 * Simple Interval:
 * - "5m"  = Every 5 minutes
 * - "1h"  = Every 1 hour
 * - "12h" = Every 12 hours
 * - "1d"  = Every 1 day
 * - "1w"  = Every 1 week
 *
 * Cron Format:
 * - "0 2 * * *"    = Every day at 2:00 AM
 * - "*-/15 * * * *" = Every 15 minutes
 * - "0 0 * * 0"    = Every Sunday midnight
 * - "0 9 1 * *"    = First day of month at 9:00 AM
 *
 *
 * =========================
 * 3. TASK MANAGEMENT
 * =========================
 *
 * // Get all tasks
 * fetch('?api=scheduler&action=get_tasks')
 *
 * // Run task manually
 * fetch('?api=scheduler', {
 *     method: 'POST',
 *     body: 'action=run_task&task_id=task_xxx'
 * })
 *
 * // Toggle task
 * fetch('?api=scheduler', {
 *     method: 'POST',
 *     body: 'action=toggle_task&task_id=task_xxx'
 * })
 *
 * // Delete task
 * fetch('?api=scheduler', {
 *     method: 'POST',
 *     body: 'action=delete_task&task_id=task_xxx'
 * })
 *
 * // Get logs & stats
 * fetch('?api=scheduler&action=get_logs&limit=100')
 * fetch('?api=scheduler&action=get_stats')
 *
 *
 * ============================================================
 * 🌐 WEB CRON SETUP
 * ============================================================
 *
 * # Cron job
 * * * * * curl "https://yoursite.com/adminer.php?cron=1&key=your_secret_key_here"
 *
 * # Or wget
 * * * * * wget -q -O - "https://yoursite.com/adminer.php?cron=1&key=your_secret_key_here"
 *
 * Change secret key in adminer.php:
 *
 * $secretKey = 'my_super_secret_key_12345';
 *
 *
 * ============================================================================
 * TASK SCHEDULER CLASS
 * Cron-like task scheduler for automated tasks
 * ============================================================================
 */
class TaskScheduler {
    private $configFile;
    private $logFile;
    
    public function __construct($configFile) {
        $this->configFile = $configFile;
        $this->logFile = __DIR__ . '/scheduler_logs.json';
    }
    
    public function getTasks() {
        $config = load_config($this->configFile);
        return $config['scheduled_tasks'] ?? [];
    }
    
    public function addTask($task) {
        $config = load_config($this->configFile);
        if (!isset($config['scheduled_tasks'])) {
            $config['scheduled_tasks'] = [];
        }
        
        $task['id'] = uniqid('task_');
        $task['created_at'] = time();
        $task['last_run'] = null;
        $task['next_run'] = $this->calculateNextRun($task['schedule']);
        $task['enabled'] = true;
        $task['run_count'] = 0;
        
        $config['scheduled_tasks'][] = $task;
        save_config($this->configFile, $config);
        
        return $task;
    }
    
    public function updateTask($taskId, $updates) {
        $config = load_config($this->configFile);
        $tasks = $config['scheduled_tasks'] ?? [];
        
        foreach ($tasks as &$task) {
            if ($task['id'] === $taskId) {
                $task = array_merge($task, $updates);
                if (isset($updates['schedule'])) {
                    $task['next_run'] = $this->calculateNextRun($updates['schedule']);
                }
                save_config($this->configFile, $config);
                return $task;
            }
        }
        
        return false;
    }
    
    public function deleteTask($taskId) {
        $config = load_config($this->configFile);
        $tasks = $config['scheduled_tasks'] ?? [];
        
        $config['scheduled_tasks'] = array_filter($tasks, function($task) use ($taskId) {
            return $task['id'] !== $taskId;
        });
        
        $config['scheduled_tasks'] = array_values($config['scheduled_tasks']);
        save_config($this->configFile, $config);
        
        return true;
    }
    
    public function toggleTask($taskId) {
        $config = load_config($this->configFile);
        $tasks = $config['scheduled_tasks'] ?? [];
        
        foreach ($tasks as &$task) {
            if ($task['id'] === $taskId) {
                $task['enabled'] = !$task['enabled'];
                save_config($this->configFile, $config);
                return $task;
            }
        }
        
        return false;
    }
    
    public function runTask($taskId) {
        $config = load_config($this->configFile);
        $tasks = $config['scheduled_tasks'] ?? [];
        
        foreach ($tasks as &$task) {
            if ($task['id'] === $taskId) {
                $result = $this->executeTask($task);
                
                $task['last_run'] = time();
                $task['run_count']++;
                $task['next_run'] = $this->calculateNextRun($task['schedule']);
                $task['last_result'] = $result;
                
                save_config($this->configFile, $config);
                $this->logExecution($task, $result);
                
                return $result;
            }
        }
        
        return ['success' => false, 'message' => 'Task not found'];
    }
    
    private function executeTask($task) {
        try {
            switch ($task['type']) {
                case 'backup_telegram':
                case 'backup_github':
                    return ['success' => true, 'message' => 'Backup task executed (integrate with existing backup code)'];
                case 'query':
                    return ['success' => true, 'message' => 'Query executed'];
                case 'cleanup':
                    return ['success' => true, 'message' => 'Cleanup completed'];
                case 'email':
                    return ['success' => true, 'message' => 'Email sent'];
                default:
                    return ['success' => false, 'message' => 'Unknown task type'];
            }
        } catch (Exception $e) {
            return ['success' => false, 'message' => $e->getMessage()];
        }
    }
    
    public function calculateNextRun($schedule) {
        $now = time();
        
        if (preg_match('/^(\d+)([mhdw])$/', $schedule, $matches)) {
            $value = (int)$matches[1];
            $unit = $matches[2];
            
            $seconds = 0;
            switch ($unit) {
                case 'm': $seconds = $value * 60; break;
                case 'h': $seconds = $value * 3600; break;
                case 'd': $seconds = $value * 86400; break;
                case 'w': $seconds = $value * 604800; break;
            }
            
            return $now + $seconds;
        }
        
        return $now + 3600;
    }
    
    public function runDueTasks() {
        $config = load_config($this->configFile);
        $tasks = $config['scheduled_tasks'] ?? [];
        $now = time();
        $executed = [];
        
        foreach ($tasks as &$task) {
            if (!$task['enabled']) continue;
            
            if ($task['next_run'] <= $now) {
                $result = $this->executeTask($task);
                
                $task['last_run'] = $now;
                $task['run_count']++;
                $task['next_run'] = $this->calculateNextRun($task['schedule']);
                $task['last_result'] = $result;
                
                $this->logExecution($task, $result);
                
                $executed[] = [
                    'task_id' => $task['id'],
                    'task_name' => $task['name'],
                    'result' => $result
                ];
            }
        }
        
        if (!empty($executed)) {
            save_config($this->configFile, $config);
        }
        
        return $executed;
    }
    
    private function logExecution($task, $result) {
        $logs = [];
        if (file_exists($this->logFile)) {
            $logs = json_decode(file_get_contents($this->logFile), true) ?? [];
        }
        
        $log = [
            'task_id' => $task['id'],
            'task_name' => $task['name'],
            'task_type' => $task['type'],
            'executed_at' => time(),
            'success' => $result['success'] ?? false,
            'message' => $result['message'] ?? '',
            'duration' => 0
        ];
        
        array_unshift($logs, $log);
        $logs = array_slice($logs, 0, 1000);
        
        file_put_contents($this->logFile, json_encode($logs, JSON_PRETTY_PRINT));
    }
    
    public function getLogs($limit = 100, $taskId = null) {
        if (!file_exists($this->logFile)) {
            return [];
        }
        
        $logs = json_decode(file_get_contents($this->logFile), true) ?? [];
        
        if ($taskId) {
            $logs = array_filter($logs, function($log) use ($taskId) {
                return $log['task_id'] === $taskId;
            });
        }
        
        return array_slice($logs, 0, $limit);
    }
    
    public function getStats() {
        $tasks = $this->getTasks();
        $logs = $this->getLogs(1000);
        
        $stats = [
            'total_tasks' => count($tasks),
            'enabled_tasks' => count(array_filter($tasks, fn($t) => $t['enabled'])),
            'disabled_tasks' => count(array_filter($tasks, fn($t) => !$t['enabled'])),
            'total_executions' => count($logs),
            'successful_executions' => count(array_filter($logs, fn($l) => $l['success'])),
            'failed_executions' => count(array_filter($logs, fn($l) => !$l['success'])),
            'tasks_by_type' => []
        ];
        
        foreach ($tasks as $task) {
            $type = $task['type'];
            if (!isset($stats['tasks_by_type'][$type])) {
                $stats['tasks_by_type'][$type] = 0;
            }
            $stats['tasks_by_type'][$type]++;
        }
        
        return $stats;
    }
}

// ===== API HASH PHP (Bcrypt) =====
// Paste tepat di sini, setelah session_start
if (isset($_GET['api']) && $_GET['api'] === 'generate_php_hash') {
    header('Content-Type: application/json');
    
    // Cek apakah user sudah login
    if (!isset($_SESSION['db_user'])) {
        echo json_encode(['success' => false, 'message' => 'Unauthorized']);
        exit;
    }

    $password = $_POST['password'] ?? '';
    
    if (empty($password)) {
        echo json_encode(['success' => false, 'message' => 'Password cannot be empty']);
        exit;
    }

    // Menggunakan PASSWORD_BCRYPT agar format sesuai ($2y$10$)
    $hash = password_hash($password, PASSWORD_BCRYPT);

    echo json_encode([
        'success' => true, 
        'hash' => $hash,
        'algo' => 'Bcrypt ($2y$)'
    ]);
    exit;
}

if (isset($_GET['api']) && $_GET['api'] === 'generate_md5') {
    header('Content-Type: application/json');
    
    // Cek apakah user sudah login
    if (!isset($_SESSION['db_user'])) {
        echo json_encode(['success' => false, 'message' => 'Unauthorized']);
        exit;
    }

    $input = $_POST['input'] ?? '';
    
    // MD5 logic
    $hash = md5($input);

    echo json_encode([
        'success' => true, 
        'hash' => $hash,
        'algo' => 'MD5'
    ]);
    exit;
}

// ... kode function get_asset_url dan seterusnya tetap ada di bawah sini ...
$configFile = __DIR__ . '/adminer.sqlite';
function get_asset_url($localPath, $cdnUrl) {
    if (file_exists(__DIR__ . '/' . $localPath)) {
        return $localPath;
    }
    return $cdnUrl;
}

function get_db_handle($path) {
    static $dbs = [];
    if (!isset($dbs[$path])) {
        $dbs[$path] = new PDO("sqlite:$path");
        $dbs[$path]->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        
        // Ensure tables exist regardless of whether the file was just created
        // This is safer if the file is 0 bytes or was created by index.php
        $dbs[$path]->exec("CREATE TABLE IF NOT EXISTS settings (key_name TEXT PRIMARY KEY, value_data TEXT)");
        $dbs[$path]->exec("CREATE TABLE IF NOT EXISTS backup_history (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, date INTEGER, file_id TEXT, message_id INTEGER, tag TEXT, size INTEGER)");
    }
    return $dbs[$path];
}

function load_config($path)
{
    if (strpos($path, '.sqlite') !== false) {
        try {
            $db = get_db_handle($path);
            $res = $db->query("SELECT key_name, value_data FROM settings");
            $data = [];
            while ($row = $res->fetch(PDO::FETCH_ASSOC)) {
                $val = json_decode($row['value_data'], true);
                $data[$row['key_name']] = (json_last_error() === JSON_ERROR_NONE) ? $val : $row['value_data'];
            }
            
            // Re-merge history into telegram array for compatibility
            $res = $db->query("SELECT * FROM backup_history ORDER BY date DESC");
            if (!isset($data['telegram'])) $data['telegram'] = [];
            $data['telegram']['history'] = $res->fetchAll(PDO::FETCH_ASSOC);
            
            return array_merge(['host' => '', 'user' => '', 'pass' => '', 'databases' => []], $data);
        } catch (Exception $e) {
            return ['host' => '', 'user' => '', 'pass' => '', 'databases' => []];
        }
    }

    if (!file_exists($path)) {
        return ['host' => '', 'user' => '', 'pass' => '', 'databases' => []];
    }
    $raw = file_get_contents($path);
    $data = json_decode($raw, true);
    if (!is_array($data)) {
        return ['host' => '', 'user' => '', 'pass' => '', 'databases' => []];
    }
    return array_merge(
        ['host' => '', 'user' => '', 'pass' => '', 'databases' => []],
        $data
    );
}

function save_config($path, $data)
{
    if (strpos($path, '.sqlite') !== false) {
        try {
            $db = get_db_handle($path);
            $db->beginTransaction();
            
            $existing = load_config($path);
            $new = array_merge($existing, $data);
            
            // Ensure databases is always an array unique
            if (isset($new['databases']) && is_array($new['databases'])) {
                $new['databases'] = array_values(array_unique($new['databases']));
            }
            
            // Sync history separately if it exists in the data
            if (isset($data['telegram']['history'])) {
                $db->exec("DELETE FROM backup_history");
                $stmt = $db->prepare("INSERT INTO backup_history (name, date, file_id, message_id, tag, size) VALUES (?, ?, ?, ?, ?, ?)");
                foreach ($data['telegram']['history'] as $h) {
                    $stmt->execute([
                        $h['name'] ?? '', $h['date'] ?? 0, $h['file_id'] ?? '',
                        $h['message_id'] ?? 0, $h['tag'] ?? '', $h['size'] ?? 0
                    ]);
                }
                unset($new['telegram']['history']);
            }

            // Sync other settings
            $stmt = $db->prepare("INSERT OR REPLACE INTO settings (key_name, value_data) VALUES (?, ?)");
            foreach ($new as $key => $value) {
                if ($key === 'telegram' && isset($value['history'])) unset($value['history']);
                $stmt->execute([$key, is_array($value) ? json_encode($value) : $value]);
            }
            
            $db->commit();
            return true;
        } catch (Exception $e) {
            if (isset($db) && $db->inTransaction()) $db->rollBack();
            throw $e; // Rethrow to show actual error
        }
    }

    $existing = load_config($path);
    $new = array_merge($existing, $data);
    if (isset($new['databases']) && is_array($new['databases'])) {
        $new['databases'] = array_values(array_unique($new['databases']));
    } else {
        $new['databases'] = [];
    }
    
    $payload = json_encode($new, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
    return file_put_contents($path, $payload) !== false;
}

// Global Config Initialization
$config = load_config($configFile);

function is_valid_db_name($name)
{
    return (bool) preg_match('/^[A-Za-z0-9_\\$\\-\\.]+$/', $name);
}

/**
 * Helper to send request to Telegram with better error handling
 */
function telegram_api_request($method, $postFields, $cfg) {
    $apiBase = rtrim($cfg['base'] ?? 'https://api.telegram.org', '/');
    $apiUrl = "$apiBase/bot" . ($cfg['token'] ?? '') . "/$method";
    
    $ch = curl_init($apiUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $postFields);
    curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
    curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 15);
    curl_setopt($ch, CURLOPT_TIMEOUT, 120);
    
    $response = curl_exec($ch);
    $errNo = curl_errno($ch);
    $errStr = curl_error($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    
    if ($errNo) {
         return ['ok' => false, 'error' => "Connection Failed ($errNo): $errStr"];
    }
    
    $data = json_decode($response, true);
    if (!$data) {
         return ['ok' => false, 'error' => "Invalid API Response: " . substr($response, 0, 100)];
    }
    
    return $data;
}

/**
 * Dumps a database (or specific tables) to a file handle using streaming.
 * Highly memory efficient for large databases (4GB+).
 */
function dump_database_to_file($pdo, $finalFile, $dbName, $tables = []) {
    return dump_database_to_files_split($pdo, $finalFile, $dbName, $tables, 0)[0] ?? false;
}

/**
 * Dumps a database to one or more files if size limits are reached.
 * Returns an array of filenames.
 */
function dump_database_to_files_split($pdo, $baseFile, $dbName, $tables = [], $maxSizeBytes = 95000000) {
    $files = [];
    $part = 1;
    $currentFile = ($maxSizeBytes > 0) ? str_replace('.sql', ".part$part.sql", $baseFile) : $baseFile;
    
    $handle = fopen($currentFile, 'w');
    if (!$handle) return [];
    $files[] = $currentFile;

    $writeHeader = function($h, $p) use ($dbName) {
        fwrite($h, "-- Adminer Lite Optimized Backup Part $p\n");
        fwrite($h, "-- Date: " . date('Y-m-d H:i:s') . "\n");
        fwrite($h, "-- Database: $dbName\n\n");
        fwrite($h, "SET FOREIGN_KEY_CHECKS=0;\n\n");
    };

    $writeHeader($handle, $part);

    try {
        if (empty($tables)) {
            $tables = $pdo->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN);
        }

        foreach ($tables as $t) {
            if ($maxSizeBytes > 0 && ftell($handle) > $maxSizeBytes) {
                fwrite($handle, "\nSET FOREIGN_KEY_CHECKS=1;\n");
                fclose($handle);
                $part++;
                $currentFile = str_replace('.sql', ".part$part.sql", $baseFile);
                $handle = fopen($currentFile, 'w');
                $files[] = $currentFile;
                $writeHeader($handle, $part);
            }

            $res = $pdo->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_ASSOC);
            fwrite($handle, "\n\nDROP TABLE IF EXISTS `$t`;\n");
            fwrite($handle, $res['Create Table'] . ";\n\n");

            $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY, false);
            $stmt = $pdo->query("SELECT * FROM `$t` shadow_unbuffered");
            
            $rowCount = 0;
            while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
                $rowCount++;
                if ($rowCount % 500 === 0 && file_exists(__DIR__ . DIRECTORY_SEPARATOR . 'temp_backups' . DIRECTORY_SEPARATOR . 'cancel_backup.flag')) {
                    fclose($handle);
                    throw new Exception("Backup cancelled by user.");
                }
                $keys = array_keys($row);
                $vals = array_map(function($v) use ($pdo) {
                    if ($v === null) return 'NULL';
                    return $pdo->quote((string)$v);
                }, array_values($row));
                
                fwrite($handle, "INSERT INTO `$t` (`" . implode("`, `", $keys) . "`) VALUES (" . implode(", ", $vals) . ");\n");
                
                if ($maxSizeBytes > 0 && $rowCount % 500 === 0 && ftell($handle) > $maxSizeBytes) {
                    fwrite($handle, "\nSET FOREIGN_KEY_CHECKS=1;\n");
                    fclose($handle);
                    $part++;
                    $currentFile = str_replace('.sql', ".part$part.sql", $baseFile);
                    $handle = fopen($currentFile, 'w');
                    $files[] = $currentFile;
                    $writeHeader($handle, $part);
                    // If we split mid-table, we should ideally re-ensure the table exists in the next part 
                    // or just rely on the user restoring parts in order. Restoration in order is the standard.
                }
            }
            $stmt->closeCursor();
            $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY, true);
        }

        fwrite($handle, "\n\nSET FOREIGN_KEY_CHECKS=1;\n");
    } catch (Exception $e) {
        if ($handle) fclose($handle);
        foreach($files as $f) @unlink($f);
        throw $e;
    }

    if ($handle) fclose($handle);
    return $files;
}

/**
 * Downloads a URL directly to a file handle to avoid memory issues.
 */
function download_url_to_file($url, $dest) {
    $fp = fopen($dest, 'w+');
    if (!$fp) return false;
    
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_FILE, $fp);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 300);
    $success = curl_exec($ch);
    curl_close($ch);
    fclose($fp);
    return $success;
}

/**
 * Streams a large SQL file into the database by executing statements one by one.
 */
function stream_sql_to_db($pdo, $filePath) {
    if (!file_exists($filePath)) return false;
    
    $handle = fopen($filePath, 'r');
    if (!$handle) return false;
    
    $query = '';
    $inString = false;
    
    $pdo->exec("SET FOREIGN_KEY_CHECKS=0");

    while (($line = fgets($handle)) !== false) {
        $trimmed = trim($line);
        if ($trimmed === '' || (substr($trimmed, 0, 2) === '--' && !$inString)) continue;
        if (substr($trimmed, 0, 2) === '/*' && substr($trimmed, -2) === '*/') continue;

        $query .= $line;
        
        // Simple check for semicolon at the end of a line, avoiding it if inside a string
        if (substr($trimmed, -1) === ';' && !$inString) {
            try {
                $pdo->exec($query);
            } catch (Exception $e) {
                // Continue on error
            }
            $query = '';
        }
    }
    
    $pdo->exec("SET FOREIGN_KEY_CHECKS=1");
    fclose($handle);
    return true;
}

/**
 * Get Database Health and Performance Stats
 */
function get_db_health($pdo, $dbName, $dbMode) {
    if (!$pdo) return null;
    $stats = [];
    try {
        if ($dbMode === 'sql') {
            $stmt = $pdo->query("SELECT VERSION() as ver, 
                                (SELECT count(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$dbName') as tables_count,
                                (SELECT SUM(TABLE_ROWS) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$dbName') as total_rows,
                                (SELECT SUM(DATA_LENGTH) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$dbName') as data_size,
                                (SELECT SUM(INDEX_LENGTH) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$dbName') as index_size");
            $res = $stmt->fetch(PDO::FETCH_ASSOC);
            if ($res && !empty($res['tables_count'])) {
                 $stats = $res;
            } else {
                // Fallback for restricted informational_schema environments (like InfinityFree)
                $status = $pdo->query("SHOW TABLE STATUS FROM `$dbName`")->fetchAll(PDO::FETCH_ASSOC);
                $stats['tables_count'] = count($status);
                $stats['total_rows'] = 0;
                $stats['data_size'] = 0;
                $stats['index_size'] = 0;
                $stats['ver'] = $pdo->query("SELECT VERSION()")->fetchColumn();
                foreach ($status as $row) {
                    $stats['total_rows'] += $row['Rows'];
                    $stats['data_size'] += $row['Data_length'];
                    $stats['index_size'] += $row['Index_length'];
                }
            }
            
            $statusStmt = $pdo->query("SHOW STATUS LIKE 'Uptime'");
            $stats['uptime'] = $statusStmt->fetch(PDO::FETCH_ASSOC)['Value'] ?? '0';
            
            $connStmt = $pdo->query("SHOW STATUS LIKE 'Threads_connected'");
            $stats['connections'] = $connStmt->fetch(PDO::FETCH_ASSOC)['Value'] ?? '0';
        } else if ($dbMode === 'sqlite') {
             $stats['tables_count'] = $pdo->query("SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")->fetchColumn();
             $stats['total_rows'] = 'N/A';
             $stats['data_size'] = file_exists($_SESSION['sqlite_file'] ?? '') ? filesize($_SESSION['sqlite_file']) : 0;
             $stats['index_size'] = 0;
             $stats['ver'] = $pdo->query("select sqlite_version()")->fetchColumn();
             $stats['uptime'] = 'N/A';
        }
    } catch (Exception $e) { }
    
    // Ensure numeric defaults to prevent errors in report
    return [
        'ver' => $stats['ver'] ?? 'Unknown',
        'tables_count' => $stats['tables_count'] ?? 0,
        'total_rows' => $stats['total_rows'] ?? 0,
        'data_size' => $stats['data_size'] ?? 0,
        'index_size' => $stats['index_size'] ?? 0,
        'uptime' => $stats['uptime'] ?? '0',
        'connections' => $stats['connections'] ?? '0'
    ];
}



/**
 * Generate Smart Fake Data
 */
function generate_fake_data($type, $index = 0, $dbType = '') {
    $names = ['James Smith', 'Maria Garcia', 'Robert Hernandez', 'David Miller', 'Linda Martinez', 'Michael Davis', 'Sarah Taylor', 'William Lopez', 'Angela Wilson', 'Daniel Anderson'];
    $domains = ['example.com', 'test.io', 'mail.net', 'company.org', 'web.com'];
    $cities = ['New York', 'Los Angeles', 'Chicago', 'Houston', 'Phoenix', 'London', 'Berlin', 'Paris', 'Tokyo', 'Jakarta'];
    $texts = ['Lorem ipsum dolor sit amet.', 'Quick brown fox jumps over lazy dog.', 'Data integrity is very important.', 'Fastest database manager in the west.', 'This is a sample generated text.'];
    
    $dbType = strtolower($dbType);
    switch (strtolower((string)$type)) {
        case 'name': return $names[rand(0, count($names)-1)];
        case 'username': return strtolower(explode(' ', $names[rand(0, count($names)-1)])[0]) . rand(10, 99);
        case 'email': 
            $n = strtolower(str_replace(' ', '.', $names[rand(0, count($names)-1)]));
            return $n . rand(10, 99) . '@' . $domains[rand(0, count($domains)-1)];
        case 'phone': return '08' . rand(11, 19) . '-' . rand(1000, 9999) . '-' . rand(1000, 9999);
        case 'city': return $cities[rand(0, count($cities)-1)];
        case 'text': return $texts[rand(0, count($texts)-1)];
        case 'role': return 'user'; 
        case 'status': return (rand(0, 10) > 2) ? 'active' : 'inactive';
        case 'number': 
            $max = 1000;
            if (strpos($dbType, 'tinyint') !== false) $max = (strpos($dbType, 'unsigned') !== false) ? 255 : 127;
            elseif (strpos($dbType, 'smallint') !== false) $max = (strpos($dbType, 'unsigned') !== false) ? 65535 : 32767;
            return rand(1, $max);
        case 'boolean': return rand(0, 1);
        case 'date': return date('Y-m-d', strtotime('-' . rand(0, 365) . ' days'));
        case 'datetime': return date('Y-m-d H:i:s', strtotime('-' . rand(0, 365) . ' days -' . rand(0, 86400) . ' seconds'));
        case 'password': return password_hash('password123', PASSWORD_BCRYPT);
        default: return 'Value ' . ($index + 1);
    }
}

/**
 * Guess Fake Data Type based on Column Name and DB Type
 */
function guess_fake_type($name, $dbType) {
    $name = strtolower((string)$name);
    $dbType = strtolower((string)$dbType);
    
    if (strpos($name, 'email') !== false) return 'email';
    if (strpos($name, 'user') !== false || strpos($name, 'username') !== false) return 'username';
    if (strpos($name, 'name') !== false) return 'name';
    if (strpos($name, 'role') !== false) return 'role';
    if (strpos($name, 'status') !== false) return 'status';
    if (strpos($name, 'phone') !== false || strpos($name, 'tel') !== false) return 'phone';
    if (strpos($name, 'pass') !== false) return 'password';
    if (strpos($name, 'city') !== false) return 'city';
    
    if (strpos($dbType, 'int') !== false) return 'number';
    if (strpos($dbType, 'date') !== false) return 'date';
    if (strpos($dbType, 'text') !== false) return 'text';
    if (strpos($dbType, 'bool') !== false) return 'boolean';
    
    return 'default';
}

/**
 * Smart table name guesser for convention-based FK
 * Tries multiple variations and checks if table exists
 */
function guess_fk_table_name($columnName, $pdo, $tables = []) {
    // Remove '_id' suffix
    $baseName = substr($columnName, 0, -3);
    
    // Build list of possible table names
    $candidates = [];
    
    // 1. Exact match (e.g., google_id -> google)
    $candidates[] = $baseName;
    
    // 2. Plural form (e.g., user_id -> users)
    $candidates[] = $baseName . 's';
    
    // 3. Handle irregular plurals
    $irregularPlurals = [
        'person' => 'people',
        'child' => 'children',
        'man' => 'men',
        'woman' => 'women',
        'tooth' => 'teeth',
        'foot' => 'feet',
        'mouse' => 'mice',
        'goose' => 'geese',
        'category' => 'categories',
        'company' => 'companies',
        'city' => 'cities',
    ];
    
    if (isset($irregularPlurals[$baseName])) {
        $candidates[] = $irregularPlurals[$baseName];
    }
    
    // 4. Handle words ending in 'y' (e.g., category -> categories)
    if (substr($baseName, -1) === 'y' && !in_array(substr($baseName, -2, 1), ['a', 'e', 'i', 'o', 'u'])) {
        $candidates[] = substr($baseName, 0, -1) . 'ies';
    }
    
    // 5. Handle words ending in 's', 'x', 'z', 'ch', 'sh' (e.g., box -> boxes)
    if (preg_match('/(s|x|z|ch|sh)$/i', $baseName)) {
        $candidates[] = $baseName . 'es';
    }
    
    // Check if we have a tables array (from current session)
    if (!empty($tables)) {
        $tableNames = array_map(function($t) {
            return strtolower($t['Name'] ?? $t['TABLE_NAME'] ?? '');
        }, $tables);
        
        foreach ($candidates as $candidate) {
            if (in_array(strtolower($candidate), $tableNames)) {
                return $candidate;
            }
        }
    }
    
    // If PDO available, check database directly
    if ($pdo) {
        try {
            foreach ($candidates as $candidate) {
                $stmt = $pdo->prepare("SHOW TABLES LIKE ?");
                $stmt->execute([$candidate]);
                if ($stmt->fetch()) {
                    return $candidate;
                }
            }
        } catch (Exception $e) {
            // Fallback to first candidate if query fails
        }
    }
    
    // Fallback: return first candidate (most likely)
    return $candidates[0] ?? $baseName;
}

