// ===== DB CONNECTION (IF LOGGED IN) =====
$is_sql_mode = (($_SESSION['db_mode'] ?? 'sql') === 'sql');
$databases = []; // List of databases
$sqlResults = [];
$lastResultSet = null;
$hostProfile = detect_host_profile($dbConfig['host'] ?? $_SESSION['db_host'] ?? '');

if ($is_sql_mode && $is_logged_in) {
    try {
        // Selalu buat koneksi dasar (tanpa database) dulu
        $dsn = "mysql:host={$_SESSION['db_host']};charset=utf8mb4";
        
        $pdo = new PDO(
            $dsn,
            $_SESSION['db_user'],
            $_SESSION['db_pass'],
            [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_TIMEOUT => 5
            ]
        );
        
        // Apply Foreign Key Checks setting from session
        if (isset($_SESSION['fk_checks'])) {
            $fk_val = (int)$_SESSION['fk_checks'];
            $pdo->exec("SET FOREIGN_KEY_CHECKS = $fk_val");
        }
        
        // Fetch semua database yang tersedia
        try {
            $stmt = $pdo->query("SHOW DATABASES");
            $databases_from_server = $stmt->fetchAll(PDO::FETCH_COLUMN);
            
            // Prioritaskan database dari server
            if (!empty($databases_from_server)) {
                $databases = $databases_from_server;
            } elseif (!empty($user_defined_databases)) {
                // Fallback ke user defined databases
                $databases = $user_defined_databases;
            }
            
            // Jika ada database yang dipilih di session, validasi
            if (!empty($_SESSION['db_name']) && !in_array($_SESSION['db_name'], $databases)) {
                // Database tidak valid, reset
                $_SESSION['db_name'] = '';
                $hasSelectedDatabase = false;
                $DB_NAME = '';
            }
            
        } catch (Exception $e) {
            $databases = $user_defined_databases;
        }
        
        // Jika sudah ada database yang dipilih, reconnect dengan database tersebut
        if ($hasSelectedDatabase && !empty($_SESSION['db_name'])) {
            try {
                $dsn_with_db = "mysql:host={$_SESSION['db_host']};dbname={$_SESSION['db_name']};charset=utf8mb4";
                $pdo = new PDO(
                    $dsn_with_db,
                    $_SESSION['db_user'],
                    $_SESSION['db_pass'],
                    [
                        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                        PDO::ATTR_TIMEOUT => 5
                    ]
                );
                
                // Apply Foreign Key Checks setting from session
                if (isset($_SESSION['fk_checks'])) {
                    $fk_val = (int)$_SESSION['fk_checks'];
                    $pdo->exec("SET FOREIGN_KEY_CHECKS = $fk_val");
                }
            } catch (Exception $e) {
                error_log("Adminer reconnect with DB error: " . $e->getMessage());
                $_SESSION['db_name'] = '';
                $hasSelectedDatabase = false;
                $DB_NAME = '';
            }
        }
    } catch (Exception $e) {
        session_destroy();
        die("Database Connection Error: " . htmlspecialchars($e->getMessage()));
    }
} elseif (($_SESSION['db_mode'] ?? 'sql') === 'sqlite') {
    $hasSelectedDatabase = true;
    $DB_NAME = $_SESSION['db_name'] ?? 'SQLite';
}

// ===== HELPER FUNCTIONS =====
function formatSize($bytes) {
    $units = ['B', 'KB', 'MB', 'GB', 'TB'];
    $bytes = max($bytes, 0);
    $pow = floor(($bytes ? log($bytes) : 0) / log(1024));
    $pow = min($pow, count($units) - 1);
    $bytes /= pow(1024, $pow);
    return round($bytes, 2) . ' ' . $units[$pow];
}

function getPrimaryKey($pdo, $table) {
    try {
        $stmt = $pdo->prepare("SHOW KEYS FROM `$table` WHERE Key_name = 'PRIMARY'");
        $stmt->execute();
        $res = $stmt->fetch();
        return $res ? $res['Column_name'] : null;
    } catch (Exception $e) { return null; }
}

function redirect($url) {
    header("Location: $url");
    exit;
}

function sanitizeDiagramId($name) {
    $sanitized = preg_replace('/[^A-Za-z0-9_]/', '_', $name);
    if ($sanitized === '' || is_numeric($sanitized[0])) {
        $sanitized = 'tbl_' . substr(md5($name), 0, 6);
    }
    return $sanitized;
}

function mermaid_identifier($name) {
    $id = preg_replace('/[^A-Za-z0-9_]/', '_', $name);
    if ($id === '' || is_numeric($id[0])) {
        $id = 'tbl_' . substr(md5($name), 0, 6);
    }
    return $id;
}

function mermaid_datatype($type) {
    $upper = strtoupper($type);
    $upper = preg_replace('/[^A-Z0-9]/', '_', $upper);
    return $upper ?: 'TEXT';
}

function mermaid_column_name($name) {
    $col = preg_replace('/[^A-Za-z0-9_]/', '_', $name);
    if ($col === '' || is_numeric($col[0])) {
        $col = 'col_' . substr(md5($name), 0, 6);
    }
    return $col;
}

function mermaid_column_suffix($col) {
    $suffix = [];
    if (!empty($col['Key'])) {
        if ($col['Key'] === 'PRI') $suffix[] = 'PK';
        elseif ($col['Key'] === 'UNI') $suffix[] = 'UQ';
        elseif ($col['Key'] === 'MUL') $suffix[] = 'IDX';
    }
    if (!empty($col['Null']) && $col['Null'] === 'NO') {
        $suffix[] = 'NOT_NULL';
    }
    if (!empty($col['Extra'])) {
        $suffix[] = strtoupper(str_replace(' ', '_', $col['Extra']));
    }
    return $suffix ? ' ' . implode(' ', $suffix) : '';
}

function mermaid_relation_label($fromCol, $toCol) {
    $label = $fromCol . '_to_' . $toCol;
    return preg_replace('/[^A-Za-z0-9_]/', '_', $label);
}

function plantuml_encode($text) {
    $data = mb_convert_encoding($text, 'UTF-8', 'ISO-8859-1');
    $compressed = gzdeflate($data);
    return plantuml_encode64($compressed);
}

function plantuml_encode64($data) {
    $alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";
    $out = '';
    $len = strlen($data);
    for ($i = 0; $i < $len; $i += 3) {
        if ($i + 2 < $len) {
            $b1 = ord($data[$i]);
            $b2 = ord($data[$i + 1]);
            $b3 = ord($data[$i + 2]);
            $out .= $alphabet[$b1 >> 2];
            $out .= $alphabet[(($b1 & 0x3) << 4) | ($b2 >> 4)];
            $out .= $alphabet[(($b2 & 0xF) << 2) | ($b3 >> 6)];
            $out .= $alphabet[$b3 & 0x3F];
        } elseif ($i + 1 < $len) {
            $b1 = ord($data[$i]);
            $b2 = ord($data[$i + 1]);
            $out .= $alphabet[$b1 >> 2];
            $out .= $alphabet[(($b1 & 0x3) << 4) | ($b2 >> 4)];
            $out .= $alphabet[(($b2 & 0xF) << 2)];
        } else {
            $b1 = ord($data[$i]);
            $out .= $alphabet[$b1 >> 2];
            $out .= $alphabet[(($b1 & 0x3) << 4)];
        }
    }
    return $out;
}

function split_sql_statements($sql) {
    $statements = [];
    $current = '';
    $inString = false;
    $stringChar = '';
    $inLineComment = false;
    $inBlockComment = false;
    $length = strlen($sql);

    for ($i = 0; $i < $length; $i++) {
        $char = $sql[$i];
        $next = $i + 1 < $length ? $sql[$i + 1] : '';

        if ($inLineComment) {
            if ($char === "\n") {
                $inLineComment = false;
            }
            continue;
        }

        if ($inBlockComment) {
            if ($char === '*' && $next === '/') {
                $inBlockComment = false;
                $i++;
            }
            continue;
        }

        if (!$inString) {
            if ($char === '-' && $next === '-') {
                $inLineComment = true;
                $i++;
                continue;
            }
            if ($char === '#') {
                $inLineComment = true;
                continue;
            }
            if ($char === '/' && $next === '*') {
                $inBlockComment = true;
                $i++;
                continue;
            }
        }

        if ($char === '\\' && $inString) {
            $current .= $char;
            if ($next !== '') {
                $current .= $next;
                $i++;
            }
            continue;
        }

        if ($char === '\'' || $char === '"' || $char === '`') {
            if ($inString && $char === $stringChar) {
                $inString = false;
                $stringChar = '';
            } elseif (!$inString) {
                $inString = true;
                $stringChar = $char;
            }
            $current .= $char;
            continue;
        }

        if ($char === ';' && !$inString) {
            if (trim($current) !== '') {
                $statements[] = trim($current);
            }
            $current = '';
            continue;
        }

        $current .= $char;
    }

    if (trim($current) !== '') {
        $statements[] = trim($current);
    }

    return $statements;
}

function is_resultset_statement($statement) {
    return (bool) preg_match('/^(SELECT|SHOW|DESCRIBE|EXPLAIN)\\b/i', ltrim($statement));
}

/**
 * Order tables based on foreign-key dependencies.
 * By default parents come first; when $childFirst is true result is reversed so children precede parents.
 */
function order_tables_by_dependencies(PDO $pdo, array $tables, $schema, $childFirst = false) {
    $tables = array_values(array_unique(array_filter($tables)));
    if (count($tables) <= 1) {
        return $tables;
    }

    $placeholders = implode(',', array_fill(0, count($tables), '?'));
    $params = array_merge([$schema], $tables);
    $sql = "
        SELECT TABLE_NAME, REFERENCED_TABLE_NAME
        FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE
        WHERE TABLE_SCHEMA = ?
          AND REFERENCED_TABLE_NAME IS NOT NULL
          AND TABLE_NAME IN ($placeholders)
    ";
    try {
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
    } catch (Exception $e) {
        return $tables;
    }

    $set = array_fill_keys($tables, true);
    $graph = [];
    $inDegree = array_fill_keys($tables, 0);

    foreach ($rows as $row) {
        $child = $row['TABLE_NAME'];
        $parent = $row['REFERENCED_TABLE_NAME'];
        if (!isset($set[$child]) || !isset($set[$parent])) {
            continue;
        }
        $graph[$parent][] = $child;
        $inDegree[$child] += 1;
    }

    $queue = [];
    foreach ($inDegree as $tbl => $deg) {
        if ($deg === 0) {
            $queue[] = $tbl;
        }
    }

    $ordered = [];
    while ($queue) {
        $tbl = array_shift($queue);
        $ordered[] = $tbl;
        if (!empty($graph[$tbl])) {
            foreach ($graph[$tbl] as $child) {
                $inDegree[$child] -= 1;
                if ($inDegree[$child] === 0) {
                    $queue[] = $child;
                }
            }
        }
    }

    if (count($ordered) !== count($tables)) {
        return $tables;
    }

    if ($childFirst) {
        $ordered = array_reverse($ordered);
    }
    return $ordered;
}

// ===== API REQUEST HANDLER =====
$requestUri = $_SERVER['REQUEST_URI'] ?? '';
$requestMethod = $_SERVER['REQUEST_METHOD'] ?? 'GET';

// Check if this is an API request
if (strpos($requestUri, '/api/') !== false) {
    header('Content-Type: application/json');
    header('Access-Control-Allow-Origin: *');
    header('Access-Control-Allow-Methods: GET, POST, PUT, PATCH, DELETE, OPTIONS');
    header('Access-Control-Allow-Headers: Content-Type, X-API-Key');
    
    if ($requestMethod === 'OPTIONS') {
        http_response_code(200);
        exit;
    }
    
    $apiKey = $_SERVER['HTTP_X_API_KEY'] ?? '';
    $pdo = $_SESSION['pdo'] ?? null;
    $dbMode = $_SESSION['db_mode'] ?? 'sql';
    
    $api = new APIGenerator($configFile, $pdo, $dbMode);
    
    $keyConfig = $api->validateApiKey($apiKey);
    if (!$keyConfig) {
        http_response_code(401);
        echo json_encode(['success' => false, 'error' => 'Invalid or rate-limited API key']);
        exit;
    }
    
    $path = parse_url($requestUri, PHP_URL_PATH);
    $pathParts = explode('/', trim($path, '/'));
    
    $apiIndex = array_search('api', $pathParts);
    $table = $pathParts[$apiIndex + 1] ?? null;
    $id = $pathParts[$apiIndex + 2] ?? null;
    
    if (!$table) {
        http_response_code(400);
        echo json_encode(['success' => false, 'error' => 'Table name required']);
        exit;
    }
    
    $data = [];
    if (in_array($requestMethod, ['POST', 'PUT', 'PATCH'])) {
        $rawData = file_get_contents('php://input');
        $data = json_decode($rawData, true) ?? [];
    } else if ($requestMethod === 'GET') {
        $data = $_GET;
    }
    
    $response = $api->handleRequest($table, $requestMethod, $id, $data);
    
    http_response_code($response['success'] ? 200 : 400);
    echo json_encode($response, JSON_PRETTY_PRINT);
    exit;
}

// ===== API MANAGEMENT HANDLER =====
if (isset($_GET['api']) && $_GET['api'] === 'api_manager') {
    header('Content-Type: application/json');
    
    $pdo = $_SESSION['pdo'] ?? null;
    $dbMode = $_SESSION['db_mode'] ?? 'sql';
    
    $api = new APIGenerator($configFile, $pdo, $dbMode);
    
    $action = $_POST['action'] ?? $_GET['action'] ?? '';
    
    try {
        switch ($action) {
            case 'get_keys':
                $config = load_config($configFile);
                echo json_encode(['success' => true, 'keys' => $config['api_keys'] ?? []]);
                break;
                
            case 'create_key':
                $config = load_config($configFile);
                if (!isset($config['api_keys'])) {
                    $config['api_keys'] = [];
                }
                
                $customKey = $_POST['custom_key'] ?? '';
                $keyVal = $customKey ?: bin2hex(random_bytes(32));
                
                $key = [
                    'id' => uniqid('key_'),
                    'key' => $keyVal,
                    'name' => $_POST['name'] ?? 'API Key',
                    'rate_limit' => (int)($_POST['rate_limit'] ?? 1000),
                    'enabled' => true,
                    'created_at' => time()
                ];
                
                $config['api_keys'][] = $key;
                save_config($configFile, $config);
                
                echo json_encode(['success' => true, 'key' => $key]);
                break;
                
            case 'update_key':
                $config = load_config($configFile);
                $keyId = $_POST['key_id'] ?? '';
                if (isset($config['api_keys'])) {
                    foreach ($config['api_keys'] as &$k) {
                        if ($k['id'] === $keyId) {
                            $k['name'] = $_POST['name'] ?? $k['name'];
                            $k['key'] = $_POST['key'] ?? $k['key'];
                            $k['rate_limit'] = (int)($_POST['rate_limit'] ?? $k['rate_limit']);
                            break;
                        }
                    }
                    save_config($configFile, $config);
                }
                echo json_encode(['success' => true]);
                break;
                
            case 'delete_key':
                $keyId = $_POST['key_id'] ?? '';
                $config = load_config($configFile);
                $keys = $config['api_keys'] ?? [];
                
                $config['api_keys'] = array_filter($keys, fn($k) => $k['id'] !== $keyId);
                $config['api_keys'] = array_values($config['api_keys']);
                
                save_config($configFile, $config);
                echo json_encode(['success' => true]);
                break;
                
            case 'toggle_key':
                $keyId = $_POST['key_id'] ?? '';
                $config = load_config($configFile);
                $keys = $config['api_keys'] ?? [];
                
                foreach ($keys as &$key) {
                    if ($key['id'] === $keyId) {
                        $key['enabled'] = !$key['enabled'];
                        break;
                    }
                }
                
                $config['api_keys'] = $keys;
                save_config($configFile, $config);
                echo json_encode(['success' => true]);
                break;
                
            case 'get_logs':
                $limit = (int)($_GET['limit'] ?? 100);
                $logs = $api->getLogs($limit);
                echo json_encode(['success' => true, 'logs' => $logs]);
                break;
                
            case 'get_stats':
                $stats = $api->getStats();
                echo json_encode(['success' => true, 'stats' => $stats]);
                break;
                
            case 'get_docs':
                $tables = [];
                if ($pdo && $dbMode === 'sql') {
                    $stmt = $pdo->query("SHOW TABLES");
                    $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);
                }
                $docs = $api->generateDocs($tables);
                echo json_encode(['success' => true, 'docs' => $docs]);
                break;
                
            default:
                echo json_encode(['success' => false, 'message' => 'Unknown action']);
        }
    } catch (Exception $e) {
        echo json_encode(['success' => false, 'message' => $e->getMessage()]);
    }
    
    exit;
}

// ===== SCHEDULER HANDLER =====
if (isset($_GET['api']) && $_GET['api'] === 'scheduler') {
    header('Content-Type: application/json');
    
    $scheduler = new TaskScheduler($configFile);
    
    $action = $_POST['action'] ?? $_GET['action'] ?? '';
    
    try {
        switch ($action) {
            case 'get_tasks':
                echo json_encode(['success' => true, 'tasks' => $scheduler->getTasks()]);
                break;
                
            case 'add_task':
                $task = [
                    'name' => $_POST['name'] ?? '',
                    'type' => $_POST['type'] ?? '',
                    'schedule' => $_POST['schedule'] ?? '1h',
                    'database' => $_POST['database'] ?? '',
                    'query' => $_POST['query'] ?? '',
                    'table' => $_POST['table'] ?? '',
                    'condition' => $_POST['condition'] ?? '',
                    'email_to' => $_POST['email_to'] ?? '',
                    'email_subject' => $_POST['email_subject'] ?? '',
                    'email_body' => $_POST['email_body'] ?? '',
                    'notify_on_success' => isset($_POST['notify_on_success']),
                    'notify_on_failure' => isset($_POST['notify_on_failure']),
                ];
                
                $result = $scheduler->addTask($task);
                echo json_encode(['success' => true, 'task' => $result]);
                break;
                
            case 'update_task':
                $taskId = $_POST['task_id'] ?? '';
                $updates = json_decode($_POST['updates'] ?? '{}', true);
                $result = $scheduler->updateTask($taskId, $updates);
                echo json_encode(['success' => true, 'task' => $result]);
                break;
                
            case 'delete_task':
                $taskId = $_POST['task_id'] ?? '';
                $scheduler->deleteTask($taskId);
                echo json_encode(['success' => true]);
                break;
                
            case 'toggle_task':
                $taskId = $_POST['task_id'] ?? '';
                $result = $scheduler->toggleTask($taskId);
                echo json_encode(['success' => true, 'task' => $result]);
                break;
                
            case 'run_task':
                $taskId = $_POST['task_id'] ?? '';
                $result = $scheduler->runTask($taskId);
                echo json_encode($result);
                break;
                
            case 'run_due_tasks':
                $results = $scheduler->runDueTasks();
                echo json_encode(['success' => true, 'executed' => $results]);
                break;
                
            case 'get_logs':
                $limit = (int)($_GET['limit'] ?? 100);
                $taskId = $_GET['task_id'] ?? null;
                $logs = $scheduler->getLogs($limit, $taskId);
                echo json_encode(['success' => true, 'logs' => $logs]);
                break;
                
            case 'get_stats':
                $stats = $scheduler->getStats();
                echo json_encode(['success' => true, 'stats' => $stats]);
                break;
                
            default:
                echo json_encode(['success' => false, 'message' => 'Unknown action']);
        }
    } catch (Exception $e) {
        echo json_encode(['success' => false, 'message' => $e->getMessage()]);
    }
    
    exit;
}

// ===== CRON RUNNER (Web Cron) =====
if (isset($_GET['cron']) && isset($_GET['key'])) {
    $secretKey = 'your_secret_key_here'; // Change this in production!
    $providedKey = $_GET['key'] ?? '';
    
    if ($providedKey !== $secretKey) {
        http_response_code(403);
        die('Forbidden');
    }
    
    header('Content-Type: text/plain');
    
    $scheduler = new TaskScheduler($configFile);
    
    echo "[" . date('Y-m-d H:i:s') . "] Running scheduled tasks...\n";
    
    $results = $scheduler->runDueTasks();
    
    if (empty($results)) {
        echo "No tasks due to run.\n";
    } else {
        echo "Executed " . count($results) . " task(s):\n";
        foreach ($results as $result) {
            $status = $result['result']['success'] ? 'SUCCESS' : 'FAILED';
            echo "  - {$result['task_name']}: $status\n";
            if (!$result['result']['success']) {
                echo "    Error: {$result['result']['message']}\n";
            }
        }
    }
    
    echo "Done.\n";
    exit;
}

// ===== AJAX HANDLERS (GET/POST) =====
if ($is_logged_in && (isset($_GET['action']) || isset($_POST['action']))) {
    $action = $_POST['action'] ?? $_GET['action'] ?? '';
    $dbMode = $_SESSION['db_mode'] ?? 'sql';
    
    // --- EXPORT DASHBOARD ---
    if ($action === 'export_dash') {
        while (ob_get_level()) ob_end_clean();
        $db = $_SESSION['db_name'] ?? '';
        $config = load_config($configFile);
        $export = [
            'widgets' => array_values(array_filter($config['widgets'] ?? [], fn($w) => ($w['db'] ?? '') === $db)),
            'charts' => array_values(array_filter($config['charts'] ?? [], fn($c) => ($c['db'] ?? '') === $db))
        ];
        
        if (isset($_GET['json']) || (isset($_SERVER['HTTP_X_REQUESTED_WITH']) && $_SERVER['HTTP_X_REQUESTED_WITH'] == 'XMLHttpRequest')) {
            header('Content-Type: application/json');
            echo json_encode($export);
        } else {
            header('Content-Type: application/json');
            header('Content-Disposition: attachment; filename="dashboard_export_'.$db.'.json"');
            echo json_encode($export, JSON_PRETTY_PRINT);
        }
        exit;
    }
    // --- IMPORT DASHBOARD ---
    elseif ($action === 'import_dash') {
        $json = $_POST['data'] ?? '';
        $data = json_decode($json, true);
        if ($data) {
            $config = load_config($configFile);
            $db = $_SESSION['db_name'] ?? '';
            
            if (isset($data['widgets'])) {
                foreach ($data['widgets'] as $w) {
                    $w['id'] = uniqid(); // New IDs to avoid collision
                    $w['db'] = $db;
                    $config['widgets'][] = $w;
                }
            }
            if (isset($data['charts'])) {
                foreach ($data['charts'] as $c) {
                    $c['id'] = uniqid();
                    $c['db'] = $db;
                    $config['charts'][] = $c;
                }
            }
            save_config($configFile, $config);
            echo json_encode(['success' => true]);
        } else {
            echo json_encode(['success' => false, 'message' => 'Invalid JSON data']);
        }
        exit;
    }
    
    // --- SAVE DASHBOARD ORDER ---
    elseif ($action === 'save_order') {
        $type = $_POST['type'] ?? ''; // 'widgets' or 'charts'
        $order = $_POST['order'] ?? [];
        if ($type && !empty($order)) {
            $config = load_config($configFile);
            $db = $_SESSION['db_name'] ?? '';
            
            // Reorder the specific type while keeping items from other DBs
            $items = $config[$type] ?? [];
            $otherItems = array_filter($items, fn($i) => ($i['db'] ?? '') !== $db);
            $currentDbItems = array_filter($items, fn($i) => ($i['db'] ?? '') === $db);
            
            // Map current items for quick lookup
            $itemMap = [];
            foreach ($currentDbItems as $i) $itemMap[$i['id']] = $i;
            
            $newOrderedList = [];
            foreach ($order as $id) {
                if (isset($itemMap[$id])) {
                    $newOrderedList[] = $itemMap[$id];
                    unset($itemMap[$id]);
                }
            }
            // Append any missed items
            foreach ($itemMap as $i) $newOrderedList[] = $i;
            
            $config[$type] = array_merge($otherItems, $newOrderedList);
            save_config($configFile, $config);
            echo json_encode(['success' => true]);
        } else {
            echo json_encode(['success' => false, 'message' => 'Invalid data']);
        }
        exit;
    }
    
    // --- RUN WIDGET ACTION ---
    elseif ($action === 'run_widget_action') {
        $id = $_POST['id'] ?? '';
        $config = load_config($configFile);
        $widget = null;
        foreach ($config['widgets'] ?? [] as $w) {
            if ($w['id'] == $id) { $widget = $w; break; }
        }
        
        if ($widget && !empty($widget['sql']) && isset($pdo)) {
            try {
                $count = $pdo->exec($widget['sql']);
                echo json_encode(['success' => true, 'message' => "Action executed successfully! $count rows affected."]);
            } catch (Exception $e) {
                echo json_encode(['success' => false, 'message' => $e->getMessage()]);
            }
        } else {
            echo json_encode(['success' => false, 'message' => 'Widget or SQL not found']);
        }
        exit;
    }
    
    elseif ($action === 'save_visualizer_pos') {
        @error_reporting(0);
        $tableName = $_POST['table'] ?? '';
        $left = $_POST['left'] ?? 0;
        $top = $_POST['top'] ?? 0;
        if ($tableName) {
            $cfg = load_config($configFile);
            $cfg['visualizer_pos'][$tableName] = ['left' => (int)$left, 'top' => (int)$top];
            save_config($configFile, $cfg);
            echo json_encode(['success' => true]);
        }
        exit;
    }
    
    elseif ($action === 'save_all_visualizer_pos') {
        @error_reporting(0);
        $positions = $_POST['positions'] ?? [];
        if (is_array($positions)) {
            $cfg = load_config($configFile);
            foreach ($positions as $tbl => $pos) {
                $cfg['visualizer_pos'][$tbl] = ['left' => (int)($pos['left'] ?? 0), 'top' => (int)($pos['top'] ?? 0)];
            }
            save_config($configFile, $cfg);
            echo json_encode(['success' => true]);
        }
        exit;
    }
    
    // --- GET COLUMNS AJAX ---
    elseif ($action === 'get_columns') {
        @error_reporting(0);
        @ini_set('display_errors', 0);
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        
        $t = $_POST['table'] ?? $_GET['table'] ?? '';
        $result = ['columns' => [], 'fks' => []];
        
        if ($t) {
            try {
                if ($dbMode === 'json' && isset($jsonDb)) {
                    $data = $jsonDb->select($t, [], null, 'DESC', 1);
                    if (!empty($data)) {
                        foreach ($data[0] as $name => $val) {
                            $result['columns'][] = [
                                'Field' => $name,
                                'Type' => gettype($val),
                                'Key' => $name === 'id' ? 'PRI' : ''
                            ];
                        }
                    }
                } elseif (isset($pdo)) {
                    if ($dbMode === 'sqlite') {
                        $stmt = $pdo->query("PRAGMA table_info(`$t`)");
                        foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
                            $result['columns'][] = [
                                'Field' => $row['name'],
                                'Type' => $row['type'],
                                'Key' => $row['pk'] ? 'PRI' : ''
                            ];
                        }
                        // Get SQLite FKs
                        $fkStmt = $pdo->query("PRAGMA foreign_key_list(`$t`)");
                        foreach($fkStmt->fetchAll(PDO::FETCH_ASSOC) as $fk) {
                            $result['fks'][$fk['from']] = [
                                'table' => $fk['table'],
                                'column' => $fk['to']
                            ];
                        }
                    } else {
                        // MySQL
                        $stmt = $pdo->query("DESCRIBE `$t`");
                        $result['columns'] = $stmt->fetchAll(PDO::FETCH_ASSOC);
                        
                        // Get MySQL FKs
                        $dbName = $_SESSION['db_name'] ?? '';
                        $fkSql = "SELECT COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME 
                                 FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE 
                                 WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? AND REFERENCED_TABLE_NAME IS NOT NULL";
                        $fkStmt = $pdo->prepare($fkSql);
                        $fkStmt->execute([$dbName, $t]);
                        foreach($fkStmt->fetchAll(PDO::FETCH_ASSOC) as $fk) {
                            $result['fks'][$fk['COLUMN_NAME']] = [
                                'table' => $fk['REFERENCED_TABLE_NAME'],
                                'column' => $fk['REFERENCED_COLUMN_NAME']
                            ];
                    }
                }
            }
        } catch (Exception $e) {}
    }
        
        // Smart Guessing for Convention-based FKs (e.g. user_id -> users)
        if (isset($pdo)) {
            // Get all tables for comparison
            static $allTablesForGuessing = null;
            if ($allTablesForGuessing === null) {
                try {
                    if ($dbMode === 'sqlite') {
                        $st = $pdo->query("SELECT name as Name FROM sqlite_master WHERE type='table'");
                        $allTablesForGuessing = $st->fetchAll(PDO::FETCH_ASSOC);
                    } else {
                        $st = $pdo->query("SHOW TABLES");
                        $raw = $st->fetchAll(PDO::FETCH_COLUMN);
                        $allTablesForGuessing = array_map(fn($n) => ['Name' => $n], $raw);
                    }
                } catch (Exception $e) { $allTablesForGuessing = []; }
            }
            
            foreach ($result['columns'] as $col) {
                $colName = $col['Field'] ?? $col['name'] ?? '';
                if ($colName && !isset($result['fks'][$colName]) && substr($colName, -3) === '_id') {
                    $guessedTable = guess_fk_table_name($colName, $pdo, $allTablesForGuessing);
                    if ($guessedTable) {
                        $result['fks'][$colName] = [
                            'table' => $guessedTable,
                            'column' => 'id'
                        ];
                    }
                }
            }
        }
        
        echo json_encode($result);
        exit;
    }
}

// ===== ACTION HANDLER (POST) =====
if ($is_logged_in && $_SERVER['REQUEST_METHOD'] === 'POST') {
    // Handle JSON payloads (e.g. for Excel Import)
    $contentType = $_SERVER['CONTENT_TYPE'] ?? '';
    if (stripos($contentType, 'application/json') !== false) {
        $jsonInput = json_decode(file_get_contents('php://input'), true);
        if (is_array($jsonInput)) {
            $_POST = array_merge($_POST, $jsonInput);
        }
    }

    $action = $_POST['action'] ?? '';
    $table = $_POST['table'] ?? '';
    $dbMode = $_SESSION['db_mode'] ?? 'sql';

    // --- UNIVERSAL REPLACE ---
    if ($action === 'universal_replace') {
        header('Content-Type: application/json');
        $search = $_POST['search_query'] ?? '';
        $replace = $_POST['replace_query'] ?? '';
        $mode = $_POST['replace_mode'] ?? 'all'; // 'all' or 'selected'
        $selected = $_POST['selected'] ?? []; // Array of "table|col|pk"

        if (empty($search)) {
            echo json_encode(['success' => false, 'message' => 'Search term cannot be empty.']);
            exit;
        }

        try {
            $affectedTotal = 0;
            if ($mode === 'selected' && !empty($selected)) {
                // Replace only in selected rows
                foreach ($selected as $item) {
                    $parts = explode('|', $item);
                    if (count($parts) < 2) continue;
                    $t = $parts[0];
                    $pkVal = $parts[1];
                    
                    if ($dbMode === 'json' && isset($jsonDb)) {
                        $row = $jsonDb->select($t, ['id' => ['operator' => '=', 'value' => $pkVal]]);
                        if (!empty($row)) {
                            $updates = [];
                            foreach ($row[0] as $col => $val) {
                                if (is_string($val) && stripos($val, $search) !== false) {
                                    $updates[$col] = str_ireplace($search, $replace, $val);
                                }
                            }
                            if (!empty($updates)) {
                                $jsonDb->update($t, $updates, ['id' => ['operator' => '=', 'value' => $pkVal]]);
                                $affectedTotal++;
                            }
                        }
                    } else {
                        // Detect PK
                        $pk = 'id'; // default fallback
                        if ($dbMode === 'sql') {
                            $res = $pdo->query("SHOW KEYS FROM `$t` WHERE Key_name = 'PRIMARY'")->fetch();
                            if ($res) $pk = $res['Column_name'];
                        } else {
                            foreach($pdo->query("PRAGMA table_info(`$t`)")->fetchAll() as $ci) if ($ci['pk']) $pk = $ci['name'];
                        }
                        
                        // Fetch row to find which columns contain the search term
                        $stmt = $pdo->prepare("SELECT * FROM `$t` WHERE `$pk` = ?");
                        $stmt->execute([$pkVal]);
                        $row = $stmt->fetch(PDO::FETCH_ASSOC);
                        
                        if ($row) {
                            $updateCols = [];
                            $params = [];
                            foreach ($row as $col => $val) {
                                if (is_string($val) && stripos($val, $search) !== false) {
                                    $updateCols[] = "`$col` = REPLACE(`$col`, ?, ?)";
                                    $params[] = $search;
                                    $params[] = $replace;
                                }
                            }
                            if (!empty($updateCols)) {
                                $uSql = "UPDATE `$t` SET " . implode(', ', $updateCols) . " WHERE `$pk` = ?";
                                $params[] = $pkVal;
                                $uStmt = $pdo->prepare($uSql);
                                $uStmt->execute($params);
                                $affectedTotal++;
                            }
                        }
                    }
                }
            } else {
                // Replace in ALL tables where search term matches
                if ($dbMode === 'json' && isset($jsonDb)) {
                    foreach ($jsonDb->listTables() as $t) {
                        $data = $jsonDb->select($t);
                        foreach ($data as $row) {
                            $changed = false;
                            $updates = [];
                            foreach ($row as $col => $val) {
                                if (is_string($val) && stripos($val, $search) !== false) {
                                    $updates[$col] = str_ireplace($search, $replace, $val);
                                    $changed = true;
                                }
                            }
                            if ($changed) {
                                $jsonDb->update($t, $updates, ['id' => ['operator' => '=', 'value' => $row['id']]]);
                                $affectedTotal++;
                            }
                        }
                    }
                } else {
                    $tables = [];
                    if ($dbMode === 'sql') {
                        $tables = $pdo->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN);
                    } else {
                        $tables = $pdo->query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")->fetchAll(PDO::FETCH_COLUMN);
                    }

                    foreach ($tables as $t) {
                        $cols = [];
                        if ($dbMode === 'sql') {
                            $cols = $pdo->query("DESCRIBE `$t`")->fetchAll(PDO::FETCH_COLUMN);
                        } else {
                            foreach($pdo->query("PRAGMA table_info(`$t`)")->fetchAll() as $ci) $cols[] = $ci['name'];
                        }
                        
                        foreach ($cols as $c) {
                            $sql = "UPDATE `$t` SET `$c` = REPLACE(`$c`, ?, ?) WHERE `$c` LIKE ?";
                            $stmt = $pdo->prepare($sql);
                            $stmt->execute([$search, $replace, "%$search%"]);
                            $affectedTotal += $stmt->rowCount();
                        }
                    }
                }
            }
            echo json_encode(['success' => true, 'message' => "Successfully replaced $affectedTotal occurrences."]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }

    if ($action === 'compare_structures') {
        header('Content-Type: application/json');
        $localhostSql = $_POST['localhost_sql'] ?? '';
        $productionSql = $_POST['production_sql'] ?? '';
        
        if (empty($localhostSql) || empty($productionSql)) {
            echo json_encode(['success' => false, 'message' => 'Both SQL structures are required.']);
            exit;
        }

        try {
            $localTables = parseSqlDump($localhostSql);
            $prodTables = parseSqlDump($productionSql);
            
            if (empty($localTables) || empty($prodTables)) {
                throw new Exception('Failed to parse SQL. Ensure format is "CREATE TABLE ...".');
            }
            
            $summary = [];
            $sqlResult = generateMigration($localTables, $prodTables, $summary);
            
            if ($sqlResult === '__NONE__') {
                $sqlResult = '-- No structural differences detected.';
            }

            // Ensure the result is clean of entities and normalized
            $sqlResult = html_entity_decode($sqlResult, ENT_QUOTES, 'UTF-8');

            echo json_encode([
                'success' => true,
                'sql' => $sqlResult,
                'summary' => $summary,
                'highlighted' => highlightSql($sqlResult)
            ]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }


    // --- SQL QUERY ---
    if ($action === 'sql_query') {
        $sql = $_POST['query'] ?? '';
        $statements = split_sql_statements($sql);
        $affectedTotal = 0;
        $resultSets = [];

        if (empty($statements)) {
            $error = 'No SQL statements provided.';
        } else {
            try {
                foreach ($statements as $statement) {
                    if (stripos($statement, 'DROP DATABASE') === 0) {
                        throw new Exception('DROP DATABASE statements are blocked.');
                    }

                    if (is_resultset_statement($statement)) {
                        $stmt = $pdo->query($statement);
                        $fetched = $stmt->fetchAll();
                        $resultSets[] = [
                            'query' => $statement,
                            'rows' => $fetched,
                            'columns' => !empty($fetched) ? array_keys($fetched[0]) : []
                        ];
                    } else {
                        $affected = $pdo->exec($statement);
                        $affectedTotal += $affected !== false ? $affected : 0;
                    }
                }
                $sqlResults = $resultSets;
                $lastResultSet = !empty($resultSets) ? end($resultSets) : null;
                $msg = count($statements) . " statement(s) executed. Rows affected: $affectedTotal.";
            } catch (Exception $e) {
                $error = $e->getMessage();
            }
        }
    }
    // --- EXPORT FILTERED DATA ---
    elseif ($action === 'export_filtered') {
        $table = $_POST['table'] ?? '';
        $format = $_POST['format'] ?? 'csv';
        $whereClause = $_POST['where_clause'] ?? '';
        
        if (empty($table)) {
            fm_set_msg('Table name is required', 'error');
            fm_redirect(FM_SELF_URL . '?p=' . urlencode(FM_PATH));
        }
        
        if (empty($whereClause)) {
            fm_set_msg('No filter conditions provided', 'error');
            fm_redirect(FM_SELF_URL . '?p=' . urlencode(FM_PATH));
        }
        
        try {
            // Check if we're in JSON mode
            if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
                // JSON Mode - parse WHERE clause and fetch data
                // For simplicity, we'll fetch all data and filter in PHP
                $allData = $jsonDb->select($table);
                $rows = $allData; // TODO: Implement WHERE clause parsing for JSON
            } else {
                // SQL Mode
                $query = "SELECT * FROM `$table` WHERE $whereClause";
                $stmt = $pdo->query($query);
                $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            }
            
            if (empty($rows)) {
                fm_set_msg('No data to export', 'error');
                fm_redirect(FM_SELF_URL . '?p=' . urlencode(FM_PATH));
            }
            
            $filename = $table . "_filtered_" . date("Y-m-d_H-i-s");
            
            if ($format === 'csv') {
                header('Content-Type: text/csv');
                header("Content-Disposition: attachment; filename=\"$filename.csv\"");
                $out = fopen('php://output', 'w');
                fputcsv($out, array_keys($rows[0]), ',', '"', "\\");
                foreach ($rows as $row) {
                    fputcsv($out, $row, ',', '"', "\\");
                }
                fclose($out);
            } elseif ($format === 'json') {
                header('Content-Type: application/json');
                header("Content-Disposition: attachment; filename=\"$filename.json\"");
                echo json_encode($rows, JSON_PRETTY_PRINT);
            } elseif ($format === 'sql') {
                header('Content-Type: application/octet-stream');
                header("Content-Disposition: attachment; filename=\"$filename.sql\"");
                foreach ($rows as $row) {
                    $keys = array_keys($row);
                    $values = array_map(function($v) use ($pdo) {
                        return $v === null ? "NULL" : $pdo->quote($v);
                    }, array_values($row));
                    echo "INSERT INTO `$table` (`" . implode('`, `', $keys) . "`) VALUES (" . implode(', ', $values) . ");\n";
                }
            }
            exit;
        } catch (Exception $e) {
            fm_set_msg('Export error: ' . $e->getMessage(), 'error');
            fm_redirect(FM_SELF_URL . '?p=' . urlencode(FM_PATH));
        }
    }
    // --- CREATE JSON FILE ---
    elseif ($action === 'create_json_file') {
        header('Content-Type: application/json');
        $filename = $_POST['filename'] ?? '';
        
        if (empty($filename)) {
            echo json_encode(['success' => false, 'message' => 'Filename is required']);
            exit;
        }
        
        if (!preg_match('/^[a-zA-Z0-9_\-]+\.json$/', $filename)) {
            echo json_encode(['success' => false, 'message' => 'Invalid filename. Use only letters, numbers, underscore, and hyphen']);
            exit;
        }
        
        try {
            $jsonDb->selectFile($filename);
            // Create empty file with default structure
            $jsonDb->createTable('default_table');
            echo json_encode(['success' => true, 'message' => 'JSON file created successfully']);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- CREATE SQLITE FILE ---
    elseif ($action === 'create_sqlite_file') {
        header('Content-Type: application/json');
        $filename = $_POST['filename'] ?? '';
        
        if (empty($filename)) {
            echo json_encode(['success' => false, 'message' => 'Filename is required']);
            exit;
        }
        
        if (!preg_match('/^[a-zA-Z0-9_\-]+\.(db|sqlite)$/', $filename)) {
            echo json_encode(['success' => false, 'message' => 'Invalid filename. Use only letters, numbers, underscore, and hyphen']);
            exit;
        }
        
        try {
            $sqlitePath = __DIR__ . '/sqlite_db/' . basename($filename);
            
            if (file_exists($sqlitePath)) {
                echo json_encode(['success' => false, 'message' => 'File already exists']);
                exit;
            }
            
            // Create new SQLite database
            $sqlitePdo = new PDO('sqlite:' . $sqlitePath);
            $sqlitePdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
            
            // Create a default table
            $sqlitePdo->exec("CREATE TABLE IF NOT EXISTS example (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )");
            
            echo json_encode(['success' => true, 'message' => 'SQLite database created successfully']);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- DELETE SQLITE FILE ---
    elseif ($action === 'delete_sqlite_file') {
        header('Content-Type: application/json');
        $filename = $_POST['filename'] ?? '';
        
        if (empty($filename)) {
            echo json_encode(['success' => false, 'message' => 'Filename is required']);
            exit;
        }
        
        try {
            $filePath = __DIR__ . '/sqlite_db/' . basename($filename);
            
            if (file_exists($filePath)) {
                unlink($filePath);
                
                // Clear session if it was the selected one
                if (($_SESSION['sqlite_file'] ?? '') === $filename) {
                    unset($_SESSION['sqlite_file']);
                    unset($_SESSION['sqlite_file_path']);
                    $_SESSION['db_mode'] = 'sql';
                }
                
                echo json_encode(['success' => true, 'message' => 'SQLite database deleted successfully']);
            } else {
                echo json_encode(['success' => false, 'message' => 'File not found']);
            }
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- SAVE JSON TABLE (TREE EDITOR) ---
    elseif ($action === 'save_json_table') {
        header('Content-Type: application/json');
        $table = $_POST['table'] ?? '';
        $jsonData = $_POST['json_data'] ?? '';
        
        try {
            $data = json_decode($jsonData, true);
            if (!is_array($data)) {
                throw new Exception('Invalid JSON data provided.');
            }
            
            $jsonDb->importTable($table, $data);
            echo json_encode(['success' => true, 'message' => 'Table updated successfully']);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- BROWSE SQLITE FILES ---
    elseif ($action === 'browse_sqlite_files') {
        header('Content-Type: application/json');
        $path = $_POST['path'] ?? '';
        
        // Security: clean path and prevent directory traversal
        $path = str_replace(['..', '\\'], ['', '/'], $path);
        $path = trim($path, '/');
        
        // Base path is document root
        $basePath = $_SERVER['DOCUMENT_ROOT'];
        $fullPath = $basePath . ($path ? '/' . $path : '');
        
        try {
            if (!is_dir($fullPath)) {
                throw new Exception('Invalid path');
            }
            
            $items = scandir($fullPath);
            $folders = [];
            $files = [];
            
            foreach ($items as $item) {
                if ($item === '.' || $item === '..') continue;
                
                // Skip hidden files/folders
                if (substr($item, 0, 1) === '.') continue;
                
                $itemPath = $fullPath . '/' . $item;
                
                if (is_dir($itemPath)) {
                    $folders[] = $item;
                } elseif (is_file($itemPath)) {
                    $ext = pathinfo($item, PATHINFO_EXTENSION);
                    if ($ext === 'db' || $ext === 'sqlite' || $ext === 'sqlite3') {
                        $files[] = $item;
                    }
                }
            }
            
            // Sort
            natcasesort($folders);
            natcasesort($files);
            
            echo json_encode([
                'success' => true,
                'current_path' => $path,
                'items' => [
                    'folders' => array_values($folders),
                    'files' => array_values($files)
                ]
            ]);
        } catch (Exception $e) {
            echo json_encode([
                'success' => false,
                'message' => $e->getMessage()
            ]);
        }
        exit;
    }
    // --- DELETE JSON FILE ---
    elseif ($action === 'delete_json_file') {
        header('Content-Type: application/json');
        $filename = $_POST['filename'] ?? '';
        
        if (empty($filename)) {
            echo json_encode(['success' => false, 'message' => 'Filename is required']);
            exit;
        }
        
        try {
            $filePath = __DIR__ . '/json_db/' . basename($filename);
            if (file_exists($filePath)) {
                if (unlink($filePath)) {
                    // Clear session if deleting current file
                    if ($_SESSION['json_file'] === $filename) {
                        unset($_SESSION['json_file']);
                    }
                    echo json_encode(['success' => true, 'message' => 'JSON file deleted successfully']);
                } else {
                    echo json_encode(['success' => false, 'message' => 'Failed to delete file']);
                }
            } else {
                echo json_encode(['success' => false, 'message' => 'File not found']);
            }
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- BROWSE FILES (FOR JSON FILE SELECTION) ---
    elseif ($action === 'browse_files') {
        header('Content-Type: application/json');
        $path = $_POST['path'] ?? '';
        
        // Security: clean path and prevent directory traversal
        $path = str_replace(['..', '\\'], ['', '/'], $path);
        $path = trim($path, '/');
        
        // Base path is document root
        $basePath = $_SERVER['DOCUMENT_ROOT'];
        $fullPath = $basePath . ($path ? '/' . $path : '');
        
        try {
            if (!is_dir($fullPath)) {
                throw new Exception('Invalid path');
            }
            
            $items = scandir($fullPath);
            $folders = [];
            $files = [];
            
            foreach ($items as $item) {
                if ($item === '.' || $item === '..') continue;
                
                // Skip hidden files/folders
                if (substr($item, 0, 1) === '.') continue;
                
                $itemPath = $fullPath . '/' . $item;
                
                if (is_dir($itemPath)) {
                    $folders[] = $item;
                } elseif (is_file($itemPath) && pathinfo($item, PATHINFO_EXTENSION) === 'json') {
                    $files[] = $item;
                }
            }
            
            // Sort
            natcasesort($folders);
            natcasesort($files);
            
            echo json_encode([
                'success' => true,
                'current_path' => $path,
                'items' => [
                    'folders' => array_values($folders),
                    'files' => array_values($files)
                ]
            ]);
        } catch (Exception $e) {
            echo json_encode([
                'success' => false,
                'message' => $e->getMessage()
            ]);
        }
        exit;
    }
    // --- SET FK CHECKS ---
    elseif ($action === 'set_fk_checks') {
        $val = (int)($_POST['value'] ?? 1);
        $_SESSION['fk_checks'] = $val; // Save to session to persist across requests
        try {
            if ($pdo) {
                $pdo->exec("SET FOREIGN_KEY_CHECKS = $val");
            }
            $table = $_POST['table'] ?? '';
            redirect("?table=$table&view=structure&msg=" . urlencode("Foreign Key Checks set to $val " . ($val ? 'ON' : 'OFF') . "."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- GENERATE DUMMY DATA ---
    elseif ($action === 'generate_dummy_data') {
        $count = (int)($_POST['count'] ?? 10);
        if ($count > 1000) $count = 1000;
        
        $overrides = [];
        if (!empty($_POST['overrides'])) {
            $overrides = json_decode($_POST['overrides'], true) ?: [];
        }
        
        try {
            if (($_SESSION['db_mode'] ?? 'sql') === 'json') {
                for ($i = 0; $i < $count; $i++) {
                    $dummy = [];
                    $existing = $jsonDb->select($table, [], 0, 1);
                    if (!empty($existing)) {
                        foreach (array_keys($existing[0]) as $key) {
                            if ($key === 'id') continue;
                            
                            if (isset($overrides[$key])) {
                                if (is_array($overrides[$key])) {
                                    $dummy[$key] = $overrides[$key][array_rand($overrides[$key])];
                                } else {
                                    $dummy[$key] = $overrides[$key];
                                }
                            } else {
                                $type = guess_fake_type($key, 'string');
                                $dummy[$key] = generate_fake_data($type, $i);
                            }
                        }
                    }
                    $jsonDb->insert($table, $dummy);
                }
            } else {
                // SQL Mode - Pre-fetch ENUM and FK info
                $stmt = $pdo->query("DESCRIBE `$table`");
                $structure = $stmt->fetchAll(PDO::FETCH_ASSOC);
                
                $colMeta = [];
                foreach ($structure as $col) {
                    if (strpos($col['Extra'], 'auto_increment') !== false) continue;
                    
                    $field = $col['Field'];
                    $type = $col['Type'];
                    $options = null;
                    
                    // Handle ENUM
                    if (stripos($type, 'enum') === 0) {
                        preg_match("/^enum\((.*)\)$/i", $type, $matches);
                        if (isset($matches[1])) {
                            $options = str_getcsv($matches[1], ",", "'");
                        }
                    }
                    
                    // Handle Foreign Key
                    $fkValues = [];
                    $sqlFK = "SELECT REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME 
                              FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE 
                              WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ? AND REFERENCED_TABLE_NAME IS NOT NULL";
                    $stmtFK = $pdo->prepare($sqlFK);
                    $stmtFK->execute([$table, $field]);
                    $fk = $stmtFK->fetch(PDO::FETCH_ASSOC);
                    
                    if ($fk) {
                        $refTable = $fk['REFERENCED_TABLE_NAME'];
                        $refCol = $fk['REFERENCED_COLUMN_NAME'];
                        try {
                            $stmtRef = $pdo->query("SELECT `$refCol` FROM `$refTable` LIMIT 50");
                            $fkValues = $stmtRef->fetchAll(PDO::FETCH_COLUMN);
                        } catch(Exception $e) {}
                    }
                    
                    $colMeta[$field] = [
                        'type' => $type,
                        'enum_options' => $options,
                        'fk_values' => $fkValues
                    ];
                }
                
                for ($i = 0; $i < $count; $i++) {
                    $insertCols = [];
                    $params = [];
                    foreach ($colMeta as $name => $meta) {
                        $insertCols[] = "`$name`";
                        
                        // Priority 1: Manual Overrides (supports array for random choice)
                        if (isset($overrides[$name])) {
                            $val = is_array($overrides[$name]) ? $overrides[$name][array_rand($overrides[$name])] : $overrides[$name];
                            
                            // Check for special seeder command
                            if (is_string($val) && strpos($val, '__SEED__:') === 0) {
                                $forcedType = substr($val, 9);
                                $val = generate_fake_data($forcedType, $i);
                            }
                        } 
                        // Priority 2: ENUM options
                        elseif ($meta['enum_options']) {
                            $val = $meta['enum_options'][array_rand($meta['enum_options'])];
                        }
                        // Priority 3: Foreign Key values
                        elseif ($meta['fk_values']) {
                            $val = $meta['fk_values'][array_rand($meta['fk_values'])];
                        }
                        // Priority 4: Smart Fake Data
                        else {
                            $type = guess_fake_type($name, $meta['type']);
                            $val = generate_fake_data($type, $i, $meta['type']);
                        }
                        
                        $params[] = $val;
                    }
                    
                    $insertKeyword = 'INSERT';
                    $sql = "$insertKeyword INTO `$table` (" . implode(', ', $insertCols) . ") VALUES (" . implode(', ', array_fill(0, count($params), '?')) . ")";
                    $stmt = $pdo->prepare($sql);
                    $stmt->execute($params);
                }
            }
            redirect("?table=$table&view=data&msg=" . urlencode("$count rows of dummy data generated successfully."));
        } catch (Exception $e) {
            $error = "Successfully seeded " . ($i ?? 0) . " rows. (" . ($count - ($i ?? 0)) . " failed. Error: " . $e->getMessage() . ")";
            if (strpos($error, '1264') !== false) {
                $error .= "<br><br><div style='background:rgba(255,107,107,0.1); padding:10px; border-radius:4px; border:1px solid #ff6b6b; font-weight:bold; color:#ffb3b3;'>";
                $error .= "<i class='fas fa-exclamation-triangle'></i> TIP: Nilai yang Anda masukkan mungkin terlalu besar untuk tipe kolom tersebut (misal: memasukkan 387 ke kolom TINYINT).<br>";
                $error .= "<a href='?table=$table&view=structure' style='color:#fff; text-decoration:underline;'>Ubah tipe kolom ke INT di tab Structure &rarr;</a>";
                $error .= "</div>";
            }
        }
    }
    // --- DUPLICATE ROW ---
    elseif ($action === 'duplicate_row') {
        $pk = $_POST['pk'] ?? null;
        $val = $_POST['val'] ?? null;
        // Support both 'count' (from JS) and 'duplicate_count'
        $count = isset($_POST['count']) ? (int)$_POST['count'] : (isset($_POST['duplicate_count']) ? (int)$_POST['duplicate_count'] : 1);
        if ($count < 1) $count = 1;
        
        try {
            if ($pk && $val) {
                if (($_SESSION['db_mode'] ?? 'sql') === 'json') {
                    for ($i = 0; $i < $count; $i++) {
                        $jsonDb->duplicate_row($table, $val);
                    }
                    $msg = $count > 1 ? "$count rows duplicated successfully." : "Row duplicated successfully.";
                } else {
                    // SQL Mode: Fetch original row to handle unique constraints
                    $stmt = $pdo->prepare("SELECT * FROM `$table` WHERE `$pk` = ?");
                    $stmt->execute([$val]);
                    $original = $stmt->fetch(PDO::FETCH_ASSOC);
                    
                    if (!$original) throw new Exception("Original row not found.");
                    
                    // Get columns meta to identify unique/primary keys
                    $stmt = $pdo->query("SHOW COLUMNS FROM `$table` ");
                    $colsMeta = $stmt->fetchAll(PDO::FETCH_ASSOC);
                    
                    $insertCols = [];
                    $uniqueFields = [];
                    foreach ($colsMeta as $m) {
                        if (strpos($m['Extra'], 'auto_increment') !== false) continue;
                        $insertCols[] = $m['Field'];
                        // UNI = Unique, PRI = Primary Key
                        // We also check MUL because composite unique keys appear as MUL in DESCRIBE
                        if ($m['Key'] === 'UNI' || $m['Key'] === 'PRI' || $m['Key'] === 'MUL') {
                            $uniqueFields[] = $m['Field'];
                        }
                    }
                    
                    $bypass = isset($_POST['bypass']) && $_POST['bypass'] == '1';

                    for ($i = 1; $i <= $count; $i++) {
                        $data = $original;
                        foreach ($uniqueFields as $f) {
                            if ($data[$f] === null) continue;
                            
                            if (is_string($data[$f])) {
                                // Append random string or sequence for uniqueness
                                if (strpos($data[$f], '@') !== false && filter_var($data[$f], FILTER_VALIDATE_EMAIL)) {
                                    $parts = explode('@', $data[$f]);
                                    $data[$f] = $parts[0] . "+" . substr(md5(uniqid() . $i), 0, 4) . "@" . $parts[1];
                                } else {
                                    // Prevent double copy suffix if duplicating a duplicate
                                    $data[$f] = preg_replace('/\s\(\d+\)$/', '', $data[$f]);
                                    $data[$f] .= "$i";
                                }
                            } elseif (is_numeric($data[$f])) {
                                $data[$f] = $data[$f] + rand(100, 999) + $i;
                            }
                        }
                        
                        $fields = [];
                        $placeholders = [];
                        $values = [];
                        foreach ($insertCols as $colName) {
                            $fields[] = "`$colName`";
                            $placeholders[] = "?";
                            $values[] = $data[$colName];
                        }
                        
                        $insertKeyword = 'INSERT';
                        // Use IGNORE internally only if we really need to prevent crash on PRI/UNI
                        $sql = "$insertKeyword INTO `$table` (" . implode(', ', $fields) . ") VALUES (" . implode(', ', $placeholders) . ")";
                        $stmt = $pdo->prepare($sql);
                        $stmt->execute($values);
                    }
                    $msg = $count > 1 ? "$count rows processed." : "Row processed.";
                    if ($bypass) $msg .= " (Duplicates were ignored/bypassed)";
                }
                redirect("?table=$table&view=data&msg=" . urlencode($msg));
            }
        } catch (Exception $e) {
            $error = "Duplicate error: " . $e->getMessage();
        }
    }
    // --- SAVE ROW ---
    elseif ($action === 'save_row') {
        $data = $_POST['data'] ?? [];
        $pk = $_POST['pk'] ?? null;
        $pkVal = $_POST['pk_val'] ?? null;
        
        try {
            // Check if we're in JSON mode
            if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
                if ($pkVal) {
                    // UPDATE
                    $jsonDb->update($table, $data, [
                        'id' => ['operator' => '=', 'value' => $pkVal]
                    ]);
                    $msg = "Row updated successfully.";
                } else {
                    // INSERT
                    $jsonDb->insert($table, $data);
                    $msg = "Row inserted successfully.";
                }
            } else {
                // SQL Mode
                if ($pkVal) {
                    // UPDATE
                    $set = [];
                    $params = [];
                    foreach ($data as $col => $val) {
                        $set[] = "`$col` = ?";
                        $params[] = $val;
                    }
                    $params[] = $pkVal;
                    $sql = "UPDATE `$table` SET " . implode(', ', $set) . " WHERE `$pk` = ?";
                    $stmt = $pdo->prepare($sql);
                    $stmt->execute($params);
                    $msg = "Row updated successfully.";
                } else {
                    // INSERT
                    $cols = array_keys($data);
                    $vals = array_values($data);
                    $placeholders = array_fill(0, count($vals), '?');
                    $sql = "INSERT INTO `$table` (`" . implode('`, `', $cols) . "`) VALUES (" . implode(', ', $placeholders) . ")";
                    $stmt = $pdo->prepare($sql);
                    $stmt->execute($vals);
                    $msg = "Row inserted successfully.";
                }
            }
            redirect("?table=$table&view=data&msg=" . urlencode($msg));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- DELETE TABLE ---
    elseif ($action === 'delete_table') {
        try {
            $pdo->exec("DROP TABLE `$table`");
            redirect("?msg=" . urlencode("Table $table deleted."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- TRUNCATE TABLE ---
    elseif ($action === 'truncate_table') {
        try {
            $pdo->exec("TRUNCATE TABLE `$table`");
            redirect("?table=$table&view=structure&msg=" . urlencode("Table $table truncated."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- DROP COLUMN ---
    elseif ($action === 'drop_column') {
        $col = $_POST['col'];
        try {
            $pdo->exec("ALTER TABLE `$table` DROP COLUMN `$col`");
            redirect("?table=$table&view=structure&msg=" . urlencode("Column $col dropped."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- SAVE COLUMN (ADD/EDIT) ---
    elseif ($action === 'save_column') {
        $orig = $_POST['orig_field'] ?? '';
        $name = $_POST['field'];
        $type = $_POST['type'];
        $length = $_POST['length'];
        $default = $_POST['default']; 
        $default_val = $_POST['default_val'] ?? '';
        $null = isset($_POST['null']) ? 'NULL' : 'NOT NULL';
        $ai = isset($_POST['ai']) ? 'AUTO_INCREMENT' : '';
        $collation = $_POST['collation'] ?? '';
        
        // Build definition
        $def = "`$name` $type";
        if ($length !== '') $def .= "($length)";
        if ($collation) $def .= " COLLATE $collation";
        $def .= " $null";
        
        if ($default === 'NULL') {
            $def .= " DEFAULT NULL";
        } elseif ($default === 'USER_DEFINED') {
            $def .= " DEFAULT " . $pdo->quote($default_val);
        } elseif ($default === 'CURRENT_TIMESTAMP') {
            $def .= " DEFAULT CURRENT_TIMESTAMP";
        }
        
        $def .= " $ai";
        
        try {
            if ($orig) {
                $sql = "ALTER TABLE `$table` CHANGE COLUMN `$orig` $def";
            } else {
                $after = $_POST['after'] ?? '';
                $pos = $after ? "AFTER `$after`" : "FIRST"; 
                if ($after === '') $pos = ""; 
                $sql = "ALTER TABLE `$table` ADD COLUMN $def $pos";
            }
            $pdo->exec($sql);
            redirect("?table=$table&view=structure&msg=" . urlencode("Column saved."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- EXPORT ---
    elseif ($action === 'export') {
        $exportTable = $_POST['table'] ?? null; // If null, export all
        $format = $_POST['format'] ?? 'sql';
        $dbMode = $_SESSION['db_mode'] ?? 'sql';
        
        // Determine filename
        if ($dbMode === 'json') {
            $filename = ($exportTable ? $exportTable : 'json_export') . "_" . date("Y-m-d_H-i-s");
        } elseif ($dbMode === 'sqlite') {
            $filename = ($exportTable ? $exportTable : 'sqlite_export') . "_" . date("Y-m-d_H-i-s");
        } else {
            $filename = ($exportTable ? $exportTable : $_SESSION['db_name']) . "_" . date("Y-m-d_H-i-s");
        }

        if ($format === 'csv') {
            header('Content-Type: text/csv');
            header("Content-disposition: attachment; filename=\"$filename.csv\"");
            $out = fopen('php://output', 'w');
            $colsJson = $_POST['columns'] ?? '';
            $selCols = !empty($colsJson) ? json_decode($colsJson, true) : null;
            
            $csvOut = fopen('php://temp', 'w+');
            // Support JSON, SQLite, and SQL modes
            if ($dbMode === 'json' && $exportTable) {
                $data = $jsonDb->select($exportTable);
                if (!empty($data)) {
                    $keys = $selCols && is_array($selCols) ? $selCols : array_keys($data[0]);
                    fputcsv($csvOut, $keys, ',', '"', "\\");
                    foreach ($data as $row) {
                        $csvRow = [];
                        foreach ($keys as $k) $csvRow[] = $row[$k] ?? '';
                        fputcsv($csvOut, $csvRow, ',', '"', "\\");
                    }
                }
            } elseif ($exportTable) {
                $colsStr = ($selCols && is_array($selCols)) ? "`" . implode("`, `", $selCols) . "`" : "*";
                $whereSql = '';
                if (!empty($_POST['export_where'])) {
                    $whereSql = " WHERE " . $_POST['export_where'];
                }
                $stmt = $pdo->query("SELECT $colsStr FROM `$exportTable`$whereSql");
                $first = true;
                $keys = [];
                while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
                    if ($first) {
                        $keys = $selCols && is_array($selCols) ? $selCols : array_keys($row);
                        fputcsv($csvOut, $keys, ',', '"', "\\");
                        $first = false;
                    }
                    $csvRow = [];
                    foreach ($keys as $k) $csvRow[] = $row[$k] ?? '';
                    fputcsv($csvOut, $csvRow, ',', '"', "\\");
                }
            }
            
            rewind($csvOut);
            $csvData = stream_get_contents($csvOut);
            fclose($csvOut);
            
            if (isset($_POST['copy_mode']) && $_POST['copy_mode'] === '1') {
                header('Content-Type: text/plain');
                echo $csvData;
                exit;
            }
            echo $csvData;
        } elseif ($format === 'json') {
            header('Content-Type: application/json');
            header("Content-disposition: attachment; filename=\"$filename.json\"");
            
            $data = [];
            $colsJson = $_POST['columns'] ?? '';
            $selCols = !empty($colsJson) ? json_decode($colsJson, true) : null;
            
            if ($dbMode === 'json' && $exportTable) {
                $raw = $jsonDb->select($exportTable);
                foreach($raw as $r) {
                    if ($selCols && is_array($selCols)) {
                        $n = []; foreach($selCols as $c) if (isset($r[$c])) $n[$c] = $r[$c];
                        $data[] = $n;
                    } else $data[] = $r;
                }
            } elseif ($exportTable) {
                $colsStr = ($selCols && is_array($selCols)) ? "`" . implode("`, `", $selCols) . "`" : "*";
                $whereSql = '';
                if (!empty($_POST['export_where'])) {
                    $whereSql = " WHERE " . $_POST['export_where'];
                }
                $stmt = $pdo->query("SELECT $colsStr FROM `$exportTable`$whereSql");
                $data = $stmt->fetchAll(PDO::FETCH_ASSOC);
            }
            
            $outputStr = json_encode($data, JSON_PRETTY_PRINT);
            
            if (isset($_POST['copy_mode']) && $_POST['copy_mode'] === '1') {
                header('Content-Type: text/plain');
                echo $outputStr;
                exit;
            }
            
            echo $outputStr;
        } elseif ($format === 'xlsx') {
            // Excel export - support all modes
            // Using simple XML format compatible with Excel
            
            $data = [];
            if ($dbMode === 'json' && $exportTable) {
                $data = $jsonDb->select($exportTable);
            } elseif ($exportTable) {
                $whereSql = '';
                if (!empty($_POST['export_where'])) {
                    $whereSql = " WHERE " . $_POST['export_where'];
                }
                $stmt = $pdo->query("SELECT * FROM `$exportTable`$whereSql");
                $data = $stmt->fetchAll(PDO::FETCH_ASSOC);
            }
            
            if (!empty($data)) {
                header('Content-Type: application/vnd.ms-excel');
                header("Content-Disposition: attachment; filename=\"$filename.xls\"");
                
                echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n";
                echo '<?mso-application progid="Excel.Sheet"?>' . "\n";
                echo '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"' . "\n";
                echo ' xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">' . "\n";
                echo '<Worksheet ss:Name="' . htmlspecialchars($exportTable ?: 'Sheet1') . '">' . "\n";
                echo '<Table>' . "\n";
                
                // Header row
                $header = array_keys($data[0]);
                echo '<Row>' . "\n";
                foreach ($header as $col) {
                    echo '<Cell><Data ss:Type="String">' . htmlspecialchars($col) . '</Data></Cell>' . "\n";
                }
                echo '</Row>' . "\n";
                
                // Data rows
                foreach ($data as $row) {
                    echo '<Row>' . "\n";
                    foreach ($row as $val) {
                        $type = is_numeric($val) ? 'Number' : 'String';
                        $value = htmlspecialchars($val ?? '');
                        echo '<Cell><Data ss:Type="' . $type . '">' . $value . '</Data></Cell>' . "\n";
                    }
                    echo '</Row>' . "\n";
                }
                
                echo '</Table>' . "\n";
                echo '</Worksheet>' . "\n";
                echo '</Workbook>';
            }
            exit;
        } else {
            // SQL EXPORT (Default)
            if (isset($_POST['copy_mode']) && $_POST['copy_mode'] === '1') {
                header('Content-Type: text/plain');
            } else {
                header('Content-Type: application/octet-stream');
                header("Content-Transfer-Encoding: Binary"); 
                header("Content-disposition: attachment; filename=\"$filename.sql\""); 
            }
            
            $colsJson = $_POST['columns'] ?? '';
            $selCols = !empty($colsJson) ? json_decode($colsJson, true) : null;
            $sqlMode = $_POST['sql_mode'] ?? 'insert'; // 'insert' or 'update'
            
            $tablesToExport = [];
            if ($exportTable) {
                $tablesToExport[] = $exportTable;
            } else {
                $stmt = $pdo->query("SHOW TABLES");
                while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
                    $tablesToExport[] = $row[0];
                }
            }

            // Collect CREATE statements and referenced tables for ordering
            $creates = [];
            $refs = [];
            foreach ($tablesToExport as $t) {
                $stmt = $pdo->query("SHOW CREATE TABLE `$t`");
                $row = $stmt->fetch(PDO::FETCH_NUM);
                $creates[$t] = $row ? $row[1] : '';
                $matches = [];
                preg_match_all("/REFERENCES\s+`([^`]+)`/i", $creates[$t], $matches);
                $refs[$t] = array_values(array_unique($matches[1] ?? []));
            }

            // Topological sort
            $inDegree = [];
            $dependents = [];
            foreach ($tablesToExport as $t) $inDegree[$t] = 0;
            foreach ($tablesToExport as $t) {
                foreach ($refs[$t] ?? [] as $r) {
                    if (isset($inDegree[$r])) {
                        $inDegree[$t]++;
                        $dependents[$r][] = $t;
                    }
                }
            }
            $queue = [];
            foreach ($inDegree as $t => $deg) if ($deg === 0) $queue[] = $t;
            $ordered = [];
            while (!empty($queue)) {
                $n = array_shift($queue);
                $ordered[] = $n;
                foreach ($dependents[$n] ?? [] as $m) {
                    $inDegree[$m]--;
                    if ($inDegree[$m] === 0) $queue[] = $m;
                }
            }

            echo "-- Adminer Export: " . date("Y-m-d H:i:s") . "\n";
            echo "-- Database: " . $_SESSION['db_name'] . "\n\n";

            $useFkChecks = true;
            if (count($ordered) !== count($tablesToExport)) {
                $useFkChecks = false;
                echo "SET FOREIGN_KEY_CHECKS=0;\n\n";
            }

            $sequence = count($ordered) === count($tablesToExport) ? $ordered : $tablesToExport;

            foreach ($sequence as $t) {
                echo "-- --------------------------------------------------------\n";
                
                if (!$selCols && $sqlMode !== 'update' && $sqlMode !== 'upsert') {
                    echo "-- Structure for table `$t`\n";
                    echo "--\n\n";
                    echo "DROP TABLE IF EXISTS `$t`;\n";
                    echo ($creates[$t] ?? '') . ";\n\n";
                }

                echo "-- Data for table `$t`\n\n";
                if ($sqlMode === 'update' && !empty($_POST['where_column'])) {
                    $pkCol = $_POST['where_column'];
                } else {
                    $pkCol = function_exists('getPrimaryKey') ? getPrimaryKey($pdo, $t) : 'id';
                    if (!$pkCol) $pkCol = 'id';
                }
                
                if ($selCols && is_array($selCols) && count($tablesToExport) === 1) {
                    $queryCols = $selCols;
                    if ($sqlMode === 'update' && !in_array($pkCol, $queryCols)) {
                        $queryCols[] = $pkCol;
                    }
                    $colsStr = "`" . implode("`, `", $queryCols) . "`";
                } else {
                    $colsStr = "*";
                }
                
                $whereSql = '';
                if (!empty($_POST['export_where']) && count($tablesToExport) === 1) {
                    $whereSql = " WHERE " . $_POST['export_where'];
                }
                
                try {
                    $stmt = $pdo->query("SELECT $colsStr FROM `$t`$whereSql");
                    $buffer = [];
                    $keys = [];
                    $first = true;
                    while ($r = $stmt->fetch(PDO::FETCH_ASSOC)) {
                        if ($sqlMode === 'update') {
                            $pkVal = $r[$pkCol] ?? null;
                            if ($pkVal === null) continue;
                            $sets = [];
                            foreach ($r as $k => $v) {
                                if ($k === $pkCol) continue;
                                if ($selCols && is_array($selCols) && count($tablesToExport) === 1 && !in_array($k, $selCols)) continue;
                                $sets[] = "`$k` = " . ($v === null ? "NULL" : $pdo->quote($v));
                            }
                            if (!empty($sets)) {
                                echo "UPDATE `$t` SET " . implode(', ', $sets) . " WHERE `$pkCol` = " . $pdo->quote($pkVal) . ";\n";
                            }
                        } elseif ($sqlMode === 'upsert') {
                            if ($first) {
                                $keys = array_keys($r);
                                $first = false;
                            }
                            $vals = [];
                            foreach ($r as $v) {
                                $vals[] = ($v === null) ? 'NULL' : $pdo->quote($v);
                            }
                            
                            $updates = [];
                            foreach ($r as $k => $v) {
                                if ($selCols && is_array($selCols) && count($tablesToExport) === 1 && !in_array($k, $selCols)) continue;
                                $updates[] = "`$k` = " . ($v === null ? 'NULL' : $pdo->quote($v));
                            }
                            
                            $updateStr = !empty($updates) ? implode(', ', $updates) : "`" . $keys[0] . "` = `" . $keys[0] . "`";
                            
                            echo "INSERT INTO `$t` (`" . implode("`, `", $keys) . "`) VALUES (" . implode(", ", $vals) . ") ON DUPLICATE KEY UPDATE " . $updateStr . ";\n";
                        } else {
                            if ($first) {
                                $keys = array_keys($r);
                                $first = false;
                            }
                            $vals = [];
                            foreach ($r as $v) {
                                $vals[] = ($v === null) ? 'NULL' : $pdo->quote($v);
                            }
                            $buffer[] = "(" . implode(', ', $vals) . ")";
                            if (count($buffer) >= 100) {
                                echo "INSERT INTO `$t` (`" . implode("`, `", $keys) . "`) VALUES\n" . implode(",\n", $buffer) . ";\n";
                                $buffer = [];
                            }
                        }
                    }
                    if (!empty($buffer) && $sqlMode !== 'update' && $sqlMode !== 'upsert') {
                        echo "INSERT INTO `$t` (`" . implode("`, `", $keys) . "`) VALUES\n" . implode(",\n", $buffer) . ";\n";
                    }
                } catch (Exception $e) {
                    echo "-- Error exporting data for $t: " . $e->getMessage() . "\n";
                }
                echo "\n";
            }

            if (!$useFkChecks) {
                echo "SET FOREIGN_KEY_CHECKS=1;\n";
            }
        }
        exit;
    }
    // --- UPDATE CELL (INLINE EDIT) ---
    elseif ($action === 'update_cell') {
        header('Content-Type: application/json');
        $tableName = $_POST['table'] ?? '';
        $col = $_POST['column'] ?? '';
        $id = $_POST['id'] ?? '';
        $val = $_POST['value'] ?? '';
        
        if (!$tableName || !$col || !$id) {
            echo json_encode(['success' => false, 'message' => 'Missing parameters']);
            exit;
        }
        
        // Check if we're in JSON mode
        if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
            try {
                // For flat structure, id is the key name
                if ($col === 'value') {
                    $jsonDb->update($tableName, [$col => $val], [
                        'key' => ['operator' => '=', 'value' => $id]
                    ]);
                } else {
                    $jsonDb->update($tableName, [$col => $val], [
                        'id' => ['operator' => '=', 'value' => $id]
                    ]);
                }
                echo json_encode(['success' => true]);
            } catch (Exception $e) {
                echo json_encode(['success' => false, 'message' => $e->getMessage()]);
            }
        } else {
            // SQL Mode
            $pkCol = getPrimaryKey($pdo, $tableName);
            if (!$pkCol) {
                echo json_encode(['success' => false, 'message' => 'No Primary Key found']);
                exit;
            }
            
            try {
                $stmt = $pdo->prepare("UPDATE `$tableName` SET `$col` = ? WHERE `$pkCol` = ?");
                $stmt->execute([$val, $id]);
                echo json_encode(['success' => true]);
            } catch (Exception $e) {
                echo json_encode(['success' => false, 'message' => $e->getMessage()]);
            }
        }
        exit;
    }
    // --- SMART EXPORT SINGLE ROW ---
    elseif ($action === 'export_single_row') {
        header('Content-Type: application/json');
        $table = $_POST['table'] ?? '';
        $pk = $_POST['pk'] ?? '';
        $val = $_POST['val'] ?? '';
        $format = $_POST['format'] ?? 'json';

        if (!$table || !$pk || !$val) {
            echo json_encode(['success' => false, 'message' => 'Missing parameters']);
            exit;
        }

        try {
            $row = null;
            if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
                $tableData = $jsonDb->select($table, [$pk => ['operator' => '=', 'value' => $val]]);
                $row = $tableData[0] ?? null;
            } else {
                $stmt = $pdo->prepare("SELECT * FROM `$table` WHERE `$pk` = ?");
                $stmt->execute([$val]);
                $row = $stmt->fetch(PDO::FETCH_ASSOC);
            }

            if (!$row) {
                echo json_encode(['success' => false, 'message' => 'Row not found']);
                exit;
            }

            $content = '';
            if ($format === 'json') {
                $content = json_encode($row, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
            } elseif ($format === 'csv') {
                $fp = fopen('php://temp', 'r+');
                fputcsv($fp, array_keys($row), ',', '"', "\\");
                fputcsv($fp, array_values($row), ',', '"', "\\");
                rewind($fp);
                $content = stream_get_contents($fp);
                fclose($fp);
            } elseif ($format === 'sql') {
                $keys = array_keys($row);
                $vals = array_map(function($v) use ($pdo) {
                    return $v === null ? "NULL" : $pdo->quote($v);
                }, array_values($row));
                $content = "INSERT INTO `$table` (`" . implode('`, `', $keys) . "`) VALUES (" . implode(', ', $vals) . ");";
            }

            echo json_encode(['success' => true, 'content' => $content]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- BULK EXPORT TO CLIPBOARD ---
    elseif ($action === 'bulk_export_clipboard') {
        header('Content-Type: application/json');
        $table = $_POST['table'] ?? '';
        $ids = json_decode($_POST['ids'] ?? '[]', true);
        $format = $_POST['format'] ?? 'json';

        if (!$table || empty($ids)) {
            echo json_encode(['success' => false, 'message' => 'Missing parameters']);
            exit;
        }

        try {
            $rows = [];
            if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
                // JSON Mode
                $pk = 'id'; // Default for our JSON DB
                foreach ($ids as $id) {
                    $item = $jsonDb->select($table, [$pk => ['operator' => '=', 'value' => $id]]);
                    if (!empty($item)) $rows[] = $item[0];
                }
            } else {
                // SQL Mode
                $pk = getPrimaryKey($pdo, $table);
                if (!$pk) {
                    echo json_encode(['success' => false, 'message' => 'No Primary Key found']);
                    exit;
                }
                $in  = str_repeat('?,', count($ids) - 1) . '?';
                $stmt = $pdo->prepare("SELECT * FROM `$table` WHERE `$pk` IN ($in)");
                $stmt->execute($ids);
                $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            }

            if (empty($rows)) {
                echo json_encode(['success' => false, 'message' => 'No data found']);
                exit;
            }

            $content = '';
            if ($format === 'json') {
                $content = json_encode($rows, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
            } elseif ($format === 'csv') {
                $fp = fopen('php://temp', 'r+');
                fputcsv($fp, array_keys($rows[0]), ',', '"', "\\");
                foreach ($rows as $r) {
                    fputcsv($fp, array_values($r), ',', '"', "\\");
                }
                rewind($fp);
                $content = stream_get_contents($fp);
                fclose($fp);
            } elseif ($format === 'sql') {
                foreach ($rows as $row) {
                    $keys = array_keys($row);
                    $vals = array_map(function($v) use ($pdo) {
                        return $v === null ? "NULL" : $pdo->quote($v);
                    }, array_values($row));
                    $content .= "INSERT INTO `$table` (`" . implode('`, `', $keys) . "`) VALUES (" . implode(', ', $vals) . ");\n";
                }
            }

            echo json_encode(['success' => true, 'content' => $content]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- GET COLUMN SUGGESTIONS ---
    elseif ($action === 'get_column_suggestions') {
        header('Content-Type: application/json');
        $tableName = $_POST['table'] ?? '';
        $col = $_POST['column'] ?? '';
        
        if (!$tableName || !$col) {
            echo json_encode(['success' => false, 'message' => 'Missing parameters']);
            exit;
        }
        
        try {
            if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
                $tableData = $jsonDb->select($tableName);
                $suggestions = array_unique(array_filter(array_column($tableData, $col)));
                $suggestions = array_slice($suggestions, 0, 50);
            } else {
                $stmt = $pdo->prepare("SELECT DISTINCT `$col` FROM `$tableName` WHERE `$col` IS NOT NULL AND `$col` != '' LIMIT 50");
                $stmt->execute();
                $suggestions = $stmt->fetchAll(PDO::FETCH_COLUMN);
            }
            echo json_encode(['success' => true, 'suggestions' => array_values($suggestions)]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }

    // --- GET TABLE STRUCTURE ---
    elseif ($action === 'get_table_structure') {
        header('Content-Type: application/json');
        try {
            $stmt = $pdo->query("SHOW CREATE TABLE `$table`");
            $row = $stmt->fetch(PDO::FETCH_NUM);
            if ($row) {
                echo json_encode(['success' => true, 'sql' => $row[1] . ";"]);
            } else {
                echo json_encode(['success' => false, 'message' => 'Table not found']);
            }
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- GET TABLE COLUMNS (Detailed with FKs) ---
    elseif ($action === 'get_table_columns') {
        header('Content-Type: application/json');
        try {
            // 1. Get Columns
            $stmt = $pdo->query("DESCRIBE `$table`");
            $rawCols = $stmt->fetchAll(PDO::FETCH_ASSOC);

            // 2. Get Foreign Keys
            $dbName = $_SESSION['db_name'];
            $sqlFK = "SELECT COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME 
                      FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE 
                      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? AND REFERENCED_TABLE_NAME IS NOT NULL";
            $stmtFK = $pdo->prepare($sqlFK);
            $stmtFK->execute([$dbName, $table]);
            
            $fks = [];
            while($row = $stmtFK->fetch(PDO::FETCH_ASSOC)) {
                $fks[$row['COLUMN_NAME']] = [
                    'table' => $row['REFERENCED_TABLE_NAME'],
                    'col' => $row['REFERENCED_COLUMN_NAME']
                ];
            }

            $columns = [];
            $referencedTablesData = [];
            $uniqueRefTables = [];

            foreach ($rawCols as $col) {
                // Exclude auto_increment columns
                if (stripos($col['Extra'], 'auto_increment') !== false) {
                    continue;
                }

                $colName = $col['Field'];
                $isNullable = $col['Null'] === 'YES';
                $fkInfo = $fks[$colName] ?? null;
                $fkData = [];

                if ($fkInfo) {
                    $refTable = $fkInfo['table'];
                    $refCol = $fkInfo['col'];
                    $uniqueRefTables[$refTable] = $refCol;
                    
                    try {
                        // Fetch distinct values for the dropdown list (legacy support for simple dropdowns)
                        $stmtVal = $pdo->query("SELECT DISTINCT `$refCol` FROM `$refTable` ORDER BY `$refCol` LIMIT 1000");
                        $fkData = $stmtVal->fetchAll(PDO::FETCH_COLUMN);
                    } catch (Exception $e) { }
                }

                $columns[] = [
                    'name' => $colName,
                    'required' => !$isNullable,
                    'type' => $col['Type'],
                    'fk' => $fkInfo,
                    'fk_values' => $fkData
                ];
            }

            // Fetch full data for unique referenced tables
            foreach ($uniqueRefTables as $refTable => $refCol) {
                try {
                    $stmtFull = $pdo->query("SELECT * FROM `$refTable` LIMIT 500");
                    $referencedTablesData[$refTable] = $stmtFull->fetchAll(PDO::FETCH_ASSOC);
                } catch (Exception $e) {
                    $referencedTablesData[$refTable] = [];
                }
            }
            
            echo json_encode([
                'success' => true, 
                'columns' => $columns,
                'referenced_tables' => $referencedTablesData
            ]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- GET ALL TABLES STRUCTURE ---
    elseif ($action === 'get_all_tables_structure') {
        header('Content-Type: application/json');
        try {
            if ($dbMode === 'sql') {
                $stmt = $pdo->query("SHOW TABLES");
                $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);
            } else {
                $stmt = $pdo->query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'");
                $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);
            }

            // Collect CREATE statements and referenced tables
            $creates = [];
            $refs = [];
            foreach ($tables as $t) {
                if ($dbMode === 'sql') {
                    $stmt = $pdo->query("SHOW CREATE TABLE `$t` ");
                    $row = $stmt->fetch(PDO::FETCH_NUM);
                    $create = $row[1] ?? '';
                } else {
                    $stmt = $pdo->query("SELECT sql FROM sqlite_master WHERE type='table' AND name='$t'");
                    $row = $stmt->fetch(PDO::FETCH_NUM);
                    $create = $row[0] ?? '';
                }
                
                if ($create) {
                    $creates[$t] = $create;
                    // Find referenced table names from FOREIGN KEY clauses
                    $matches = [];
                    preg_match_all("/REFERENCES\s+[`\"]?([^`\"\(]+)[`\"]?/i", $create, $matches);
                    $refs[$t] = array_values(array_unique($matches[1] ?? []));
                }
            }


            // Topological sort based on dependencies (referenced -> dependent)
            $inDegree = [];
            $dependents = [];
            foreach ($tables as $t) {
                $inDegree[$t] = 0;
            }
            foreach ($tables as $t) {
                foreach ($refs[$t] ?? [] as $r) {
                    if (isset($inDegree[$r])) {
                        $inDegree[$t]++;
                        $dependents[$r][] = $t;
                    }
                }
            }

            $queue = [];
            foreach ($inDegree as $t => $deg) {
                if ($deg === 0) $queue[] = $t;
            }

            $ordered = [];
            while (!empty($queue)) {
                $n = array_shift($queue);
                $ordered[] = $n;
                foreach ($dependents[$n] ?? [] as $m) {
                    $inDegree[$m]--;
                    if ($inDegree[$m] === 0) $queue[] = $m;
                }
            }

            $sql = "";
            if (count($ordered) === count($tables)) {
                // Successfully sorted, emit DROP + CREATE in order
                foreach ($ordered as $t) {
                    $sql .= "DROP TABLE IF EXISTS `$t`;\n";
                    $sql .= ($creates[$t] ?? '') . ";\n\n";
                }
            } else {
                // Cyclic or unresolved dependencies detected: fallback to safe approach
                $sql .= "SET FOREIGN_KEY_CHECKS=0;\n\n";
                foreach ($tables as $t) {
                    $sql .= "DROP TABLE IF EXISTS `$t`;\n";
                    $sql .= ($creates[$t] ?? '') . ";\n\n";
                }
                $sql .= "SET FOREIGN_KEY_CHECKS=1;\n";
            }

            if ($sql) {
                echo json_encode(['success' => true, 'sql' => $sql]);
            } else {
                echo json_encode(['success' => false, 'message' => 'No tables found']);
            }
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- DUPLICATE TABLE ---
    elseif ($action === 'duplicate_table') {
        $source = $_POST['source'] ?? '';
        $target = trim($_POST['target'] ?? '');
        $copyData = isset($_POST['copy_data']);
        
        if ($source && $target) {
            try {
                $pdo->exec("CREATE TABLE `$target` LIKE `$source`");
                if ($copyData) {
                    $pdo->exec("INSERT INTO `$target` SELECT * FROM `$source`");
                }
                redirect("?table=$target&view=structure&msg=" . urlencode("Table duplicated as $target"));
            } catch (Exception $e) {
                $error = $e->getMessage();
            }
        }
    }
    // --- BULK TABLE OPERATIONS ---
    elseif ($action === 'bulk_tables') {
        $operation = $_POST['bulk_operation'] ?? '';
        $selected = $_POST['tables'] ?? [];
        if (!$selected || !$operation) {
            $error = 'Select at least one table and an operation.';
        } else {
            $cleanTables = [];
            foreach ($selected as $tbl) {
                $clean = preg_replace('/[^A-Za-z0-9_]/', '', $tbl);
                if ($clean !== '') {
                    $cleanTables[] = $clean;
                }
            }
            if (empty($cleanTables)) {
                $error = 'No valid tables selected.';
            } else {
                try {
                    if (in_array($operation, ['drop', 'truncate'])) {
                        $orderedTables = order_tables_by_dependencies(
                            $pdo,
                            $cleanTables,
                            $_SESSION['db_name'] ?? '',
                            true
                        );
                    } else {
                        $orderedTables = $cleanTables;
                    }
                    $tablesStr = implode('`, `', $orderedTables);
                    if ($operation === 'drop') {
                        foreach ($orderedTables as $tbl) $pdo->exec("DROP TABLE `$tbl`");
                        redirect("?msg=" . urlencode(count($orderedTables) . " table(s) dropped."));
                    } elseif ($operation === 'truncate') {
                        $pdo->exec("SET FOREIGN_KEY_CHECKS=0");
                        try {
                            foreach ($orderedTables as $tbl) {
                                $pdo->exec("TRUNCATE TABLE `$tbl`");
                            }
                        } finally {
                            $pdo->exec("SET FOREIGN_KEY_CHECKS=1");
                        }
                        redirect("?msg=" . urlencode(count($orderedTables) . " table(s) truncated."));
                    } elseif (in_array($operation, ['optimize', 'analyze', 'check', 'repair'])) {
                        $sql = strtoupper($operation) . " TABLE `$tablesStr`";
                        $stmt = $pdo->query($sql);
                        $_SESSION['maintenance_data'] = $stmt->fetchAll(PDO::FETCH_ASSOC);
                        redirect("?view=maintenance&msg=" . urlencode(ucfirst($operation) . " complete."));
                    } elseif ($operation === 'export') {
                        $filename = "tables_" . date("Y-m-d_H-i-s") . ".sql";
                        header('Content-Type: application/octet-stream');
                        header("Content-Transfer-Encoding: Binary"); 
                        header("Content-disposition: attachment; filename=\"$filename\"");
                        echo "-- Adminer Bulk Export: " . date("Y-m-d H:i:s") . "\n";
                        echo "-- Database: " . $_SESSION['db_name'] . "\n";
                        echo "-- Tables: " . implode(', ', $orderedTables) . "\n\n";
                        foreach ($orderedTables as $t) {
                            $stmt = $pdo->query("SHOW CREATE TABLE `$t`");
                            $row = $stmt->fetch(PDO::FETCH_NUM);
                            echo "DROP TABLE IF EXISTS `$t`;\n";
                            echo $row[1] . ";\n\n";
                            $stmt = $pdo->query("SELECT * FROM `$t`");
                            while ($r = $stmt->fetch(PDO::FETCH_ASSOC)) {
                                $keys = array_keys($r);
                                $vals = array_values($r);
                                $vals = array_map(function($v) use ($pdo) {
                                    return $v === null ? "NULL" : $pdo->quote($v);
                                }, $vals);
                                echo "INSERT INTO `$t` (`" . implode('`, `', $keys) . "`) VALUES (" . implode(', ', $vals) . ");\n";
                            }
                            echo "\n";
                        }
                        exit;
                    } else {
                        $error = 'Unsupported bulk operation.';
                    }
                } catch (Exception $e) {
                    $error = $e->getMessage();
                }
            }
        }
    }
    // --- ADD INDEX ---
    elseif ($action === 'add_index') {
        $type = $_POST['type']; // INDEX, UNIQUE, PRIMARY
        $cols = $_POST['cols'] ?? [];
        $name = $_POST['name'] ?? '';
        
        if (!empty($cols)) {
            $colsStr = '`' . implode('`, `', $cols) . '`';
            $sql = "ALTER TABLE `$table` ADD $type ";
            if ($name && $type !== 'PRIMARY') $sql .= "`$name` ";
            $sql .= "($colsStr)";
            
            try {
                $pdo->exec($sql);
                redirect("?table=$table&view=structure&msg=" . urlencode("Index added."));
            } catch (Exception $e) {
                $error = $e->getMessage();
            }
        }
    }
    // --- DROP INDEX ---
    elseif ($action === 'drop_index') {
        $name = $_POST['name'];
        $type = $_POST['type']; // PRIMARY or name
        
        try {
            if ($name === 'PRIMARY') {
                $pdo->exec("ALTER TABLE `$table` DROP PRIMARY KEY");
            } else {
                $pdo->exec("ALTER TABLE `$table` DROP INDEX `$name`");
            }
            redirect("?table=$table&view=structure&msg=" . urlencode("Index dropped."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- TOGGLE UNIQUE / INDEX (Bypass Unique) ---
    elseif ($action === 'convert_to_index' || $action === 'convert_to_unique') {
        $name = $_POST['name'];
        $toUnique = ($action === 'convert_to_unique');
        
        if ($name === 'PRIMARY') {
            $error = "Cannot modify PRIMARY KEY.";
        } else {
            try {
                // 1. Get current index columns
                $stmt = $pdo->query("SHOW INDEX FROM `$table` WHERE Key_name = " . $pdo->quote($name));
                $cols = [];
                while($r = $stmt->fetch()) $cols[] = "`" . $r['Column_name'] . "`";
                
                if (!$cols) throw new Exception("Index info not found.");
                $colsStr = implode(', ', $cols);
                
                // 2. Wrap in FK Check bypass AND use atomic ALTER TABLE
                // Atomic ALTER TABLE (DROP and ADD in one go) is more likely to succeed 
                // because the requirement for an index is checked at the end of the statement.
                $pdo->exec("SET FOREIGN_KEY_CHECKS = 0");
                try {
                    $type = $toUnique ? "UNIQUE INDEX" : "INDEX";
                    $sql = "ALTER TABLE `$table` DROP INDEX `$name`, ADD $type `$name` ($colsStr)";
                    $pdo->exec($sql);
                } finally {
                    $pdo->exec("SET FOREIGN_KEY_CHECKS = 1");
                }
                
                $msg = $toUnique ? "Unique constraint restored for `$name`." : "Unique constraint removed. Index `$name` is now Normal.";
                redirect("?table=$table&view=structure&msg=" . urlencode($msg));
            } catch (Exception $e) {
                $error = "Bypass Failed: " . $e->getMessage();
                if ($toUnique && strpos($error, '1062') !== false) {
                    $error = "Gagal mengaktifkan Unique: Terdapat data duplikat pada tabel. Bersihkan data duplikat terlebih dahulu.";
                }
            }
        }
    }
    elseif ($action === 'add_fk') {
        $name = $_POST['name'] ?? '';
        $col = $_POST['col'];
        $refTable = $_POST['ref_table'];
        $refCol = $_POST['ref_col'];
        $onDelete = $_POST['on_delete'];
        $onUpdate = $_POST['on_update'];
        
        $sql = "ALTER TABLE `$table` ADD ";
        if ($name) $sql .= "CONSTRAINT `$name` ";
        $sql .= "FOREIGN KEY (`$col`) REFERENCES `$refTable` (`$refCol`)";
        if ($onDelete) $sql .= " ON DELETE $onDelete";
        if ($onUpdate) $sql .= " ON UPDATE $onUpdate";
        
        try {
            $pdo->exec($sql);
            redirect("?table=$table&view=structure&msg=" . urlencode("Foreign Key added."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- DROP FOREIGN KEY ---
    elseif ($action === 'drop_fk') {
        $name = $_POST['name'];
        try {
            $pdo->exec("ALTER TABLE `$table` DROP FOREIGN KEY `$name`");
            redirect("?table=$table&view=structure&msg=" . urlencode("Foreign Key dropped."));
        } catch (Exception $e) {
            $error = $e->getMessage();
        }
    }
    // --- BULK ROW OPERATIONS (DELETE & EXPORT) ---
    elseif (in_array($action, ['bulk_delete', 'bulk_edit', 'export_sql', 'export_csv', 'export_json'])) {
        $ids = $_POST['ids'] ?? [];
        $pk = $_POST['pk'] ?? null;
        
        if ($table && $pk && !empty($ids)) {
            $placeholders = implode(',', array_fill(0, count($ids), '?'));
            
            if ($action === 'bulk_delete') {
                try {
                    $sql = "DELETE FROM `$table` WHERE `$pk` IN ($placeholders)";
                    $stmt = $pdo->prepare($sql);
                    $stmt->execute($ids);
                    $count = $stmt->rowCount();
                    redirect("?table=$table&view=data&msg=" . urlencode("$count rows deleted."));
                } catch (Exception $e) {
                    $error = $e->getMessage();
                }
            } elseif ($action === 'bulk_edit') {
                $bulkCol = $_POST['bulk_col'] ?? '';
                $bulkVal = $_POST['bulk_val'] ?? '';
                if ($bulkCol) {
                    try {
                        $sql = "UPDATE `$table` SET `$bulkCol` = ? WHERE `$pk` IN ($placeholders)";
                        $stmt = $pdo->prepare($sql);
                        $params = array_merge([$bulkVal === '' ? null : $bulkVal], $ids);
                        $stmt->execute($params);
                        $count = $stmt->rowCount();
                        redirect("?table=$table&view=data&msg=" . urlencode("$count rows updated."));
                    } catch (Exception $e) {
                        $error = $e->getMessage();
                    }
                }
            } else {
                // EXPORT SELECTED
                $sql = "SELECT * FROM `$table` WHERE `$pk` IN ($placeholders)";
                $stmt = $pdo->prepare($sql);
                $stmt->execute($ids);
                $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
                $filename = $table . "_selected_" . date("Y-m-d_H-i-s");

                if ($action === 'export_json') {
                    header('Content-Type: application/json');
                    header("Content-disposition: attachment; filename=\"$filename.json\"");
                    echo json_encode($rows, JSON_PRETTY_PRINT);
                } elseif ($action === 'export_csv') {
                    header('Content-Type: text/csv');
                    header("Content-disposition: attachment; filename=\"$filename.csv\"");
                    $out = fopen('php://output', 'w');
                    if ($rows) {
                        fputcsv($out, array_keys($rows[0]), ',', '"', "\\");
                        foreach ($rows as $r) fputcsv($out, $r, ',', '"', "\\");
                    }
                    fclose($out);
                } elseif ($action === 'export_sql') {
                    header('Content-Type: application/octet-stream');
                    header("Content-disposition: attachment; filename=\"$filename.sql\"");
                    echo "-- Export Selected Rows from `$table`\n";
                    foreach ($rows as $r) {
                        $keys = array_keys($r);
                        $vals = array_map(function($v) use ($pdo) {
                            return $v === null ? "NULL" : $pdo->quote($v);
                        }, array_values($r));
                        echo "INSERT INTO `$table` (`" . implode('`, `', $keys) . "`) VALUES (" . implode(', ', $vals) . ");\n";
                    }
                }
                exit;
            }
        } else {
             $error = "No rows selected or primary key missing.";
        }
    }
    // --- MANAGE DATABASE LIST (JSON) ---
    elseif ($action === 'add_database_list') {
        $dbName = trim($_POST['name'] ?? '');
        
        $config = load_config($configFile);
