                    $c['data_col'] = (isset($_POST['data_col']) && strpos($_POST['data_col'], ',') !== false) ? explode(',', $_POST['data_col']) : ($_POST['data_col'] ?? $c['data_col']);
                    $c['type'] = $_POST['type'] ?? $c['type'];
