        redirect("?msg=" . urlencode("Chart updated."));
    }

    // --- GET CHART DATA (AJAX) ---
    elseif ($action === 'get_chart_data') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        
        $chartId = $_POST['id'] ?? '';
        $config = load_config($configFile);
        $chart = null;
        if (isset($config['charts'])) {
            foreach ($config['charts'] as $c) {
                if ($c['id'] === $chartId) {
                    $chart = $c;
                    break;
                }
            }
        }
        
        if (!$chart || !isset($pdo)) {
            echo json_encode(['success' => false, 'message' => 'Chart not found']);
            exit;
        }
        
        try {
            $table = $chart['table'];
            $labelCol = $chart['label_col'];
            $displayCol = $chart['label_display_col'] ?? '';
            $refTable = $chart['referenced_table'] ?? '';
            $refCol = $chart['referenced_column'] ?? '';
            $dateCol = $chart['date_col'] ?? '';
            $dateRange = $_POST['date_range'] ?? '';
            
            $calc = $chart['calc_mode'] ?? 'COUNT';
            $dataCols = $chart['data_col'] ?? ['*'];
            if (empty($dataCols)) $dataCols = ['*'];
            if (!is_array($dataCols)) $dataCols = explode(',', (string)$dataCols);
            $dataCols = array_filter(array_map('trim', $dataCols));
            if (empty($dataCols)) $dataCols = ['*'];
            
            $limit = (int)($chart['limit'] ?? 5);
            $limitClause = $limit > 0 ? "LIMIT $limit" : "";
            
            $where = "1=1";
            $params = [];
            
            $filterCol = $chart['filter_col'] ?? $labelCol;
            $filterOp = $chart['filter_op'] ?? 'LIKE';
            $filterVal = $chart['filter_keyword'] ?? '';
            
            if ($filterCol && ($filterVal !== '' || in_array($filterOp, ['IS NULL', 'IS NOT NULL']))) {
                switch($filterOp) {
                    case '=': case '!=': case '>': case '<': case '>=': case '<=':
                        $where .= " AND `$filterCol` $filterOp ?";
                        $params[] = $filterVal;
                        break;
                    case 'CONTAINS': case 'LIKE':
                        $where .= " AND `$filterCol` LIKE ?";
                        $params[] = '%' . $filterVal . '%';
                        break;
                    case 'STARTS':
                        $where .= " AND `$filterCol` LIKE ?";
                        $params[] = $filterVal . '%';
                        break;
                    case 'ENDS':
                        $where .= " AND `$filterCol` LIKE ?";
                        $params[] = '%' . $filterVal;
                        break;
                    case 'IS NULL':
                        $where .= " AND `$filterCol` IS NULL";
                        break;
                    case 'IS NOT NULL':
                        $where .= " AND `$filterCol` IS NOT NULL";
                        break;
                }
            }
            if ($dateCol && $dateRange) {
                $dates = explode(' to ', $dateRange);
                if (count($dates) === 2) {
                    $where .= " AND `$dateCol` >= ? AND `$dateCol` <= ?";
                    $params[] = $dates[0] . ' 00:00:00';
                    $params[] = $dates[1] . ' 23:59:59';
                } elseif (count($dates) === 1) {
                    $where .= " AND `$dateCol` LIKE ?";
                    $params[] = $dates[0] . '%';
                }
            }

            $series = [];
            foreach ($dataCols as $dCol) {
                if ($dCol === '*' || empty($dCol)) {
                    $aggFunc = "COUNT(*)";
                    if ($calc !== 'COUNT') $aggFunc = "$calc(1)"; // Fallback for SUM(*) etc
                } else {
                    $aggFunc = "$calc(`$dCol`)";
                }
                
                if ($displayCol && $refTable && $refCol) {
                    $sql = "SELECT t2.`$displayCol` as label, $aggFunc as value 
                            FROM `$table` t1
                            JOIN `$refTable` t2 ON t1.`$labelCol` = t2.`$refCol`
                            WHERE $where
                            GROUP BY t2.`$displayCol` 
                            ORDER BY value DESC 
                            $limitClause";
                } else {
                    $sql = "SELECT `$labelCol` as label, $aggFunc as value 
                            FROM `$table` 
                            WHERE $where
                            GROUP BY `$labelCol` 
                            ORDER BY value DESC 
                            $limitClause";
                }
                
                $stmt = $pdo->prepare($sql);
                $stmt->execute($params);
                $res = $stmt->fetchAll(PDO::FETCH_ASSOC);
                
                $series[$dCol] = [
                    'label' => ($calc === 'COUNT' && $dCol === '*') ? 'Total Rows' : "$calc($dCol)",
                    'data' => $res
                ];
            }

            $firstSeriesKey = array_key_first($series);
            if (!$firstSeriesKey) throw new Exception("No data columns defined.");
            
            $labels = array_column($series[$firstSeriesKey]['data'], 'label');
            
            $finalDatasets = [];
            foreach ($series as $colName => $s) {
                $valMap = [];
                foreach ($s['data'] as $r) $valMap[$r['label']] = $r['value'];
                
                $dataValues = [];
                foreach ($labels as $lbl) $dataValues[] = $valMap[$lbl] ?? 0;
                
                $finalDatasets[] = [
                    'label' => $s['label'],
                    'data' => $dataValues
                ];
            }
            
            echo json_encode([
                'success' => true,
                'table' => $table,
                'label_col' => $labelCol,
                'labels' => $labels,
                'datasets' => $finalDatasets
            ]);
            exit;
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
            exit;
        }
    }
    // --- SMART SEEDER ---
    elseif ($action === 'seed_data') {
        $sTable = $_POST['table'] ?? '';
        $sCount = (int)($_POST['count'] ?? 10);
        $sConfig = $_POST['field_types'] ?? []; 
        $manualVals = $_POST['manual_values'] ?? [];
        
        if ($sTable && !empty($sConfig) && isset($pdo)) {
            try {
                $pdo->beginTransaction();
                $columns = array_keys($sConfig);
                $placeholders = implode(', ', array_fill(0, count($columns), '?'));
                $sql = "INSERT INTO `$sTable` (`" . implode('`, `', $columns) . "`) VALUES ($placeholders)";
                $stmt = $pdo->prepare($sql);
                
                // Cache for foreign key IDs to avoid redundant queries
                $fkCache = [];
                $successRows = 0;
                $failedRows = 0;
                $lastError = '';

                for ($i = 0; $i < $sCount; $i++) {
                    $rowValues = [];
                    foreach ($sConfig as $col => $type) {
                        // Priority 1: Manual Value
                        if (!empty($manualVals[$col])) {
                            $rowValues[] = $manualVals[$col];
                            continue;
                        }

                        // Priority 2: Foreign Key detection
                        if (strpos($type, 'fk:') === 0) {
                            $refPart = substr($type, 3); // table.column
                            if (!isset($fkCache[$refPart])) {
                                list($refTable, $refCol) = explode('.', $refPart);
                                try {
                                    $fkStmt = $pdo->query("SELECT `$refCol` FROM `$refTable` LIMIT 100");
                                    $fkCache[$refPart] = $fkStmt->fetchAll(PDO::FETCH_COLUMN);
                                } catch (Exception $e) { $fkCache[$refPart] = []; }
                            }
                            if (!empty($fkCache[$refPart])) {
                                $rowValues[] = $fkCache[$refPart][array_rand($fkCache[$refPart])];
                            } else {
                                $rowValues[] = null;
                            }
                            continue;
                        }

                        // Priority 3: Enum values
                        if (strpos($type, 'enum:') === 0) {
                            $options = explode(',', substr($type, 5));
                            $rowValues[] = $options[array_rand($options)];
                            continue;
                        }

                        // Priority 4: Guess standard type if empty
                        if ($type === '') {
                             if (preg_match('/_?id$/i', $col) || preg_match('/_?count$/i', $col)) $type = 'number';
                             elseif (preg_match('/_?at$/i', $col) || preg_match('/date/i', $col)) $type = 'datetime';
                             elseif (preg_match('/is_/i', $col) || preg_match('/has_/i', $col)) $type = 'boolean';
                        }

                        // Priority 5: Standard Fake Data
                        $rowValues[] = generate_fake_data($type, $i);
                    }
                    try {
                        $stmt->execute($rowValues);
                        $successRows++;
                    } catch (PDOException $e) {
                        $failedRows++;
                        $lastError = $e->getMessage();
                    }
                }
                
                $pdo->commit();
                $msg = "Successfully seeded $successRows rows.";
                if ($failedRows > 0) $msg .= " ($failedRows failed. Error: " . htmlspecialchars($lastError) . ")";
                redirect("?table=$sTable&view=data&msg=" . urlencode($msg));
            } catch (Exception $e) {
                if ($pdo->inTransaction()) $pdo->rollBack();
                $error = "Seeding Error: " . $e->getMessage();
            }
        }
    }
    // --- SAVE GITHUB CONFIG (PER DATABASE) ---
    elseif ($action === 'save_github_config') {
        $cfg = load_config($configFile);
        $dbName = $_POST['db_name'] ?? '';
        
        // Initialize backup_configs if not exists
        if (!isset($cfg['backup_configs'])) {
