    // --- SAVE TELEGRAM CONFIG (PER DATABASE) ---
    elseif ($action === 'save_telegram_config') {
        $cfg = load_config($configFile);
        $dbName = $_POST['db_name'] ?? '';
        
        // Initialize backup_configs if not exists
        if (!isset($cfg['backup_configs'])) {
            $cfg['backup_configs'] = [];
        }
        
        // Initialize database config if not exists
        if (!isset($cfg['backup_configs'][$dbName])) {
            $cfg['backup_configs'][$dbName] = [];
        }
        
        // Save Telegram config for this database
        $cfg['backup_configs'][$dbName]['telegram'] = [
            'enabled' => isset($_POST['tg_enabled']) && $_POST['tg_enabled'] === '1',
            'token' => trim($_POST['tg_token'] ?? ''),
            'chat_id' => trim($_POST['tg_chat_id'] ?? ''),
            'base' => trim($_POST['tg_base'] ?? 'https://api.telegram.org'),
            'tag' => $_POST['tg_tag'] ?? 'unorganized',
            'auto' => $_POST['tg_auto'] ?? '',
            'use_zip' => isset($_POST['tg_zip']) && $_POST['tg_zip'] === '1' ? '1' : '0',
            'zip_password' => $_POST['tg_zip_password'] ?? '',
            'last_backup' => $cfg['backup_configs'][$dbName]['telegram']['last_backup'] ?? 0,
            'last_health_report' => $cfg['backup_configs'][$dbName]['telegram']['last_health_report'] ?? 0,
            'history' => $cfg['backup_configs'][$dbName]['telegram']['history'] ?? []
        ];
        
        save_config($configFile, $cfg);
        redirect("?msg=" . urlencode("Telegram settings saved for database: $dbName"));
    }
    
    elseif ($action === 'push_telegram_backup') {
        @set_time_limit(1800); // Increased for multi-file backups
        while (ob_get_level()) ob_end_clean(); 
        header('Content-Type: application/json');
        
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) {
            echo json_encode(['success' => false, 'message' => 'No database selected']);
            exit;
        }

        $mode = $_POST['mode'] ?? 'single';
        $selectedTables = $_POST['tables'] ?? [];
        if (!is_array($selectedTables) && !empty($selectedTables)) {
            $selectedTables = explode(',', $selectedTables);
        }
        $selectedTables = array_filter(array_map('trim', (array)$selectedTables));
        
        if ($mode === 'per_table' && empty($selectedTables)) {
            $selectedTables = $pdo->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN);
        }

        $allConfig = load_config($configFile);
        $cfg = $allConfig['backup_configs'][$dbName]['telegram'] ?? null;
        
        if (!$cfg || empty($cfg['token']) || empty($cfg['chat_id'])) {
            echo json_encode(['success' => false, 'message' => 'Telegram not configured']);
            exit;
        }

        try {
            $tmpDir = __DIR__ . DIRECTORY_SEPARATOR . 'temp_backups';
            if (!is_dir($tmpDir)) @mkdir($tmpDir, 0755, true);
            
            $results = [];
            $tablesToProcess = ($mode === 'per_table') ? $selectedTables : ['_combined_'];

            foreach ($tablesToProcess as $table) {
                $isCombined = ($table === '_combined_');
                $filename = "backup_" . ($dbName) . ($isCombined ? "" : "_$table") . "_" . date('Y-m-d_H-i-s') . ".sql";
                $finalFile = $tmpDir . DIRECTORY_SEPARATOR . $filename;
                $tablesForDump = $isCombined ? $selectedTables : [$table];

                $generatedFiles = dump_database_to_files_split($pdo, $finalFile, $dbName, $tablesForDump, 0); 
                if (empty($generatedFiles)) {
                    throw new Exception("Failed to generate dump for " . ($isCombined ? "database" : "table $table"));
                }

                foreach ($generatedFiles as $fileToUpload) {
                    $filename = basename($fileToUpload);
                    $mimeType = 'text/plain';

                    if (($cfg['use_zip'] ?? '0') === '1' && class_exists('ZipArchive')) {
                        $zipFile = $fileToUpload . ".zip";
                        $zip = new ZipArchive();
                        if ($zip->open($zipFile, ZipArchive::CREATE | ZipArchive::OVERWRITE) === TRUE) {
                            $pass = $cfg['zip_password'] ?? '';
                            if (!empty($pass)) $zip->setPassword($pass);
                            $zip->addFile($fileToUpload, $filename);
                            if (!empty($pass) && method_exists($zip, 'setEncryptionName')) {
                                $zip->setEncryptionName($filename, ZipArchive::EM_AES_256);
                            }
                            $zip->close();
                            @unlink($fileToUpload);
                            $fileToUpload = $zipFile;
                            $filename .= ".zip";
                            $mimeType = 'application/zip';
                        }
                    }

                    $fileSize = filesize($fileToUpload);
                    $postFields = [
                        'chat_id' => $cfg['chat_id'],
                        'document' => new CURLFile($fileToUpload, $mimeType, $filename),
                        'caption' => "📦 DB Backup: " . ($dbName) . ($isCombined ? "" : "\n📑 Table: $table") . "\n🏷 Tag: #" . ($cfg['tag'] ?? 'general') . "\n📅 Date: " . date('Y-m-d H:i:s')
                    ];

                    $resData = telegram_api_request('sendDocument', $postFields, $cfg);
                    @unlink($fileToUpload);

                    if (isset($resData['ok']) && $resData['ok']) {
                        $results[] = $filename;
                        
                        // Log history only for combined or at least once per set
                        $config = load_config($configFile);
                        if (!isset($config['backup_configs'][$dbName]['telegram'])) $config['backup_configs'][$dbName]['telegram'] = [];
                        $config['backup_configs'][$dbName]['telegram']['last_backup'] = time();
                        if (!isset($config['backup_configs'][$dbName]['telegram']['history'])) $config['backup_configs'][$dbName]['telegram']['history'] = [];
                        
                        array_unshift($config['backup_configs'][$dbName]['telegram']['history'], [
                            'name' => $filename,
                            'date' => time(),
                            'file_id' => $resData['result']['document']['file_id'] ?? '',
                            'message_id' => $resData['result']['message_id'] ?? '',
                            'tag' => $cfg['tag'] ?? 'unorganized',
                            'size' => $fileSize
                        ]);
                        $config['backup_configs'][$dbName]['telegram']['history'] = array_slice($config['backup_configs'][$dbName]['telegram']['history'], 0, 20);
                        save_config($configFile, $config);
                    } else {
                        throw new Exception("Telegram Error for $filename: " . ($resData['error'] ?? 'API Error'));
                    }
                }
            }

            echo json_encode(['success' => true, 'message' => count($results) . " backup file(s) sent successfully."]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- RESTORE FROM TELEGRAM ---
    elseif ($action === 'restore_telegram_backup') {
        @set_time_limit(900); // 15 mins for large restores
        while (ob_get_level()) ob_end_clean(); 
        header('Content-Type: application/json');
        $fileId = $_POST['file_id'] ?? '';
        
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) {
            echo json_encode(['success' => false, 'message' => 'No database selected']);
            exit;
        }
        
        $allConfig = load_config($configFile);
        $cfg = $allConfig['backup_configs'][$dbName]['telegram'] ?? null;
        
        if (!$cfg || !$fileId) {
            echo json_encode(['success' => false, 'message' => 'Invalid request']);
            exit;
        }

        $tmpDir = __DIR__ . DIRECTORY_SEPARATOR . 'temp_backups';
        if (!is_dir($tmpDir)) @mkdir($tmpDir, 0755, true);
        $tmpSql = $tmpDir . DIRECTORY_SEPARATOR . 'restore_' . uniqid() . '.sql';

        try {
            $password = $_POST['password'] ?? '';
            $apiBase = rtrim($cfg['base'] ?? 'https://api.telegram.org', '/');

            // 1. Get File Path from Telegram
            $getRes = @file_get_contents("$apiBase/bot{$cfg['token']}/getFile?file_id=$fileId");
            $getFile = json_decode($getRes, true);
            if (!$getFile['ok']) throw new Exception("Telegram could not locate file");
            
            $filePath = $getFile['result']['file_path'];
            $downloadUrl = "$apiBase/file/bot{$cfg['token']}/$filePath";
            
            // 2. Download directly to file
            if (!download_url_to_file($downloadUrl, $tmpSql)) {
                throw new Exception("Failed to download file from Telegram.");
            }

            // Check if it's a ZIP file
            if (strpos($filePath, '.zip') !== false && class_exists('ZipArchive')) {
                $zip = new ZipArchive();
                if ($zip->open($tmpSql) === TRUE) {
                    if (!empty($password)) {
                        $zip->setPassword($password);
                    }
                    $sqlName = $zip->getNameIndex(0);
                    $extractedPath = $tmpDir . DIRECTORY_SEPARATOR . 'ext_' . uniqid() . '.sql';
                    
                    // Extract first file
                    if ($zip->extractTo($tmpDir, [$sqlName])) {
                        $extractedFile = $tmpDir . DIRECTORY_SEPARATOR . $sqlName;
                        $zip->close();
                        @unlink($tmpSql); // Delete zip
                        $tmpSql = $extractedFile; // Point to extracted SQL
                    } else {
                        $zip->close();
                        throw new Exception("Failed to extract ZIP.");
                    }
                } else {
                    throw new Exception("Failed to open ZIP file.");
                }
            }

            // 3. Execute SQL via Streaming
            if ($dbMode === 'sql' && isset($pdo)) {
                if (stream_sql_to_db($pdo, $tmpSql)) {
                    @unlink($tmpSql);
                    echo json_encode(['success' => true, 'message' => 'Restored successfully from Telegram!']);
                } else {
                    throw new Exception("Failed to stream SQL to database.");
                }
            } else {
                 throw new Exception("Restore only supported in SQL mode");
            }
        } catch (Exception $e) {
            if (file_exists($tmpSql)) @unlink($tmpSql);
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- DELETE FROM TELEGRAM INDEX & CHAT ---
    elseif ($action === 'delete_telegram_backup') {
        while (ob_get_level()) ob_end_clean(); 
        header('Content-Type: application/json');
        $dateId = $_POST['date_id'] ?? '';
        $msgId = $_POST['message_id'] ?? '';
        
        // Get current database name
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) {
            echo json_encode(['success' => false, 'message' => 'No database selected']);
            exit;
        }
        
        $config = load_config($configFile);
        $cfg = $config['backup_configs'][$dbName]['telegram'] ?? null;

        if (!$cfg || !$dateId) {
            echo json_encode(['success' => false, 'message' => 'Invalid request']);
            exit;
        }

        try {
            // 1. Try to delete from Telegram Chat (if message_id exists)
            if ($msgId && !empty($cfg['token'])) {
                @file_get_contents("https://api.telegram.org/bot{$cfg['token']}/deleteMessage?chat_id={$cfg['chat_id']}&message_id=$msgId");
            }

            // 2. Remove from Local Index for this database
            if (isset($config['backup_configs'][$dbName]['telegram']['history'])) {
                $config['backup_configs'][$dbName]['telegram']['history'] = array_filter(
                    $config['backup_configs'][$dbName]['telegram']['history'], 
                    function($h) use ($dateId) {
                        return (string)$h['date'] !== (string)$dateId;
                    }
                );
                $config['backup_configs'][$dbName]['telegram']['history'] = array_values($config['backup_configs'][$dbName]['telegram']['history']);
                save_config($configFile, $config);
            }

            echo json_encode(['success' => true, 'message' => 'Backup removed from index and chat.']);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- BULK DELETE FROM TELEGRAM ---
    elseif ($action === 'bulk_delete_telegram_backup') {
        while (ob_get_level()) ob_end_clean(); 
        header('Content-Type: application/json');
        $items = $_POST['items'] ?? '[]';
        if (!is_array($items)) $items = json_decode($items, true);

        $dbName = $_SESSION['db_name'] ?? '';
        $config = load_config($configFile);
        $cfg = $config['backup_configs'][$dbName]['telegram'] ?? null;

        if (!$cfg || empty($items)) {
            echo json_encode(['success' => false, 'message' => 'Invalid request']);
            exit;
        }

        $successCount = 0;
        foreach ($items as $item) {
            $dateId = $item['date'] ?? '';
            $msgId = $item['message_id'] ?? '';
            
            if ($msgId && !empty($cfg['token'])) {
                @file_get_contents("https://api.telegram.org/bot{$cfg['token']}/deleteMessage?chat_id={$cfg['chat_id']}&message_id=$msgId");
            }

            if (isset($config['backup_configs'][$dbName]['telegram']['history'])) {
                $config['backup_configs'][$dbName]['telegram']['history'] = array_filter(
                    $config['backup_configs'][$dbName]['telegram']['history'], 
                    function($h) use ($dateId) {
                        return (string)$h['date'] !== (string)$dateId;
                    }
                );
            }
            $successCount++;
        }
        
        if (isset($config['backup_configs'][$dbName]['telegram']['history'])) {
            $config['backup_configs'][$dbName]['telegram']['history'] = array_values($config['backup_configs'][$dbName]['telegram']['history']);
            save_config($configFile, $config);
        }

        echo json_encode(['success' => true, 'message' => "$successCount items removed."]);
        exit;
    }
    // --- TELEGRAM HEALTH REPORT ---
    elseif ($action === 'send_telegram_health_report') {
        @set_time_limit(180);
        while (ob_get_level()) ob_end_clean(); 
        header('Content-Type: application/json');
        $cfg = load_config($configFile)['telegram'] ?? null;
        if (!$cfg || empty($cfg['token']) || empty($cfg['chat_id'])) {
            echo json_encode(['success' => false, 'message' => 'Telegram not configured']);
            exit;
        }

        try {
            $dbName = $_SESSION['db_name'] ?? 'db';
            $health = get_db_health($pdo, $dbName, $dbMode);
            
            $message = "📊 <b>Smart Database Report: $dbName</b>\n";
            $message .= "━━━━━━━━━━━━━━━━━━\n";
            $message .= "⏱ Time: " . date('Y-m-d H:i') . "\n";
            $message .= "💾 Total Size: " . formatSize($health['data_size']) . "\n";
            $message .= "📁 Total Tables: " . $health['tables_count'] . "\n\n";
            
            if ($dbMode === 'sql' && isset($pdo)) {
                $message .= "<b>Top 3 Tables (Rows):</b>\n";
                $topTables = $pdo->query("SELECT TABLE_NAME, TABLE_ROWS FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$dbName' ORDER BY TABLE_ROWS DESC LIMIT 3")->fetchAll(PDO::FETCH_ASSOC);
                foreach($topTables as $t) {
                    $message .= "🔹 " . htmlspecialchars($t['TABLE_NAME']) . ": " . number_format($t['TABLE_ROWS']) . " rows\n";
                }
            }
            
            $message .= "\n🖥 <b>Server Status:</b>\n";
            $message .= "⚡ PHP: " . PHP_VERSION . " on " . PHP_OS . "\n";
            if (function_exists('disk_free_space') && function_exists('disk_total_space')) {
                $free = @disk_free_space(".");
                $total = @disk_total_space(".");
                if ($free && $total) {
                    $message .= "💽 Disk Free: " . formatSize($free) . " / " . formatSize($total) . " (" . round(($free/$total)*100) . "%)\n";
                }
            }

            $postFields = [
                'chat_id' => $cfg['chat_id'],
                'text' => $message,
                'parse_mode' => 'HTML'
            ];

            $resData = telegram_api_request('sendMessage', $postFields, $cfg);

            if (isset($resData['ok']) && $resData['ok']) {
                $config = load_config($configFile);
                $config['telegram']['last_health_report'] = time();
                save_config($configFile, $config);
                echo json_encode(['success' => true, 'message' => 'Health Report sent.']);
            } else {
                echo json_encode(['success' => false, 'message' => $resData['error'] ?? ($resData['description'] ?? 'API Error')]);
            }
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- PUSH BACKUP TO GITHUB ---
    elseif ($action === 'push_github_backup') {
        @set_time_limit(0);
        @ignore_user_abort(true);
        @ini_set('memory_limit', '1024M');
        while (ob_get_level()) ob_end_clean(); 
        header('Content-Type: application/json');
        
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) {
            echo json_encode(['success' => false, 'message' => 'No database selected']);
            exit;
        }

        $mode = $_POST['mode'] ?? 'single';
        $selectedTables = $_POST['tables'] ?? [];
        if (!is_array($selectedTables) && !empty($selectedTables)) {
            $selectedTables = explode(',', $selectedTables);
        }
        $selectedTables = array_filter(array_map('trim', (array)$selectedTables));

        if ($mode === 'per_table' && empty($selectedTables)) {
            $selectedTables = $pdo->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN);
        }
        
        $allConfig = load_config($configFile);
        $cfg = $allConfig['backup_configs'][$dbName]['github'] ?? null;
        
        if (!$cfg || empty($cfg['token']) || empty($cfg['repo'])) {
            echo json_encode(['success' => false, 'message' => 'GitHub not configured']);
            exit;
        }

        try {
            $tmpDir = __DIR__ . DIRECTORY_SEPARATOR . 'temp_backups';
            if (!is_dir($tmpDir)) @mkdir($tmpDir, 0755, true);
            @unlink($tmpDir . DIRECTORY_SEPARATOR . 'cancel_backup.flag');

            $results = $_SESSION['gh_backup_progress'] ?? [];
            $resumeMode = !empty($results);
            
            $tablesToProcess = ($mode === 'per_table') ? $selectedTables : ['_combined_'];
            
            // If resuming, filter out already done tables
            if ($resumeMode && $mode === 'per_table') {
                $tablesToProcess = array_filter($tablesToProcess, function($t) use ($results) {
                    // Check if any part of this table was uploaded (rough check)
                    foreach ($results as $r) { if (strpos($r, "_$t" . "_") !== false) return false; }
                    return true;
                });
            }

            $totalTables = count($tablesToProcess);
            $tableIndex = 0;

            foreach ($tablesToProcess as $table) {
                $tableIndex++;
                $isCombined = ($table === '_combined_');
                
                // Update Status: Creating (Write & Close immediately)
                if (session_status() === PHP_SESSION_NONE) @session_start();
                $_SESSION['gh_backup_status'] = [
                    'table' => $isCombined ? 'Database' : $table,
                    'table_index' => $tableIndex,
                    'total_tables' => $totalTables,
                    'status' => 'Creating SQL...',
                    'part' => 0,
                    'total_parts' => 0
                ];
                session_write_close(); 

                $filename = "backup_" . ($dbName) . ($isCombined ? "" : "_$table") . "_" . date('Y-m-d_H-i-s') . ".sql";
                $finalFile = $tmpDir . DIRECTORY_SEPARATOR . $filename;
                $tablesForDump = $isCombined ? $selectedTables : [$table];

                // Split at 20MB
                $generatedFiles = dump_database_to_files_split($pdo, $finalFile, $dbName, $tablesForDump, 20000000); 
                if (empty($generatedFiles)) {
                    throw new Exception("Failed to generate dump for " . ($isCombined ? "database" : "table $table"));
                }

                $partCount = count($generatedFiles);
                $partIndex = 0;

                foreach ($generatedFiles as $partFile) {
                    $partIndex++;
                    $filenamePart = basename($partFile);
                    if (!file_exists($partFile)) continue;
                    
                    if (file_exists($tmpDir . DIRECTORY_SEPARATOR . 'cancel_backup.flag')) {
                        if (session_status() === PHP_SESSION_NONE) @session_start();
                        unset($_SESSION['gh_backup_status']);
                        session_write_close();
                        throw new Exception("Backup cancelled by user.");
                    }

                    // Update Status: Pushing (Write & Close immediately)
                    if (session_status() === PHP_SESSION_NONE) @session_start();
                    $_SESSION['gh_backup_status'] = [
                        'table' => $isCombined ? 'Database' : $table,
                        'table_index' => $tableIndex,
                        'total_tables' => $totalTables,
                        'status' => "Pushing to GitHub...",
                        'part' => $partIndex,
                        'total_parts' => $partCount
                    ];
                    session_write_close(); 

                    @set_time_limit(600); // Reset timer for each part
                    $content = base64_encode(file_get_contents($partFile));
                    
                    $basePath = trim($cfg['path'] ?? 'backups/', '/');
                    $dailyFolder = date('Y-m-d');
                    // Add table folder to prevent cluttering even within daily folder
                    $tableSubFolder = $isCombined ? 'full_backup' : $table;
                    $pathStr = ltrim($basePath . '/' . $dailyFolder . '/' . $tableSubFolder . '/' . $filenamePart, '/');
                    $pathSegments = array_map('rawurlencode', explode('/', $pathStr));
                    $encPath = implode('/', $pathSegments);
                    
                    $user = !empty($cfg['user']) ? $cfg['user'] : explode('/', $cfg['repo'])[0];
                    $repo = strpos($cfg['repo'], '/') !== false ? explode('/', $cfg['repo'])[1] : $cfg['repo'];
                    $apiUrl = "https://api.github.com/repos/" . rawurlencode($user) . "/" . rawurlencode($repo) . "/contents/{$encPath}";
                    
                    $payload = json_encode([
                        'message' => "Backup DB: $dbName" . ($isCombined ? "" : " (Table: $table)") . " - " . date('Y-m-d H:i:s'),
                        'content' => $content,
                        'branch' => $cfg['branch'] ?? 'main'
                    ]);

                    $maxRetries = 3;
                    $success = false;
                    $lastErr = '';

                    for ($attempt = 1; $attempt <= $maxRetries; $attempt++) {
                        $ch = curl_init($apiUrl);
                        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                        curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "PUT");
                        curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
                        curl_setopt($ch, CURLOPT_HTTPHEADER, [
                            "Authorization: token {$cfg['token']}",
                            "User-Agent: Adminer-Lite-Backup",
                            "Content-Type: application/json",
                            "Expect:" 
                        ]);
                        
                        $response = curl_exec($ch);
                        $curlErr = curl_error($ch);
                        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
                        curl_close($ch);

                        if ($httpCode >= 200 && $httpCode < 300) {
                            $success = true;
                            $tableSubFolder = $isCombined ? 'full_backup' : $table;
                            $results[] = "{$tableSubFolder}/{$filenamePart}";
                            if (session_status() === PHP_SESSION_NONE) @session_start();
                            $_SESSION['gh_backup_progress'] = $results; 
                            session_write_close();
                            @unlink($partFile); 
                            break;
                        } else {
                            $err = json_decode($response, true);
                            $lastErr = $err['message'] ?? ($curlErr ?: "HTTP $httpCode");
                            if ($attempt < $maxRetries) sleep(1);
                        }
                    }

                    // Free memory
                    unset($content);
                    unset($payload);
                    unset($response);

                    if (!$success) {
                        if (session_status() === PHP_SESSION_NONE) @session_start();
                        unset($_SESSION['gh_backup_status']);
                        session_write_close();
                        throw new Exception("GitHub Error for $filenamePart: $lastErr (Tried $maxRetries times).");
                    }
                }
            }

            // --- AUTO-GENERATE / UPDATE README.MD ---
            try {
                $readmePath = trim($cfg['path'] ?? 'backups/', '/') . '/' . date('Y-m-d') . '/README.md';
                $readmeUrl = "https://api.github.com/repos/" . rawurlencode($user) . "/" . rawurlencode($repo) . "/contents/" . rawurlencode($readmePath);
                
                // 1. Fetch existing SHA for update
                $ch = curl_init($readmeUrl . "?ref=" . ($cfg['branch'] ?? 'main'));
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_HTTPHEADER, ["Authorization: token {$cfg['token']}", "User-Agent: Adminer-Lite-Backup"]);
                $infoJson = curl_exec($ch);
                $info = json_decode($infoJson, true);
                $sha = $info['sha'] ?? null;
                curl_close($ch);

                // 2. Prepare content
                $readmeMarkdown = "# 🗄️ Database Backup: $dbName\n\n";
                $readmeMarkdown .= "> **Last Updated:** " . date('Y-m-d H:i:s') . "\n\n";
                $readmeMarkdown .= "## 📊 Session Summary\n";
                $readmeMarkdown .= "- **Database:** `$dbName` \n";
                $readmeMarkdown .= "- **Backup Mode:** " . ($mode === 'per_table' ? "Per Table (Split)" : "Combined File") . "\n";
                $readmeMarkdown .= "- **Files in this session:** " . count($results) . " files\n\n";
                $readmeMarkdown .= "### 📄 Files Uploaded:\n";
                foreach ($results as $file) {
                    $readmeMarkdown .= "- `$file` \n";
                }
                $readmeMarkdown .= "\n---\n_This documentation was automatically generated by Adminer Lite Cloud Backup system._";

                // 3. Upload to GitHub
                $payload = json_encode([
                    'message' => "Update README for backup session: " . date('Y-m-d H:i:s'),
                    'content' => base64_encode($readmeMarkdown),
                    'sha' => $sha,
                    'branch' => $cfg['branch'] ?? 'main'
                ]);

                $ch = curl_init($readmeUrl);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "PUT");
                curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
                curl_setopt($ch, CURLOPT_HTTPHEADER, [
                    "Authorization: token {$cfg['token']}",
                    "User-Agent: Adminer-Lite-Backup",
                    "Content-Type: application/json"
                ]);
                curl_exec($ch);
                curl_close($ch);
            } catch (Exception $e) {
                // Ignore README errors to not fail the whole backup
            }

            // Success! Clear progress & status
            if (session_status() === PHP_SESSION_NONE) @session_start();
            unset($_SESSION['gh_backup_status']);
            unset($_SESSION['gh_backup_progress']);
            session_write_close();

            // Update last backup time if combined or finished
            $config = load_config($configFile);
            if (!isset($config['backup_configs'][$dbName]['github'])) $config['backup_configs'][$dbName]['github'] = [];
            $config['backup_configs'][$dbName]['github']['last_backup'] = time();
            save_config($configFile, $config);

            while (ob_get_level()) ob_end_clean();
            header('Content-Type: application/json');
            echo json_encode(['success' => true, 'message' => count($results) . " file(s) pushed to GitHub."]);
        } catch (Exception $e) {
            while (ob_get_level()) ob_end_clean();
            header('Content-Type: application/json');
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- GET GITHUB BACKUP STATUS (FOR POLLING) ---
    elseif ($action === 'get_gh_backup_status') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        if (session_status() === PHP_SESSION_NONE) @session_start();
        $status = $_SESSION['gh_backup_status'] ?? ['status' => 'idle'];
        session_write_close();
        echo json_encode($status);
        exit;
    }
    // --- CANCEL GITHUB BACKUP ---
    elseif ($action === 'cancel_github_backup') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        $tmpDir = __DIR__ . DIRECTORY_SEPARATOR . 'temp_backups';
        if (!is_dir($tmpDir)) @mkdir($tmpDir, 0755, true);
        file_put_contents($tmpDir . DIRECTORY_SEPARATOR . 'cancel_backup.flag', '1');
        
        if (session_status() === PHP_SESSION_NONE) @session_start();
        $_SESSION['gh_backup_status'] = ['status' => 'Cancelling... Please wait.'];
        session_write_close();
        
        echo json_encode(['success' => true]);
        exit;
    }
    // --- CLEAR GITHUB PROGRESS ---
    elseif ($action === 'clear_github_progress') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        unset($_SESSION['gh_backup_progress']);
        echo json_encode(['success' => true]);
        exit;
    }
    // --- FETCH EXTERNAL SQL ---
    elseif ($action === 'fetch_external_sql') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        $url = $_POST['url'] ?? '';
        if (empty($url)) {
            echo json_encode(['success' => false, 'message' => 'URL is empty']);
            exit;
        }

        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($ch, CURLOPT_USERAGENT, 'Adminer-Lite-Visualizer');
        curl_setopt($ch, CURLOPT_TIMEOUT, 30);
        $content = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($httpCode === 200) {
            echo json_encode(['success' => true, 'sql' => $content]);
        } else {
            echo json_encode(['success' => false, 'message' => "Failed to fetch. HTTP Code: $httpCode"]);
        }
        exit;
    }
    // --- GET GITHUB BACKUPS ---
    elseif ($action === 'get_github_backups') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) { echo json_encode([]); exit; }
        
        $allConfig = load_config($configFile);
        $cfg = $allConfig['backup_configs'][$dbName]['github'] ?? null;
        
        if (!$cfg || empty($cfg['token']) || empty($cfg['repo']) || empty($cfg['user'])) {
            echo json_encode([]); exit;
        }

        $token = $cfg['token'];
        $user = $cfg['user'];
        $repo = $cfg['repo'];
        $basePath = trim($cfg['path'], '/');

        // Recursive function to fetch all files from GitHub
        function fetchFilesRecursive($apiUrl, $token, &$allFiles, $currentPath = '') {
            $ch = curl_init($apiUrl);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_HTTPHEADER, [
                "Authorization: token $token",
                "User-Agent: Adminer-Lite-Backup"
            ]);
            $response = curl_exec($ch);
            $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);

            if ($httpCode !== 200) return;

            $items = json_decode($response, true);
            if (!is_array($items)) return;

            foreach ($items as $item) {
                if ($item['type'] === 'file' && strpos($item['name'], '.sql') !== false) {
                    $allFiles[] = [
                        'name' => ($currentPath ? $currentPath . '/' : '') . $item['name'],
                        'download_url' => $item['download_url'],
                        'size' => $item['size'],
                        'path' => $item['path'],
                        'sha' => $item['sha']
                    ];
                } elseif ($item['type'] === 'dir') {
                    // Limit recursion depth to prevent API abuse, but enough for Date/Table structure
                    fetchFilesRecursive($item['url'], $token, $allFiles, ($currentPath ? $currentPath . '/' : '') . $item['name']);
                }
            }
        }

        $allFiles = [];
        $rootUrl = "https://api.github.com/repos/" . rawurlencode($user) . "/" . rawurlencode($repo) . "/contents/" . rawurlencode($basePath);
        fetchFilesRecursive($rootUrl, $token, $allFiles);

        // Sort by name descending (usually latest dates first)
        usort($allFiles, function($a, $b) {
            return strcmp($b['name'], $a['name']);
        });

        echo json_encode($allFiles);
        exit;
    }
    // --- RESTORE FROM GITHUB ---
    elseif ($action === 'restore_github_backup') {
        header('Content-Type: application/json');
        while (ob_get_level()) ob_end_clean();
        
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) {
            echo json_encode(['success' => false, 'message' => 'No database selected']);
            exit;
        }
        
        $allConfig = load_config($configFile);
        $cfg = $allConfig['backup_configs'][$dbName]['github'] ?? null;
        $urls = $_POST['urls'] ?? $_POST['url'] ?? '';
        if (is_string($urls)) $urls = explode(',', $urls);
        $urls = array_filter(array_map('trim', $urls));
        
        if (!$cfg || empty($cfg['token']) || empty($urls)) {
            echo json_encode(['success' => false, 'message' => 'Invalid request or URLs missing']);
            exit;
        }

        try {
            $tmpDir = __DIR__ . DIRECTORY_SEPARATOR . 'temp_backups';
            if (!is_dir($tmpDir)) @mkdir($tmpDir, 0755, true);

            $pdo->exec("SET FOREIGN_KEY_CHECKS=0");

            foreach ($urls as $url) {
                $tmpSql = $tmpDir . DIRECTORY_SEPARATOR . 'restore_gh_' . uniqid() . '.sql';
                
                $ch = curl_init($url);
                $fp = fopen($tmpSql, 'w+');
                curl_setopt($ch, CURLOPT_FILE, $fp);
                curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
                curl_setopt($ch, CURLOPT_HTTPHEADER, [
                    "Authorization: token {$cfg['token']}",
                    "User-Agent: Adminer-Lite-Backup"
                ]);
                curl_exec($ch);
                curl_close($ch);
                fclose($fp);

                if (!file_exists($tmpSql) || filesize($tmpSql) === 0) {
                    throw new Exception("Failed to download part: " . basename($url));
                }

                if (!stream_sql_to_db($pdo, $tmpSql)) {
                    @unlink($tmpSql);
                    throw new Exception("Error processing part: " . basename($url));
                }
                @unlink($tmpSql);
            }

            $pdo->exec("SET FOREIGN_KEY_CHECKS=1");
            echo json_encode(['success' => true]);
        } catch (Exception $e) {
            echo json_encode(['success' => false, 'message' => $e->getMessage()]);
        }
        exit;
    }
    // --- CLEAR TEMP BACKUPS ---
    elseif ($action === 'clear_temp_backups') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        
        $tmpDir = __DIR__ . DIRECTORY_SEPARATOR . 'temp_backups';
        if (is_dir($tmpDir)) {
            $files = glob($tmpDir . DIRECTORY_SEPARATOR . '*');
            $count = 0;
            foreach ($files as $file) {
                if (is_file($file)) {
                    @unlink($file);
                    $count++;
                }
            }
            echo json_encode(['success' => true, 'message' => "$count temporary file(s) cleared."]);
        } else {
            echo json_encode(['success' => true, 'message' => "Temp directory does not exist or already empty."]);
        }
        exit;
    }
    // --- DELETE FROM GITHUB ---
    elseif ($action === 'delete_github_backup') {
        while (ob_get_level()) ob_end_clean();
        header('Content-Type: application/json');
        
        // Get current database name
        $dbName = $_SESSION['db_name'] ?? '';
        if (empty($dbName)) {
            echo json_encode(['success' => false, 'message' => 'No database selected']);
            exit;
        }
        
        // Load config for this specific database
        $allConfig = load_config($configFile);
        $cfg = $allConfig['backup_configs'][$dbName]['github'] ?? null;
        
        $path = $_POST['path'] ?? '';
        $sha = $_POST['sha'] ?? '';
        
        if (!$cfg || empty($cfg['token']) || empty($cfg['repo']) || empty($cfg['user']) || !$path || !$sha) {
            echo json_encode(['success' => false, 'message' => 'GitHub not configured or parameters missing']);
            exit;
        }

        $pathStr = ltrim($path, '/');
        $pathSegments = array_map('rawurlencode', explode('/', $pathStr));
        $encPath = implode('/', $pathSegments);
        $apiUrl = "https://api.github.com/repos/" . rawurlencode($cfg['user']) . "/" . rawurlencode($cfg['repo']) . "/contents/{$encPath}";
        
        $payload = json_encode([
            'message' => 'Delete backup via Adminer ' . basename($path),
            'sha' => $sha
        ]);

        $ch = curl_init($apiUrl);
        curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "DELETE");
        curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HTTPHEADER, [
            "Authorization: token {$cfg['token']}",
            "User-Agent: Adminer-Lite-Backup",
            "Content-Type: application/json"
        ]);
        $response = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($httpCode >= 200 && $httpCode < 300) {
            echo json_encode(['success' => true]);
        } else {
            $err = json_decode($response, true);
            echo json_encode(['success' => false, 'message' => $err['message'] ?? 'Failed to delete backup from GitHub']);
        }
        exit;
    }
    // --- CLONE TABLE ---
    elseif ($action === 'clone_table') {
        $sourceTable = $_POST['table'] ?? '';
        $newTable = $_POST['new_name'] ?? '';
        $copyData = isset($_POST['copy_data']) && $_POST['copy_data'] == '1';
        
        if ($sourceTable && $newTable && isset($pdo) && $dbMode === 'sql') {
            try {
                $pdo->exec("CREATE TABLE `$newTable` LIKE `$sourceTable`");
                if ($copyData) {
                    $pdo->exec("INSERT INTO `$newTable` SELECT * FROM `$sourceTable`");
                }
                redirect("?table=$newTable&msg=" . urlencode("Table cloned successfully to $newTable."));
            } catch (Exception $e) {
                $error = "Cloning Error: " . $e->getMessage();
            }
        } elseif ($dbMode !== 'sql') {
            $error = "Cloning is only supported for SQL mode at this time.";
        }
    }
    // --- GENERATE DATA DICTIONARY ---
    elseif ($action === 'generate_dictionary') {
        while (ob_get_level()) ob_end_clean();
        $dbName = $_SESSION['db_name'] ?? 'database';
        $filename = "dictionary_{$dbName}_" . date("Y-m-d_H-i") . ".md";
        
        header('Content-Type: text/markdown');
        header("Content-disposition: attachment; filename=\"$filename\"");
        
        echo "# Data Dictionary: `$dbName`\n";
        echo "Generated on: " . date("Y-m-d H:i:s") . "\n\n";

        if ($dbMode === 'sql' && isset($pdo)) {
            $tables = $pdo->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN);
            foreach ($tables as $t) {
                echo "## Table: `$t`\n\n";
                echo "| Column | Type | Null | Key | Default | Extra |\n";
                echo "| :--- | :--- | :--- | :--- | :--- | :--- |\n";
                $cols = $pdo->query("DESCRIBE `$t`")->fetchAll(PDO::FETCH_ASSOC);
                foreach ($cols as $c) {
                    $null = $c['Null'] === 'YES' ? 'Yes' : 'No';
                    $def = $c['Default'] === null ? 'NULL' : $c['Default'];
                    echo "| `{$c['Field']}` | {$c['Type']} | $null | {$c['Key']} | $def | {$c['Extra']} |\n";
                }
                echo "\n";
            }
        } elseif ($dbMode === 'sqlite' && isset($pdo)) {
            $stmt = $pdo->query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'");
            $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);
            foreach ($tables as $t) {
                echo "## Table: `$t`\n\n";
                echo "| Column | Type | Null | Key | Default |\n";
                echo "| :--- | :--- | :--- | :--- | :--- |\n";
                $cols = $pdo->query("PRAGMA table_info(`$t`)")->fetchAll(PDO::FETCH_ASSOC);
                foreach ($cols as $c) {
                    $null = $c['notnull'] ? 'No' : 'Yes';
                    $key = $c['pk'] ? 'PRI' : '';
                    $def = $c['dflt_value'] === null ? 'NULL' : $c['dflt_value'];
                    echo "| `{$c['name']}` | {$c['type']} | $null | $key | $def |\n";
                }
                echo "\n";
            }
        } else {
             echo "Data Dictionary generator only supports SQL and SQLite modes.";
        }
        exit;
    }
    // --- MANAGE DATABASE SERVER (SQL) ---
    elseif ($action === 'create_database_server') {
        $dbName = trim($_POST['name'] ?? '');
        
        $config = load_config($configFile);
        $dbUser = $config['user'] ?? '';
        $dbName = apply_database_prefix($dbName, $dbUser, $hostProfile);

        if ($dbName && is_valid_db_name($dbName)) {
            try {
                $pdo->exec("CREATE DATABASE `$dbName`");
                $msg = "Database '$dbName' created on server.";
                // Auto add to list
                $currentList = $config['databases'] ?? [];
                if (!in_array($dbName, $currentList)) {
                    $currentList[] = $dbName;
                    save_config($configFile, ['databases' => $currentList]);
                }
            } catch (Exception $e) {
                $error = $e->getMessage();
            }
        } else {
            $error = "Invalid database name.";
        }
        redirect("?view=manage_dbs&msg=" . urlencode($msg ?? '') . "&error=" . urlencode($error ?? ''));
    }
    elseif ($action === 'drop_database_server') {
        $dbName = $_POST['name'] ?? '';
        if ($dbName) {
            try {
                $pdo->exec("DROP DATABASE `$dbName`");
                $msg = "Database '$dbName' dropped from server.";
                // Remove from list too
                $currentList = load_config($configFile)['databases'] ?? [];
                if (($key = array_search($dbName, $currentList)) !== false) {
                    unset($currentList[$key]);
                    save_config($configFile, ['databases' => array_values($currentList)]);
                }
            } catch (Exception $e) {
                $error = $e->getMessage();
            }
        }
        redirect("?view=manage_dbs&msg=" . urlencode($msg ?? '') . "&error=" . urlencode($error ?? ''));
    }

    // --- CREATE TABLE ---
    elseif ($action === 'create_table') {
        $name = trim($_POST['name'] ?? '');
        $engine = $_POST['engine'] ?? 'InnoDB';
        $collation = $_POST['collation'] ?? 'utf8mb4_general_ci';
        $cols = $_POST['fields'] ?? [];
        $comments = $_POST['comments'] ?? '';

        if (!$name || empty($cols)) {
            $error = "Table name and at least one column are required.";
        } else {
            $defs = [];
            $primary = [];
            
            foreach ($cols as $c) {
                $cName = trim($c['name']);
                if (!$cName) continue;
                
                $cType = $c['type'];
                $cLen = trim($c['length']);
                $cDefault = $c['default'];
                $cDefaultVal = $c['default_val'] ?? '';
                $cNull = isset($c['null']) ? 'NULL' : 'NOT NULL';
                $cAi = isset($c['ai']) ? 'AUTO_INCREMENT' : '';
                $cIndex = $c['index'] ?? ''; 
                
                $def = "`$cName` $cType";
                if ($cLen !== '') $def .= "($cLen)";
                
                $def .= " $cNull";
                
                if ($cDefault === 'NULL') {
                    $def .= " DEFAULT NULL";
                } elseif ($cDefault === 'CURRENT_TIMESTAMP') {
                    $def .= " DEFAULT CURRENT_TIMESTAMP";
                } elseif ($cDefault === 'USER_DEFINED') {
                    $def .= " DEFAULT " . $pdo->quote($cDefaultVal);
                }
                
                if ($cAi) $def .= " AUTO_INCREMENT";
                
                if ($cIndex === 'PRI') {
                    $primary[] = "`$cName`";
                } elseif ($cIndex === 'UNI') {
                    $def .= " UNIQUE";
                }
                
                $defs[] = $def;
                
                if ($cIndex === 'IDX') {
                    $defs[] = "KEY `idx_$cName` (`$cName`)";
                }
            }
            
            if ($primary) {
                $defs[] = "PRIMARY KEY (" . implode(', ', $primary) . ")";
            }
            
            $sql = "CREATE TABLE `$name` (\n" . implode(",\n", $defs) . "\n) ENGINE=$engine DEFAULT COLLATE=$collation";
            if ($comments) $sql .= " COMMENT=" . $pdo->quote($comments);
            
            try {
                $pdo->exec($sql);
                redirect("?table=" . urlencode($name) . "&view=structure&msg=" . urlencode("Table $name created."));
            } catch (Exception $e) {
                $error = $e->getMessage();
            }
        }
    }
    // --- IMPORT EXCEL ---
    elseif ($action === 'import_excel') {
        header('Content-Type: application/json');
        $input = json_decode(file_get_contents('php://input'), true);

        $tableName = $input['table'] ?? '';
        $importType = $input['importType'] ?? 'insert';
        $primaryKeyCol = $input['primaryKeyCol'] ?? '';
        $truncateTable = $input['truncateTable'] ?? false;
        $headers = $input['headers'] ?? [];
        $data = $input['data'] ?? [];

        if (!$tableName || empty($headers) || empty($data)) {
            echo json_encode(['success' => false, 'message' => 'Missing table name, headers, or data.']);
            exit;
        }

        // Validate table name (simple alphanumeric and underscore check)
        if (!preg_match('/^[a-zA-Z0-9_]+$/', $tableName)) {
            echo json_encode(['success' => false, 'message' => 'Invalid table name.']);
            exit;
        }

        if (($importType === 'update' || $importType === 'upsert') && !$primaryKeyCol) {
            echo json_encode(['success' => false, 'message' => 'Primary Key Column is required for Update/Upsert import types.']);
            exit;
        }
        
        $insertedRows = 0;
        $updatedRows = 0;

        try {
            if ($truncateTable) {
                // Disable FK checks to allow truncate
                $pdo->exec("SET FOREIGN_KEY_CHECKS = 0");
                $pdo->exec("TRUNCATE TABLE `$tableName`");
                $pdo->exec("SET FOREIGN_KEY_CHECKS = 1");
            }

            $pdo->beginTransaction();

            // Fetch actual column names and types from the database
            $stmt = $pdo->query("DESCRIBE `$tableName`");
            $dbColumnsInfo = $stmt->fetchAll(PDO::FETCH_ASSOC);
            $dbColumns = array_column($dbColumnsInfo, 'Field');
            $dbColumnTypes = [];
            foreach ($dbColumnsInfo as $colInfo) {
                $dbColumnTypes[$colInfo['Field']] = strtolower((string)$colInfo['Type']);
            }
            
            // Map Excel headers to database columns
            $mappedHeaders = [];
            foreach ($headers as $excelCol) {
                // Find a case-insensitive match in dbColumns
                $found = false;
                // Strip special characters like '*' often used in templates for required fields
                $cleanExcel = strtolower(preg_replace('/[^a-z0-9]/i', '', (string)$excelCol));
                
                foreach ($dbColumns as $dbCol) {
                    $cleanDb = strtolower(preg_replace('/[^a-z0-9]/i', '', (string)$dbCol));
                    if ($cleanExcel === $cleanDb || strcasecmp(trim((string)$excelCol), trim((string)$dbCol)) === 0) {
                        $mappedHeaders[] = $dbCol; // Use the actual DB column name
                        $found = true;
                        break;
                    }
                }
                if (!$found) {
                    $mappedHeaders[] = null; // Mark as unmappable
                }
            }

            // Filter out unmappable columns from data rows
            $filteredData = [];
            foreach ($data as $row) {
                $newRow = [];
                foreach ($mappedHeaders as $index => $dbCol) {
                    if ($dbCol !== null) {
                        $val = $row[$index] ?? null;

                        // Handle Excel Serial Date conversion
                        // Excel serials are numbers, usually between 10000 and 60000 for current ranges
                        if ($val !== null && is_numeric($val) && $val > 0) {
                            $type = $dbColumnTypes[$dbCol] ?? '';
                            if (strpos($type, 'date') !== false || strpos($type, 'timestamp') !== false) {
                                // Simple check: if it looks like a serial number (e.g. 39617)
                                // and the destination is a date/time column
                                if (preg_match('/^\d+(\.\d+)?$/', (string)$val)) {
                                    try {
                                        $fVal = (float)$val;
                                        $base = new DateTime('1899-12-30');
                                        $days = (int)$fVal;
                                        $seconds = round(($fVal - $days) * 86400);
                                        $base->modify("+$days days");
                                        if ($seconds > 0) {
                                            $base->modify("+$seconds seconds");
                                            $val = $base->format(strpos($type, 'datetime') !== false ? 'Y-m-d H:i:s' : 'Y-m-d');
                                        } else {
                                            $val = $base->format('Y-m-d');
                                        }
                                    } catch (Exception $e) {
                                        // Fallback to original value if conversion fails
                                    }
                                }
                            }
                        }

                        $newRow[$dbCol] = $val;
                    }
                }
                if (!empty($newRow)) {
                    $filteredData[] = $newRow;
                }
            }

            if (empty($filteredData)) {
                if ($pdo->inTransaction()) $pdo->rollBack();
                echo json_encode(['success' => false, 'message' => 'No mappable data rows found after header matching.']);
                exit;
            }

            $validMappedHeaders = array_values(array_filter($mappedHeaders));
            $placeholders = implode(', ', array_fill(0, count($validMappedHeaders), '?'));
            $cols = implode('`, `', $validMappedHeaders);

            if ($importType === 'insert') {
                $sql = "INSERT INTO `$tableName` (`$cols`) VALUES ($placeholders)";
                $stmt = $pdo->prepare($sql);
            } elseif ($importType === 'update') {
                // This assumes primaryKeyCol is in headers and dbColumns
                if (!in_array($primaryKeyCol, $validMappedHeaders)) {
                    if ($pdo->inTransaction()) $pdo->rollBack();
                    echo json_encode(['success' => false, 'message' => "Primary Key Column '$primaryKeyCol' not found in Excel headers or database table."]);
                    exit;
                }
                $setParts = [];
                foreach ($validMappedHeaders as $col) {
                    if ($col !== $primaryKeyCol) {
                        $setParts[] = "`$col` = ?";
                    }
                }
                if (empty($setParts)) {
                    if ($pdo->inTransaction()) $pdo->rollBack();
                    echo json_encode(['success' => false, 'message' => 'No non-primary key columns found for update.']);
                    exit;
                }
                $sql = "UPDATE `$tableName` SET " . implode(', ', $setParts) . " WHERE `$primaryKeyCol` = ?";
                $stmt = $pdo->prepare($sql);
            } elseif ($importType === 'upsert') {
                $updateParts = [];
                foreach ($validMappedHeaders as $col) {
                    $updateParts[] = "`$col` = VALUES(`$col`)";
                }
                $sql = "INSERT INTO `$tableName` (`$cols`) VALUES ($placeholders) ON DUPLICATE KEY UPDATE " . implode(', ', $updateParts);
                $stmt = $pdo->prepare($sql);
            }

            $pdo->exec("SET FOREIGN_KEY_CHECKS = 0");
            foreach ($filteredData as $row) {
                // Skip rows that are entirely empty
                $hasContent = false;
                foreach ($row as $val) {
                    if ($val !== null && trim((string)$val) !== '') {
                        $hasContent = true;
                        break;
                    }
                }
                if (!$hasContent) continue;

                // Skip rows where username is empty (to avoid Duplicate Entry error for '')
                // We check the 'username' key (normalized mapping)
                $usernameVal = null;
                foreach ($row as $k => $v) {
                    $cleanKey = strtolower(preg_replace('/[^a-z0-9]/i', '', (string)$k));
                    if ($cleanKey === 'username') {
                        $usernameVal = $v;
                        break;
                    }
                }
                
                // If username is found but empty, skip this row
                if ($usernameVal !== null && trim((string)$usernameVal) === '') {
                    continue;
                }
                
                $values = array_values($row);
                
                if ($importType === 'update') {
                    // For update, primary key value should be last
                    $pkVal = $row[$primaryKeyCol];
                    unset($row[$primaryKeyCol]); // Remove PK from values to be set
                    $values = array_values($row);
                    $values[] = $pkVal;
                }
                
                $stmt->execute($values);
                if ($importType === 'insert') {
                    $insertedRows++;
                } elseif ($importType === 'update') {
                    $updatedRows += $stmt->rowCount(); // rowCount() is 0 if no change, 1 if updated
                } elseif ($importType === 'upsert') {
                    // For upsert, rowCount is 1 for insert, 2 for update (affecting 2 rows: old and new)
                    $affected = $stmt->rowCount();
                    if ($affected === 1) $insertedRows++;
                    elseif ($affected === 2) $updatedRows++;
                }
            }
            $pdo->exec("SET FOREIGN_KEY_CHECKS = 1");

            $pdo->commit();
            echo json_encode([
                'success' => true,
                'message' => 'Import completed successfully.',
                'insertedRows' => $insertedRows,
                'updatedRows' => $updatedRows
            ]);

        } catch (Exception $e) {
            if ($pdo && $pdo->inTransaction()) {
                $pdo->rollBack();
            }
            error_log("Excel Import Error: " . $e->getMessage());
            echo json_encode(['success' => false, 'message' => 'Database error: ' . $e->getMessage()]);
        }
        exit;
    }
}

