/**
 * Reusable function to render a single data row
 */
function render_data_row($row, $currentTable, $primaryKey, $colTypes, $fkMap = [], $pdo = null, $tables = [], $dualConditionCols = []) {
    ob_start();
    ?>
    <tr>
        <td style="text-align:center;">
            <?php if($primaryKey): ?>
                <input type="checkbox" name="ids[]" value="<?=htmlspecialchars($row[$primaryKey])?>" class="row-checkbox">
            <?php endif; ?>
        </td>
        <td>
            <?php if($primaryKey):
                ?><a href="?table=<?=htmlspecialchars($currentTable)?>&view=form&pk=<?=urlencode($primaryKey)?>&val=<?=urlencode($row[$primaryKey])?>" style="margin-right:5px; color:var(--accent);" title="Edit Row"><i class="fas fa-edit"></i></a><?php 
                ?><a href="?table=<?=htmlspecialchars($currentTable)?>&view=form&pk=<?=urlencode($primaryKey)?>&val=<?=urlencode($row[$primaryKey])?>&mode=copy" style="margin-right:5px; color:#fbbf24;" title="Copy to Form"><i class="fas fa-copy"></i></a><?php 
                ?><button type="button" class="btn-quick-duplicate" data-table="<?=htmlspecialchars($currentTable)?>" data-pk="<?=htmlspecialchars($primaryKey)?>" data-val="<?=htmlspecialchars($row[$primaryKey])?>" style="background:none; border:none; cursor:pointer; color:#8b5cf6; padding:0; margin-right:5px;" title="Quick Duplicate"><i class="fas fa-clone"></i></button><?php
                
                $exportOnClick = sprintf(
                    "showExportRowOptions(%s, %s, %s, event)",
                    json_encode($currentTable),
                    json_encode($primaryKey),
                    json_encode($row[$primaryKey])
                );
                ?><button type="button" class="btn-smart-export" onclick="<?=htmlspecialchars($exportOnClick, ENT_QUOTES)?>" style="background:none; border:none; cursor:pointer; color:#10b981; padding:0; margin-right:5px;" title="Smart Export Row"><i class="fas fa-file-export"></i></button><?php
                ?><a href="?table=<?=urlencode($currentTable)?>&action=delete_row&pk=<?=urlencode($primaryKey)?>&val=<?=urlencode($row[$primaryKey])?>" onclick="saConfirmLink(event, 'Delete this row permanently?')" style="color:var(--danger);" title="Delete Row"><i class="fas fa-trash"></i></a><?php 
            else:
                ?><span style="opacity:0.3">-</span><?php 
            endif; ?>
        </td>
        <?php foreach ($row as $key => $val):
            $jsonAttr = '';
            $isMediaColumn = false;
            $valStr = (string)$val;
            $displayVal = $val !== null ? htmlspecialchars($valStr) : '<span style="color:#666">NULL</span>';
            
            if ($val !== null) {
                // 1. JSON Detection
                if (strpos($valStr, '{') === 0 || strpos($valStr, '[') === 0) {
                    $decoded = json_decode($valStr);
                    if (json_last_error() === JSON_ERROR_NONE && (is_object($decoded) || is_array($decoded))) {
                        $jsonAttr = ' data-json-raw="' . htmlspecialchars($valStr) . '" ';
                        $displayVal = '<div class="json-cell-wrapper" style="display:flex; align-items:center; gap:8px;">'
                                    . '<span style="font-family:monospace; background:var(--bg-hover); padding:2px 4px; border-radius:3px; font-size:0.75em; color:var(--accent); cursor:help;" title="Valid JSON Structure">JSON</span> '
                                    . '<span style="max-width:200px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">' . $displayVal . '</span>'
                                    . '<button type="button" onclick="openJsonEditorInModal(this.closest(\'td\'))" style="background:none; border:none; cursor:pointer; color:var(--accent); font-size:0.9em;" title="Open JSON Tree Editor"><i class="fas fa-project-diagram"></i></button>'
                                    . '</div>';
                        $isMediaColumn = true; 
                    }
                }

                // 2. Media Detection (only if not already matched as JSON)
                if (!$isMediaColumn) {
                    // Base64 Images
                    if (preg_match('/^data:image\/(png|jpg|jpeg|gif|webp|svg\+xml);base64,/', $valStr)) {
                        $isMediaColumn = true;
                        $displayVal = '<div style="display:flex; align-items:center; gap:8px;">'
                            . '<img src="' . htmlspecialchars($valStr) . '" class="row-media-preview" style="max-width:60px; max-height:60px; border-radius:4px; cursor:pointer; object-fit:cover;" title="Click to enlarge">'
                            . '<span style="font-size:0.8em; color:var(--text-secondary);">[Base64]</span>'
                            . '</div>';
                    }
                    // Image Files
                    elseif (preg_match('/\.(jpg|jpeg|png|gif|webp|svg|bmp|ico)$/i', $valStr) && 
                            (stripos($key, 'image') !== false || stripos($key, 'img') !== false || 
                             stripos($key, 'photo') !== false || stripos($key, 'picture') !== false ||
                             stripos($key, 'avatar') !== false || stripos($key, 'thumbnail') !== false ||
                             stripos($key, 'icon') !== false || stripos($key, 'logo') !== false)) {
                        $isMediaColumn = true;
                        $imgUrl = $valStr;
                        if (!preg_match('/^https?:\/\//', $valStr)) {
                            $imgUrl = (strpos($valStr, '/') === 0) ? $valStr : '/' . $valStr;
                        }
                        $displayVal = '<div style="display:flex; align-items:center; gap:8px;">'
                            . '<div style="position:relative; width:60px; height:60px; background:#1a1a1a; border-radius:4px; overflow:hidden;">'
                            . '<img src="' . htmlspecialchars($imgUrl) . '" style="width:100%; height:100%; object-fit:cover; cursor:pointer;" onclick="showImageModal(this.src)" title="Click to enlarge" onerror="this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';" loading="lazy">'
                            . '<div style="display:none; width:100%; height:100%; align-items:center; justify-content:center; color:#666; font-size:0.7em; text-align:center; padding:5px;">No Image</div>'
                            . '</div>'
                            . '<span style="font-size:0.8em; color:var(--text-secondary); word-break:break-all; max-width:150px; overflow:hidden; text-overflow:ellipsis;" title="' . htmlspecialchars($valStr) . '">' . htmlspecialchars(basename($valStr)) . '</span>'
                            . '</div>';
                    }
                    // Video Files
                    elseif (preg_match('/\.(mp4|webm|ogg|mov|avi)$/i', $valStr) &&
                            (stripos($key, 'video') !== false || stripos($key, 'movie') !== false || 
                             stripos($key, 'media') !== false)) {
                        $isMediaColumn = true;
                        $videoUrl = $valStr;
                        if (!preg_match('/^https?:\/\//', $valStr)) {
                            $videoUrl = (strpos($valStr, '/') === 0) ? $videoUrl : '/' . $videoUrl;
                        }
                        $displayVal = '<div style="display:flex; align-items:center; gap:8px;">'
                            . '<div style="position:relative; width:80px; height:60px; background:#1a1a1a; border-radius:4px; overflow:hidden;">'
                            . '<video style="width:100%; height:100%; object-fit:cover; cursor:pointer;" onclick="showVideoModal(this.querySelector(\'source\').src)" title="Click to play" onerror="this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';" interrupted muted>'
                            . '<source src="' . htmlspecialchars($videoUrl) . '">'
                            . '</video>'
                            . '<div style="display:none; width:100%; height:100%; align-items:center; justify-content:center; color:#666; font-size:0.7em; text-align:center; padding:5px;">No Video</div>'
                            . '</div>'
                            . '<span style="font-size:0.8em; color:var(--text-secondary); word-break:break-all; max-width:150px; overflow:hidden; text-overflow:ellipsis;" title="' . htmlspecialchars($valStr) . '">' . htmlspecialchars(basename($valStr)) . '</span>'
                            . '</div>';
                    }
                }
            }
            
            // 3. Foreign Key Logic with Enhanced Preview
            if (!$isMediaColumn && $val !== null) {
                if (isset($fkMap[$key])) {
                    $refInfo = $fkMap[$key];
                    $label = $refInfo['data'][$val] ?? null;
                    
                    // Build FK preview attributes
                    $fkAttrs = sprintf(
                        'data-fk-table="%s" data-fk-col="%s" data-fk-val="%s" data-fk-label="%s"',
                        htmlspecialchars($refInfo['table']),
                        htmlspecialchars($refInfo['col']),
                        htmlspecialchars($val),
                        htmlspecialchars($label ?? '')
                    );
                    
                    $labelDisplay = '';
                    if ($label !== null && (string)$label !== (string)$val) {
                        $labelDisplay = ' <small class="fk-label" style="color:#94a3b8;">(' . htmlspecialchars($label) . ')</small>';
                    }
                    
                    // Add from_fk parameter for breadcrumb trail
                    $navUrl = sprintf(
                        '?table=%s&view=data&search_col=%s&search_op=%s&search_val=%s&from_fk=%s',
                        htmlspecialchars($refInfo['table']),
                        htmlspecialchars($refInfo['col']),
                        urlencode('='),
                        urlencode($val),
                        urlencode($currentTable)
                    );
                    
                    $displayVal = sprintf(
                        '<div class="fk-cell-wrapper" style="display:inline-flex; align-items:center; gap:6px;">
                            <span class="fk-indicator" style="display:inline-flex; align-items:center; justify-content:center; width:18px; height:18px; background:rgba(99,102,241,0.15); border:1px solid rgba(99,102,241,0.3); border-radius:3px; font-size:10px; color:#6366f1;" title="Foreign Key">
                                <i class="fas fa-link"></i>
                            </span>
                            <a href="%s" 
                               class="fk-link" 
                               %s
                               style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); cursor:pointer;" 
                               onmouseenter="showFKTooltip(this, event)" 
                               onmouseleave="hideFKTooltip()" 
                               onclick="event.preventDefault(); showFKModal(this);"
                               title="Click to preview, Ctrl+Click to navigate">
                                %s%s
                            </a>
                            <a href="%s" 
                               style="color:#94a3b8; font-size:0.85em; opacity:0.6; text-decoration:none;" 
                               title="Open in new view">
                                <i class="fas fa-external-link-alt"></i>
                            </a>
                        </div>',
                        $navUrl,
                        $fkAttrs,
                        htmlspecialchars($val),
                        $labelDisplay,
                        $navUrl
                    );
                } elseif (substr($key, -3) === '_id') {
                    // Convention-based FK detection with smart table name guessing
                    $targetTable = guess_fk_table_name($key, $pdo, $tables);
                    
                    // Verify table exists before creating link
                    $tableExists = false;
                    if ($pdo) {
                        try {
                            $stmt = $pdo->prepare("SHOW TABLES LIKE ?");
                            $stmt->execute([$targetTable]);
                            $tableExists = (bool)$stmt->fetch();
                        } catch (Exception $e) {
                            $tableExists = false;
                        }
                    }
                    
                    if ($tableExists) {
                        $navUrl = sprintf(
                            '?table=%s&view=data&search_col=id&search_op==&search_val=%s&from_fk=%s',
                            htmlspecialchars($targetTable),
                            urlencode($val),
                            urlencode($currentTable)
                        );
                        
                        $displayVal = sprintf(
                            '<div class="fk-cell-wrapper" style="display:inline-flex; align-items:center; gap:6px;">
                                <span class="fk-indicator-convention" style="display:inline-flex; align-items:center; justify-content:center; width:18px; height:18px; background:rgba(168,85,247,0.15); border:1px solid rgba(168,85,247,0.3); border-radius:3px; font-size:10px; color:#a855f7;" title="Convention-based FK → %s">
                                    <i class="fas fa-link"></i>
                                </span>
                                <a href="%s" 
                                   style="color:#a855f7; text-decoration:none; border-bottom:1px dashed #a855f7;" 
                                   title="View Related Record in %s (Convention)">
                                    %s
                                </a>
                            </div>',
                            htmlspecialchars($targetTable),
                            $navUrl,
                            htmlspecialchars($targetTable),
                            htmlspecialchars($displayVal)
                        );
                    }
                    // If table doesn't exist, just show the value without FK link
                }
            }
            ?>
            <?php
            // 4. Dynamic Boolean Toggle Logic (Exactly 2 unique values)
            $isBoolean = false;
            $type = strtolower($colTypes[$key] ?? '');
            $uniqueVals = $dualConditionCols[$key] ?? null;

            if ($uniqueVals && count($uniqueVals) == 2) {
                $isBoolean = true;
            }

            if ($isBoolean && !$isMediaColumn && $primaryKey && !isset($fkMap[$key])) {
                $v1 = (string)$uniqueVals[0];
                $v2 = (string)$uniqueVals[1];
                
                // Fallback to identify "on" state if possible
                $positiveIndicators = ['1', 'true', 'on', 'yes', 'active', 'enabled', 'y'];
                $onValue = $v2; 
                $offValue = $v1;
                
                if (in_array(strtolower($v1), $positiveIndicators)) {
                    $onValue = $v1; $offValue = $v2;
                } elseif (in_array(strtolower($v2), $positiveIndicators)) {
                    $onValue = $v2; $offValue = $v1;
                }
                
                $checked = ((string)$val === $onValue) ? 'checked' : '';
                $displayVal = '
                <div class="toggle-container" style="display:inline-flex; align-items:center; gap:8px;" title="Toggle between: ' . htmlspecialchars($offValue) . ' and ' . htmlspecialchars($onValue) . '">
                    <label class="custom-toggle" onclick="event.stopPropagation();">
                        <input type="checkbox" ' . $checked . ' data-on="' . htmlspecialchars($onValue) . '" data-off="' . htmlspecialchars($offValue) . '" onchange="toggleBoolean(this)">
                        <span class="toggle-slider"></span>
                    </label>
                    <span class="toggle-label" style="font-size: 10px; font-weight: 600; color: var(--text-secondary); text-transform: uppercase;">' . htmlspecialchars($valStr) . '</span>
                </div>';
            }
            ?>
            <?php
            // 5. Color Picker Logic
            if (!$isBoolean && !$isMediaColumn && $primaryKey && preg_match('/^#([A-Fa-f0-9]{3}|[A-Fa-f0-9]{6})$/', trim($valStr))) {
                $jsTable = addslashes($currentTable);
                $jsCol = addslashes($key);
                $jsPk = addslashes($row[$primaryKey]);
                $displayVal = '
                <div class="color-preview-wrapper" style="display:inline-flex; align-items:center; gap:8px;">
                    <div class="color-preview-box" style="width:16px; height:16px; border-radius:4px; background:'.htmlspecialchars(trim($valStr)).'; border:1px solid rgba(255,255,255,0.2); cursor:pointer;" onclick="this.nextElementSibling.click(); event.stopPropagation();" title="Click to change color"></div>
                    <input type="color" value="'.htmlspecialchars(trim($valStr)).'" style="opacity:0; width:0; height:0; position:absolute; pointer-events:none;" onchange="updateColorValue(this, \''.$jsTable.'\', \''.$jsCol.'\', \''.$jsPk.'\')">
                    <span style="font-family:monospace; font-size:0.85rem;">'.htmlspecialchars($valStr).'</span>
                </div>';
            }
            ?>
            <td <?= $jsonAttr ?> data-col="<?=htmlspecialchars($key)?>" data-type="<?=htmlspecialchars($colTypes[$key] ?? '')?>" <?php if($primaryKey): ?>data-pk="<?=htmlspecialchars($row[$primaryKey])?>" ondblclick="makeCellEditable(this)" title="Double click to edit"<?php endif; ?> style="position:relative;" class="adminer-data-cell">
                <div class="cell-value-wrapper" style="padding-right:25px;">
                    <?=$displayVal?>
                </div>
                <button type="button" class="quick-copy-btn" onclick="copyCellContent(this, event)" title="Copy raw value" style="position:absolute; right:4px; top:50%; transform:translateY(-50%); opacity:0; transition:opacity 0.2s; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); border-radius:3px; color:var(--text-secondary); width:20px; height:20px; display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0; z-index:5;">
                    <i class="far fa-copy" style="font-size:0.75rem;"></i>
                </button>
            </td>
        <?php endforeach; ?>
    </tr>
    <?php
    return ob_get_clean();
}

if ($is_logged_in && $currentTable) {
    // Check if we're in JSON mode
    if (($_SESSION['db_mode'] ?? 'sql') === 'json' && !empty($_SESSION['json_file'])) {
        // JSON Mode
        try {
            $tableStructure = $jsonDb->getTableStructure($currentTable);
            $tableColumns = array_column($tableStructure, 'Field');
            
            if ($view === 'data' || $view === 'json_tree') {
                // Build conditions for JSON database
                $conditions = [];
                
                if ($view === 'data' && $searchVal !== '') {
                    $op = '=';
                    $val = $searchVal;
                    
                    if ($searchOp === 'LIKE') {
                        $op = 'LIKE';
                    } elseif (in_array($searchOp, ['=', '!=', '>', '<', '>=', '<='])) {
                        $op = $searchOp;
                    }
                    
                    if ($searchColumn && in_array($searchColumn, $tableColumns)) {
                        $conditions[$searchColumn] = ['operator' => $op, 'value' => $val];
                    }
                }
                
                // Fetch Total Count
                $totalDataCount = $jsonDb->count($currentTable, $conditions);
                
                // Fetch data from JSON database
                $orderDir = strtoupper($orderDir) === 'DESC' ? 'DESC' : 'ASC';
                // If in tree view, we might want ALL data or at least a large set
                $limit_val = ($view === 'json_tree') ? 9999 : $limit;
                $offset_val = ($view === 'json_tree') ? 0 : $offset;
                $tableData = $jsonDb->select($currentTable, $conditions, $orderBy, $orderDir, $limit_val, $offset_val);
            }
        } catch (Exception $e) {
            error_log("JsonDatabase error: " . $e->getMessage());
            $tableStructure = [];
            $tableColumns = [];
            $tableData = [];
        }
    } elseif (($_SESSION['db_mode'] ?? 'sql') === 'sqlite' && isset($pdo)) {
        // SQLite Mode
        $stmt = $pdo->query("PRAGMA table_info(`$currentTable`)");
        $pragmaResult = $stmt->fetchAll();
        
        // Convert SQLite PRAGMA result to MySQL DESCRIBE format
        $tableStructure = [];
        foreach ($pragmaResult as $col) {
            $tableStructure[] = [
                'Field' => $col['name'],
                'Type' => $col['type'],
                'Null' => $col['notnull'] ? 'NO' : 'YES',
                'Key' => $col['pk'] ? 'PRI' : '',
                'Default' => $col['dflt_value'],
                'Extra' => ''
            ];
        }
        $tableColumns = array_column($tableStructure, 'Field');

        if ($view === 'data') {
            $sql = "SELECT * FROM `$currentTable`";
            $params = [];
            
            if ($searchVal !== '') {
                $op = '=';
                $val = $searchVal;
                
                if ($searchOp === 'LIKE') {
                    $op = 'LIKE';
                    $val = "%$searchVal%";
                } elseif (in_array($searchOp, ['=', '!=', '>', '<', '>=', '<='])) {
                    $op = $searchOp;
                }
                
                if ($searchColumn && in_array($searchColumn, $tableColumns)) {
                    $sql .= " WHERE `$searchColumn` $op ?";
                    $params[] = $val;
                } else {
                    $where = [];
                    foreach ($tableColumns as $col) {
                        $where[] = "`$col` LIKE ?";
                        $params[] = "%$searchVal%";
                    }
                    if ($where) $sql .= " WHERE (" . implode(" OR ", $where) . ")";
                }
            }
            
            // Advanced Filters
            $advancedFiltersJson = $_GET['advanced_filters'] ?? '[]';
            $advancedFilters = json_decode($advancedFiltersJson, true) ?: [];
            if (is_array($advancedFilters) && count($advancedFilters) > 0) {
                $afWhere = [];
                foreach ($advancedFilters as $af) {
                    if (!empty($af['col']) && in_array($af['col'], $tableColumns) && !empty($af['op']) && isset($af['val'])) {
                        $aop = in_array($af['op'], ['=', '!=', '>', '<', '>=', '<=', 'LIKE']) ? $af['op'] : '=';
                        $aval = $aop === 'LIKE' ? "%{$af['val']}%" : $af['val'];
                        $afWhere[] = "`{$af['col']}` $aop ?";
                        $params[] = $aval;
                    }
                }
                if (!empty($afWhere)) {
                    if (strpos($sql, 'WHERE') !== false) {
                        $sql .= " AND " . implode(" AND ", $afWhere);
                    } else {
                        $sql .= " WHERE " . implode(" AND ", $afWhere);
                    }
                }
            }
            
            if ($orderBy && in_array($orderBy, $tableColumns)) {
                $sql .= " ORDER BY `$orderBy` " . ($orderDir === 'DESC' ? 'DESC' : 'ASC');
            }
            
            // Calculate Total Count
            $countSql = "SELECT COUNT(*) FROM ($sql) as sub";
            $countStmt = $pdo->prepare($countSql);
            $countStmt->execute($params);
            $totalDataCount = $countStmt->fetchColumn();
            
            $sql .= " LIMIT $limit OFFSET $offset";
            
            $stmt = $pdo->prepare($sql);
            $stmt->execute($params);
            $tableData = $stmt->fetchAll();
        }
    } elseif (($_SESSION['db_mode'] ?? 'sql') === 'sql' && isset($pdo)) {
        // SQL Mode (MySQL/MariaDB)
        $stmt = $pdo->query("DESCRIBE `$currentTable`");
        $tableStructure = $stmt->fetchAll();
        $tableColumns = array_column($tableStructure, 'Field');

        if ($view === 'data') {
            $sql = "SELECT * FROM `$currentTable`";
            $params = [];
            
            if ($searchVal !== '') {
                $op = '=';
                $val = $searchVal;
                
                if ($searchOp === 'LIKE') {
                    $op = 'LIKE';
                    $val = "%$searchVal%";
                } elseif (in_array($searchOp, ['=', '!=', '>', '<', '>=', '<='])) {
                    $op = $searchOp;
                }
                
                if ($searchColumn && in_array($searchColumn, $tableColumns)) {
                    $sql .= " WHERE `$searchColumn` $op ?";
                    $params[] = $val;
                } else {
                    // Global search
                    $where = [];
                    foreach ($tableColumns as $col) {
                        $where[] = "`$col` LIKE ?";
                        $params[] = "%$searchVal%";
                    }
                    if ($where) $sql .= " WHERE (" . implode(" OR ", $where) . ")";
                }
            }
            
            // Advanced Filters
            $advancedFiltersJson = $_GET['advanced_filters'] ?? '[]';
            $advancedFilters = json_decode($advancedFiltersJson, true) ?: [];
            if (is_array($advancedFilters) && count($advancedFilters) > 0) {
                $afWhere = [];
                foreach ($advancedFilters as $af) {
                    if (!empty($af['col']) && in_array($af['col'], $tableColumns) && !empty($af['op']) && isset($af['val'])) {
                        $aop = in_array($af['op'], ['=', '!=', '>', '<', '>=', '<=', 'LIKE']) ? $af['op'] : '=';
                        $aval = $aop === 'LIKE' ? "%{$af['val']}%" : $af['val'];
                        $afWhere[] = "`{$af['col']}` $aop ?";
                        $params[] = $aval;
                    }
                }
                if (!empty($afWhere)) {
                    if (strpos($sql, 'WHERE') !== false) {
                        $sql .= " AND " . implode(" AND ", $afWhere);
                    } else {
                        $sql .= " WHERE " . implode(" AND ", $afWhere);
                    }
                }
            }
            
            if ($orderBy && in_array($orderBy, $tableColumns)) {
                $orderDir = strtoupper($orderDir) === 'DESC' ? 'DESC' : 'ASC';
                $sql .= " ORDER BY `$orderBy` $orderDir";
            }
            
            // Calculate Total Count
            $countSql = "SELECT COUNT(*) FROM (" . str_replace("SELECT *", "SELECT 1", $sql) . ") as sub";
            if (strpos($sql, 'WHERE') === false) {
                 $countSql = "SELECT COUNT(*) FROM `$currentTable`";
                 if (!empty($params)) { // If we had global search but it didn't find WHERE (unlikely but safe)
                      $countSql = "SELECT COUNT(*) FROM ($sql) as sub";
                 }
            } else {
                 $countSql = "SELECT COUNT(*) FROM ($sql) as sub";
            }
            
            $countStmt = $pdo->prepare($countSql);
            $countStmt->execute($params);
            $totalDataCount = (int)$countStmt->fetchColumn();
            
            $sql .= " LIMIT $limit OFFSET $offset";
            $stmt = $pdo->prepare($sql);
            $stmt->execute($params);
            $tableData = $stmt->fetchAll();
        }
    }
}

if (!empty($tableStructure)) {
    foreach ($tableStructure as $cs) {
        $colTypesMap[$cs['Field']] = strtolower($cs['Type']);
    }
}

// --- Foreign Key Auto-Lookup Pre-fetch ---
$fkMap = [];
if (($_SESSION['db_mode'] ?? 'sql') === 'sql' && $currentTable && !empty($tableData)) {
    try {
        $stmt = $pdo->prepare("SELECT COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME 
                               FROM information_schema.KEY_COLUMN_USAGE 
                               WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND REFERENCED_TABLE_NAME IS NOT NULL");
        $stmt->execute([$currentTable]);
        while ($fk = $stmt->fetch(PDO::FETCH_ASSOC)) {
            $colName = $fk['COLUMN_NAME'];
            $refTable = $fk['REFERENCED_TABLE_NAME'];
            $refCol = $fk['REFERENCED_COLUMN_NAME'];
            
            $refVals = array_unique(array_filter(array_column($tableData, $colName)));
            if (!empty($refVals)) {
                $colStmt = $pdo->query("SHOW COLUMNS FROM `$refTable`");
                $refCols = $colStmt->fetchAll(PDO::FETCH_ASSOC);
                $labelCol = $refCol;
                foreach ($refCols as $rc) {
                    $cType = strtolower($rc['Type']);
                    $cName = strtolower($rc['Field']);
                    if (strpos($cType, 'varchar') !== false || strpos($cType, 'text') !== false || $cName === 'name' || $cName === 'title' || $cName === 'username') {
                        $labelCol = $rc['Field'];
                        if ($cName === 'name' || $cName === 'title') break;
                    }
                }
                
                $inStr = implode(',', array_map([$pdo, 'quote'], $refVals));
                $fkStmt = $pdo->query("SELECT `$refCol`, `$labelCol` FROM `$refTable` WHERE `$refCol` IN ($inStr)");
                $lookup = [];
                while ($r = $fkStmt->fetch(PDO::FETCH_ASSOC)) {
                    $lookup[$r[$refCol]] = $r[$labelCol];
                }
                $fkMap[$colName] = [
                    'table' => $refTable,
                    'col' => $refCol,
                    'labelCol' => $labelCol,
                    'data' => $lookup
                ];
            }
        }
    } catch (Exception $e) {}
}

// Handle AJAX FK Preview Request
if ($action === 'fetch_fk_preview') {
    while (ob_get_level()) ob_end_clean();
    header('Content-Type: application/json');
    
    $refTable = $_GET['ref_table'] ?? '';
    $refCol = $_GET['ref_col'] ?? '';
    $refVal = $_GET['ref_val'] ?? '';
    
    if (!$refTable || !$refCol || !$refVal) {
        echo json_encode(['success' => false, 'error' => 'Missing parameters']);
        exit;
    }
    
    try {
        if (($_SESSION['db_mode'] ?? 'sql') === 'sql' && isset($pdo)) {
            // Get all columns from referenced table
            $colStmt = $pdo->query("SHOW COLUMNS FROM `$refTable`");
            $columns = $colStmt->fetchAll(PDO::FETCH_ASSOC);
            
            // Fetch the record
            $stmt = $pdo->prepare("SELECT * FROM `$refTable` WHERE `$refCol` = ? LIMIT 1");
            $stmt->execute([$refVal]);
            $record = $stmt->fetch(PDO::FETCH_ASSOC);
            
            if ($record) {
                // Format data for display
                $formattedData = [];
                foreach ($record as $col => $val) {
                    $formattedData[] = [
                        'column' => $col,
                        'value' => $val,
                        'type' => array_reduce($columns, function($carry, $c) use ($col) {
                            return $c['Field'] === $col ? $c['Type'] : $carry;
                        }, 'unknown')
                    ];
                }
                
                echo json_encode([
                    'success' => true,
                    'data' => $formattedData,
                    'table' => $refTable,
                    'primaryKey' => $refCol,
                    'primaryValue' => $refVal
                ]);
            } else {
                echo json_encode(['success' => false, 'error' => 'Record not found']);
            }
        } else {
            echo json_encode(['success' => false, 'error' => 'Not supported in current mode']);
        }
    } catch (Exception $e) {
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
    exit;
}

// Handle AJAX FK Inline Edit Request
if ($action === 'update_fk_field') {
    while (ob_get_level()) ob_end_clean();
    header('Content-Type: application/json');
    
    $refTable = $_POST['ref_table'] ?? '';
    $refCol = $_POST['ref_col'] ?? '';
    $refVal = $_POST['ref_val'] ?? '';
    $fieldName = $_POST['field_name'] ?? '';
    $fieldValue = $_POST['field_value'] ?? '';
    
    if (!$refTable || !$refCol || !$refVal || !$fieldName) {
        echo json_encode(['success' => false, 'error' => 'Missing parameters']);
        exit;
    }
    
    // Check write permission
    if (!has_permission('adminer', 'write')) {
        echo json_encode(['success' => false, 'error' => 'No write permission']);
        exit;
    }
    
    try {
        if (($_SESSION['db_mode'] ?? 'sql') === 'sql' && isset($pdo)) {
            // Update the field
            $stmt = $pdo->prepare("UPDATE `$refTable` SET `$fieldName` = ? WHERE `$refCol` = ?");
            $result = $stmt->execute([$fieldValue, $refVal]);
            
            if ($result) {
                echo json_encode([
                    'success' => true,
                    'message' => 'Field updated successfully',
                    'newValue' => $fieldValue
                ]);
            } else {
                echo json_encode(['success' => false, 'error' => 'Update failed']);
            }
        } else {
            echo json_encode(['success' => false, 'error' => 'Not supported in current mode']);
        }
    } catch (Exception $e) {
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
    exit;
}

// Handle AJAX Data Fetching (Load More)
if ($action === 'fetch_data') {
    while (ob_get_level()) ob_end_clean();
    header('Content-Type: application/json');
    
    $html = '';
    foreach ($tableData as $row) {
        $html .= render_data_row($row, $currentTable, $primaryKey, $colTypesMap ?? [], $fkMap, $pdo ?? null, $tables ?? [], $dualConditionCols ?? []);
    }

    echo json_encode([
        'success' => true,
        'html' => $html,
        'count' => count($tableData),
        'has_more' => ($offset + count($tableData) < ($totalDataCount ?? 0))
    ]);
    exit;
}

// Data for Dashboard Charts
$chartLabels = [];
$chartData = [];
if (!empty($tables)) {
    // Sort tables by size/rows descending but limit to 10 for readability
    $sortedTables = $tables;
    usort($sortedTables, function($a, $b) {
        return ($b['Rows'] ?? 0) <=> ($a['Rows'] ?? 0);
    });
    $topTables = array_slice($sortedTables, 0, 10);
    foreach ($topTables as $t) {
        $chartLabels[] = $t['Name'] ?? ($t['TABLE_NAME'] ?? 'Unknown');
        $chartData[] = (int)($t['Rows'] ?? 0);
    }
}
