            border-radius: 4px;
            padding: 2px 8px;
            outline: none;
            box-shadow: 0 0 0 2px rgba(0, 123, 255, 0.25);
        }
        .toggle-container {
            padding: 2px 4px;
            border-radius: 4px;
            transition: background 0.2s;
        }
        .toggle-container:hover {
            background: rgba(255,255,255,0.05);
        }
        .toggle-label {
            min-width: 40px;
            pointer-events: none;
            user-select: none;
        }
    </style>
    <script>
        function toggleBoolean(checkbox) {
            const td = checkbox.closest('td');
            const table = td.getAttribute('data-table') || new URLSearchParams(window.location.search).get('table');
            const column = td.getAttribute('data-col');
            const pk = td.getAttribute('data-pk');
            
            const onVal = checkbox.getAttribute('data-on');
            const offVal = checkbox.getAttribute('data-off');
            const value = checkbox.checked ? onVal : offVal;

            const formData = new FormData();
            formData.append('action', 'update_cell');
            formData.append('table', table);
            formData.append('column', column);
            formData.append('id', pk);
            formData.append('value', value);

            fetch('?', { method: 'POST', body: formData })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    const toast = Swal.mixin({toast: true, position: 'top-end', showConfirmButton: false, timer: 1000});
                    toast.fire({ icon: 'success', title: 'Updated to ' + value });
                    // Update label if exists
                    const label = checkbox.closest('.toggle-container')?.querySelector('.toggle-label');
                    if (label) label.innerText = value;
                } else {
                    checkbox.checked = !checkbox.checked;
                    Swal.fire('Error', data.message || 'Failed to update', 'error');
                }
            })
            .catch(err => {
                checkbox.checked = !checkbox.checked;
                Swal.fire('Error', 'Network error', 'error');
            });
        }

        function updateColorValue(input, table, col, pk) {
            const newVal = input.value;
            const wrapper = input.closest('.color-preview-wrapper');
            const preview = wrapper.querySelector('.color-preview-box');
            const text = wrapper.querySelector('span');

            const formData = new FormData();
            formData.append('action', 'update_cell');
            formData.append('table', table);
            formData.append('column', col);
            formData.append('id', pk);
            formData.append('value', newVal);

            fetch('?', { method: 'POST', body: formData })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    preview.style.background = newVal;
                    if (text) text.innerText = newVal;
                    const toast = Swal.mixin({toast: true, position: 'top-end', showConfirmButton: false, timer: 1000});
                    toast.fire({ icon: 'success', title: 'Color updated to ' + newVal });
                } else {
                    Swal.fire('Error', data.message || 'Update failed', 'error');
                }
            });
        }

        function copyCellContent(btn, event) {
            event.stopPropagation();
            const td = btn.closest('td');
            // Try to find the raw value. If it's a special field, we might need a specific way to get it.
            // But usually the innerText of the td minus the button is good enough.
            
            // Temporary clone to get text without the button
            const clone = td.cloneNode(true);
            const btnInClone = clone.querySelector('.quick-copy-btn');
            if (btnInClone) btnInClone.remove();
            
            // If it's a toggle or color picker, it might have extra text.
            // Let's try to get data-value if available (we can add it)
            const rawValue = td.querySelector('.cell-value-wrapper').innerText.trim();

            navigator.clipboard.writeText(rawValue).then(() => {
                const icon = btn.querySelector('i');
                icon.className = 'fas fa-check';
                icon.style.color = '#10b981';
                
                const toast = Swal.mixin({toast: true, position: 'top-end', showConfirmButton: false, timer: 1000});
                toast.fire({ icon: 'success', title: 'Copied to clipboard' });

                setTimeout(() => {
                    icon.className = 'far fa-copy';
                    icon.style.color = '';
                }, 1500);
            });
        }

        // --- KEYBOARD NAVIGATION & HIGHLIGHTING ---
        let currentRowIndex = -1;

        document.addEventListener('DOMContentLoaded', () => {
            applySearchHighlighting();
            initKeyboardNavigation();
        });

        function applySearchHighlighting() {
            const params = new URLSearchParams(window.location.search);
            const term = params.get('search_val');
            if (!term || term.length < 2) return;

            const regex = new RegExp(`(${term.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')})`, 'gi');
            document.querySelectorAll('.adminer-data-cell .cell-value-wrapper').forEach(cell => {
                if (cell.querySelector('.toggle-container, .color-preview-wrapper, .row-media-preview, video')) return;
                highlightTextNodes(cell, regex);
            });
        }

        function highlightTextNodes(node, regex) {
            if (node.nodeType === 3) {
                const matches = node.data.match(regex);
                if (matches) {
                    const span = document.createElement('span');
                    span.innerHTML = node.data.replace(regex, '<mark class="search-highlight">$1</mark>');
                    node.parentNode.replaceChild(span, node);
                }
            } else if (node.nodeType === 1 && node.childNodes && !/(script|style|button|i)/i.test(node.tagName)) {
                Array.from(node.childNodes).forEach(child => highlightTextNodes(child, regex));
            }
        }

        function initKeyboardNavigation() {
            document.addEventListener('keydown', (e) => {
                if (document.body.classList.contains('swal2-shown')) return;
                
                if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName) || document.activeElement.isContentEditable) {
                    if (e.key === 'Escape') document.activeElement.blur();
                    return;
                }

                const rows = document.querySelectorAll('#adminer-table-data tbody tr');
                if (rows.length === 0) return;

                switch (e.key.toLowerCase()) {
                    case '/':
                        e.preventDefault();
                        const sInput = document.querySelector('input[name="search_val"]');
                        if (sInput) { sInput.focus(); sInput.select(); }
                        break;
                    case 'n':
                        const table = new URLSearchParams(window.location.search).get('table');
                        if (table) window.location.href = `?table=${table}&view=form`;
                        break;
                    case 'j':
                        if (currentRowIndex < rows.length - 1) {
                            currentRowIndex++;
                            updateActiveRow(rows);
                        }
                        break;
                    case 'k':
                        if (currentRowIndex > 0) {
                            currentRowIndex--;
                            updateActiveRow(rows);
                        }
                        break;
                    case 'e':
                        if (currentRowIndex >= 0) {
                            const editLink = rows[currentRowIndex].querySelector('a[title="Edit Row"]');
                            if (editLink) editLink.click();
                        }
                        break;
                }
            });
        }

        function updateActiveRow(rows) {
            rows.forEach(r => r.classList.remove('active-row-nav'));
            const row = rows[currentRowIndex];
            if (row) {
                row.classList.add('active-row-nav');
                row.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
            }
        }

        function showExportRowOptions(table, pk, val, event) {
            event.stopPropagation();
            Swal.fire({
                title: 'Smart Export Row',
                text: 'Select format to export this single row:',
                icon: 'info',
                showCancelButton: true,
                confirmButtonText: '<i class="fas fa-code"></i> JSON',
                cancelButtonText: '<i class="fas fa-file-csv"></i> CSV',
                showDenyButton: true,
                denyButtonText: '<i class="fas fa-database"></i> SQL INSERT',
                background: 'var(--bg-card)',
                color: 'var(--text-primary)',
                customClass: {
                    confirmButton: 'btn btn-primary',
                    cancelButton: 'btn btn-secondary',
                    denyButton: 'btn btn-warning'
                }
            }).then((result) => {
                let format = '';
                if (result.isConfirmed) format = 'json';
                else if (result.isDenied) format = 'sql';
                else if (result.dismiss === Swal.DismissReason.cancel) format = 'csv';
                else return;

                const formData = new FormData();
                formData.append('action', 'export_single_row');
                formData.append('table', table);
                formData.append('pk', pk);
                formData.append('val', val);
                formData.append('format', format);

                fetch('?', { method: 'POST', body: formData })
                .then(res => res.json())
                .then(data => {
                    if (data.success) {
                        navigator.clipboard.writeText(data.content).then(() => {
                            Swal.fire({
                                icon: 'success',
                                title: 'Exported!',
                                text: `Row data copied to clipboard as ${format.toUpperCase()}`,
                                timer: 2000,
                                showConfirmButton: false
                            });
                        });
                    } else {
                        Swal.fire('Error', data.message || 'Export failed', 'error');
                    }
                });
            });
        }
        function switchSqlTab(tabId) {
            console.log('Switching SQL Tab:', tabId);
            const target = document.getElementById(tabId);
            if (!target) {
                console.error('Tab target NOT found:', tabId);
                return;
            }

            // Remove v2-active from all
            document.querySelectorAll('.sql-v2-tab-content').forEach(el => el.classList.remove('v2-active'));
            document.querySelectorAll('.sql-v2-tab-btn').forEach(el => el.classList.remove('v2-active'));

            // Add v2-active to target
            target.classList.add('v2-active');
            
            // Find the button and activate it
            const btn = document.querySelector(`.sql-v2-tab-btn[onclick*="${tabId}"]`);
            if (btn) btn.classList.add('v2-active');
            
            // Log success
            console.log('Tab activated:', tabId);
        }

        // --- GLOBAL UTILITY FUNCTIONS (Moved to Head) ---
        function switchDbMode(mode) {
            window.location.href = '?db_mode=' + mode;
        }

        function saConfirmForm(e, text) {
            e.preventDefault();
            const form = e.target;
            Swal.fire({
                title: 'Are you sure?',
                text: text || "You won't be able to revert this!",
                icon: 'warning',
                showCancelButton: true,
                confirmButtonColor: '#3085d6',
                cancelButtonColor: '#d33',
                confirmButtonText: 'Yes, proceed!'
            }).then((result) => {
                if (result.isConfirmed) {
                    form.submit();
                }
            });
        }

        function createNewJsonFile() {
            Swal.fire({
                title: 'Create New JSON File',
                html: `
                    <input type="text" id="jsonFileName" class="swal2-input" placeholder="Enter filename (e.g., mydata.json)" style="width: 80%;">
                    <small style="display: block; margin-top: 10px; color: var(--text-secondary);">
                        File akan dibuat di folder json_db/
                    </small>
                `,
                showCancelButton: true,
                confirmButtonText: 'Create',
                cancelButtonText: 'Cancel',
                preConfirm: () => {
                    const fileName = document.getElementById('jsonFileName').value;
                    if (!fileName) {
                        Swal.showValidationMessage('Please enter a filename');
                        return false;
                    }
                    if (!fileName.endsWith('.json')) {
                        Swal.showValidationMessage('Filename must end with .json');
                        return false;
                    }
                    return fileName;
                }
            }).then((result) => {
                if (result.isConfirmed) {
                    const formData = new FormData();
                    formData.append('action', 'create_json_file');
                    formData.append('filename', result.value);
                    
                    fetch('?', {
                        method: 'POST',
                        body: formData
                    })
                    .then(res => res.json())
                    .then(data => {
                        if (data.success) {
                            Swal.fire({
                                icon: 'success',
                                title: 'Success',
                                text: 'JSON file created!',
                                timer: 1500
                            }).then(() => {
                                window.location.href = '?select_json_file=' + encodeURIComponent(result.value);
                            });
                        } else {
                            Swal.fire('Error', data.message || 'Failed to create file', 'error');
                        }
                    })
                    .catch(err => {
                        Swal.fire('Error', 'Network error', 'error');
                    });
                }
            });
        }

        function createNewSqliteFile() {
            Swal.fire({
                title: 'Create New SQLite Database',
                html: `
                    <input type="text" id="sqliteFileName" class="swal2-input" placeholder="Enter filename (e.g., mydata.db)" style="width: 80%;">
                    <small style="display: block; margin-top: 10px; color: var(--text-secondary);">
                        File akan dibuat di folder sqlite_db/
                    </small>
                `,
                showCancelButton: true,
                confirmButtonText: 'Create',
                cancelButtonText: 'Cancel',
                preConfirm: () => {
                    const fileName = document.getElementById('sqliteFileName').value;
                    if (!fileName) {
                        Swal.showValidationMessage('Please enter a filename');
                        return false;
                    }
                    if (!fileName.endsWith('.db') && !fileName.endsWith('.sqlite')) {
                        Swal.showValidationMessage('Filename must end with .db or .sqlite');
                        return false;
                    }
                    return fileName;
                }
            }).then((result) => {
                if (result.isConfirmed) {
                    const formData = new FormData();
                    formData.append('action', 'create_sqlite_file');
                    formData.append('filename', result.value);
                    
                    fetch('?', {
                        method: 'POST',
                        body: formData
                    })
                    .then(res => res.json())
                    .then(data => {
                        if (data.success) {
                            Swal.fire({
                                icon: 'success',
                                title: 'Success',
                                text: 'SQLite database created!',
                                timer: 1500
                            }).then(() => {
                                window.location.href = '?select_sqlite_file=' + encodeURIComponent(result.value);
                            });
                        } else {
                            Swal.fire('Error', data.message || 'Failed to create database', 'error');
                        }
                    })
                    .catch(err => {
                        Swal.fire('Error', 'Network error', 'error');
                    });
                }
            });
        }

        function browseSqliteFile() {
            Swal.fire({
                title: 'Browse SQLite Database',
                html: `
                    <div style="text-align: left;">
                        <div style="margin-bottom: 10px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: bold;">Current Path:</label>
                            <div style="display: flex; gap: 5px;">
                                <input type="text" id="browsePath" class="swal2-input" value="" placeholder="/" style="flex: 1; margin: 0;">
                                <button onclick="loadBrowsePathSqlite()" class="swal2-confirm swal2-styled" style="margin: 0; padding: 8px 15px;">Go</button>
                            </div>
                        </div>
                        <div id="browseContent" style="max-height: 400px; overflow-y: auto; border: 1px solid #444; border-radius: 4px; padding: 10px; background: rgba(0,0,0,0.2);">
                            <div style="text-align: center; padding: 20px; color: #888;">
                                <i class="fas fa-spinner fa-spin"></i> Loading...
                            </div>
                        </div>
                    </div>
                `,
                width: '600px',
                showCancelButton: true,
                showConfirmButton: false,
                cancelButtonText: 'Close',
                didOpen: () => {
                    loadBrowsePathSqlite('');
                }
            });
        }

        function loadBrowsePathSqlite(path) {
            if (path === undefined) {
                path = document.getElementById('browsePath').value;
            } else {
                document.getElementById('browsePath').value = path;
            }
            
            const formData = new FormData();
            formData.append('action', 'browse_sqlite_files');
            formData.append('path', path);
            
            fetch('?', {
                method: 'POST',
                body: formData
            })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    renderBrowseContentSqlite(data.items, data.current_path);
                } else {
                    document.getElementById('browseContent').innerHTML = `
                        <div style="text-align: center; padding: 20px; color: #ff6b6b;">
                            <i class="fas fa-exclamation-triangle"></i> ${data.message || 'Error loading path'}
                        </div>
                    `;
                }
            })
            .catch(err => {
                document.getElementById('browseContent').innerHTML = `
                    <div style="text-align: center; padding: 20px; color: #ff6b6b;">
                        <i class="fas fa-exclamation-triangle"></i> Network error
                    </div>
                `;
            });
        }

        function renderBrowseContentSqlite(items, currentPath) {
            let html = '';
            
            if (currentPath !== '') {
                const parentPath = currentPath.split('/').slice(0, -1).join('/');
                html += `
                    <div style="padding: 8px; margin-bottom: 5px; background: rgba(255,255,255,0.05); border-radius: 4px; cursor: pointer;" onclick="loadBrowsePathSqlite('${parentPath}')">
                        <i class="fas fa-level-up-alt" style="color: #888;"></i> <span style="color: #888;">..</span>
                    </div>
                `;
            }
            
            items.folders.forEach(folder => {
                const fullPath = currentPath ? currentPath + '/' + folder : folder;
                html += `
                    <div style="padding: 8px; margin-bottom: 5px; background: rgba(255,255,255,0.05); border-radius: 4px; cursor: pointer;" onclick="loadBrowsePathSqlite('${fullPath}')">
                        <i class="fas fa-folder" style="color: #ffd700;"></i> ${folder}
                    </div>
                `;
            });
            
            items.files.forEach(file => {
                const fullPath = currentPath ? currentPath + '/' + file : file;
                html += `
                    <div style="padding: 8px; margin-bottom: 5px; background: rgba(255,255,255,0.05); border-radius: 4px; cursor: pointer; display: flex; justify-content: space-between; align-items: center;" onmouseover="this.style.background='rgba(255,255,255,0.1)'" onmouseout="this.style.background='rgba(255,255,255,0.05)'">
                        <div>
                            <i class="fas fa-database" style="color: #2196F3;"></i> ${file}
                        </div>
                        <button onclick="selectSqliteFile('${fullPath}'); event.stopPropagation();" class="swal2-confirm swal2-styled" style="margin: 0; padding: 4px 12px; font-size: 0.85rem;">
                            Select
                        </button>
                    </div>
                `;
            });
            
            if (items.folders.length === 0 && items.files.length === 0) {
                html = `
                    <div style="text-align: center; padding: 20px; color: #888;">
                        <i class="fas fa-folder-open"></i> Empty folder
                    </div>
                `;
            }
            
            document.getElementById('browseContent').innerHTML = html;
        }

        function selectSqliteFile(filePath) {
            Swal.fire({
                title: 'Use this database?',
                text: filePath,
                icon: 'question',
                showCancelButton: true,
                confirmButtonText: 'Yes, use it!',
                cancelButtonText: 'Cancel'
            }).then((result) => {
                if (result.isConfirmed) {
                    window.location.href = '?select_sqlite_file=' + encodeURIComponent(filePath) + '&external=1';
                }
            });
        }

        function browseJsonFile() {
            Swal.fire({
                title: 'Browse JSON File',
                html: `
                    <div style="text-align: left;">
                        <div style="margin-bottom: 10px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: bold;">Current Path:</label>
                            <div style="display: flex; gap: 5px;">
                                <input type="text" id="browsePath" class="swal2-input" value="" placeholder="/" style="flex: 1; margin: 0;">
                                <button onclick="loadBrowsePath()" class="swal2-confirm swal2-styled" style="margin: 0; padding: 8px 15px;">Go</button>
                            </div>
                        </div>
                        <div id="browseContent" style="max-height: 400px; overflow-y: auto; border: 1px solid #444; border-radius: 4px; padding: 10px; background: rgba(0,0,0,0.2);">
                            <div style="text-align: center; padding: 20px; color: #888;">
                                <i class="fas fa-spinner fa-spin"></i> Loading...
                            </div>
                        </div>
                    </div>
                `,
                width: '600px',
                showCancelButton: true,
                showConfirmButton: false,
                cancelButtonText: 'Close',
                didOpen: () => {
                    loadBrowsePath('');
                }
            });
        }

        function loadBrowsePath(path) {
            if (path === undefined) {
                path = document.getElementById('browsePath').value;
            } else {
                document.getElementById('browsePath').value = path;
            }
            
            const formData = new FormData();
            formData.append('action', 'browse_files');
            formData.append('path', path);
            
            fetch('?', {
