            })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    renderBrowseContent(data.items, data.current_path);
                } else {
                    document.getElementById('browseContent').innerHTML = `
                        <div style="text-align: center; padding: 20px; color: #ff6b6b;">
