    // --- Custom Export Logic ---
    function handleExport(event) {
        event.preventDefault();
        const form = event.target;
        const formatSelect = form.querySelector('select[name="format"]');
        let format = formatSelect ? formatSelect.value : 'sql';
        const tableInput = form.querySelector('input[name="table"]');
        let table = tableInput ? tableInput.value : '';
        
        let colsHtml = '';
        if (table && window._currentTableStructure) {
            colsHtml = `<p style="margin-top:10px; margin-bottom:5px;">Select columns to export:</p>
            <div style="max-height:150px; overflow-y:auto; border:1px solid #333; padding:10px; border-radius:4px; text-align:left; background:#111;">
            <label style="display:block; margin-bottom:5px;"><input type="checkbox" id="exp_check_all" checked onchange="document.querySelectorAll('.exp-col-cb').forEach(cb=>cb.checked=this.checked)"> <strong>Select All</strong></label>
            <hr style="border-color:#333; margin:5px 0;">`;
            window._currentTableStructure.forEach(col => {
                colsHtml += `<label style="display:block;"><input type="checkbox" class="exp-col-cb" value="${col.name}" checked> ${col.name}</label>`;
            });
            colsHtml += `</div>`;
        }

        Swal.fire({
            title: 'Export Options',
            html: `
                <div style="text-align:left;">
                    <label>Format:</label>
                    <select id="swal_exp_format" class="form-select" style="margin-bottom:10px;" onchange="document.getElementById('sql_mode_container').style.display = this.value === 'sql' ? 'block' : 'none'">
                        <option value="sql" ${format==='sql'?'selected':''}>SQL</option>
                        <option value="json" ${format==='json'?'selected':''}>JSON</option>
                        <option value="csv" ${format==='csv'?'selected':''}>CSV</option>
                        <option value="xlsx" ${format==='xlsx'?'selected':''}>XLSX</option>
                    </select>
                    
                    <div id="sql_mode_container" style="display:${format==='sql'?'block':'none'}">
                        <label>SQL Mode:</label>
                        <select id="swal_sql_mode" class="form-select" style="margin-bottom:10px;" onchange="
                            const isUpdate = this.value === 'update';
                            const wcc = document.getElementById('where_col_container');
                            if(wcc) {
                                wcc.style.display = isUpdate ? 'block' : 'none';
                                if(isUpdate) {
                                    document.getElementById('swal_where_col').dispatchEvent(new Event('change'));
                                } else {
                                    document.querySelectorAll('.exp-col-cb').forEach(cb => { cb.disabled = false; });
                                }
                            }
                        ">
                            <option value="insert">INSERT (Default)</option>
                            <option value="update">UPDATE</option>
                            <option value="upsert">UPSERT (On Duplicate Key Update)</option>
                        </select>
                    </div>
                    
                    ${window._currentTableStructure ? `
                    <div id="where_col_container" style="display:none;">
                        <label>Where Column (for UPDATE mode):</label>
                        <select id="swal_where_col" class="form-select" style="margin-bottom:10px;" onchange="
                            document.querySelectorAll('.exp-col-cb').forEach(cb => { cb.disabled = false; });
                            const cb = Array.from(document.querySelectorAll('.exp-col-cb')).find(el => el.value === this.value);
                            if(cb) { cb.checked = false; cb.disabled = true; }
                        ">
                            ${window._currentTableStructure.map(c => `<option value="${c.name}">${c.name}</option>`).join('')}
                        </select>
                    </div>
                    ` : ''}
                    
                    <label>Action:</label>
                    <select id="swal_exp_action" class="form-select" style="margin-bottom:10px;">
                        <option value="download">Download File</option>
                        <option value="copy">Copy to Clipboard</option>
                    </select>

                    <div>
                        <label>Custom WHERE (Optional):</label>
                        <input type="text" id="swal_exp_where" class="form-control" placeholder="e.g. status='active'" style="margin-bottom:10px; font-family:monospace; font-size:12px;">
                    </div>
                    
                    ${colsHtml}
                </div>
            `,
            showCancelButton: true,
            confirmButtonText: 'Execute',
        }).then(async res => {
            if (res.isConfirmed) {
                const selFormat = document.getElementById('swal_exp_format').value;
                const selAction = document.getElementById('swal_exp_action').value;
                const selSqlMode = document.getElementById('swal_sql_mode').value;
                const expWhere = document.getElementById('swal_exp_where').value;
                const checkedCols = Array.from(document.querySelectorAll('.exp-col-cb:checked')).map(cb => cb.value);
                
                const fd = new FormData(form);
                fd.set('format', selFormat);
                if (expWhere.trim() !== '') {
                    fd.set('export_where', expWhere.trim());
                }
                if (selFormat === 'sql') {
                    fd.set('sql_mode', selSqlMode);
                    if (selSqlMode === 'update' && document.getElementById('swal_where_col')) {
                        fd.set('where_column', document.getElementById('swal_where_col').value);
                    }
                }
                if (checkedCols.length > 0) {
                    fd.set('columns', JSON.stringify(checkedCols));
                }
                
                if (selFormat === 'xlsx' && selAction === 'download') {
                    if (typeof exportTableAsXLSX === 'function') {
                        exportTableAsXLSX(table, checkedCols);
                    } else if (typeof window.exportTableAsXLSX === 'function') {
                        window.exportTableAsXLSX(table, checkedCols);
                    }
                    return;
                }
                
                if (selAction === 'copy') {
                    fd.set('copy_mode', '1');
                    Swal.fire({title:'Processing...', allowOutsideClick:false, didOpen:()=>{Swal.showLoading()}});
                    try {
                        const r = await fetch(location.href, {method:'POST', body:fd});
                        const txt = await r.text();
                        await navigator.clipboard.writeText(txt);
                        Swal.fire('Success', 'Export content copied to clipboard!', 'success');
                    } catch (err) {
                        Swal.fire('Error', 'Failed to copy: ' + err.message, 'error');
                    }
                } else {
                    const dlForm = document.createElement('form');
                    dlForm.method = 'POST';
                    dlForm.action = location.href;
                    for (let [key, val] of fd.entries()) {
                        const i = document.createElement('input');
                        i.type = 'hidden';
                        i.name = key;
                        i.value = val;
                        dlForm.appendChild(i);
                    }
                    document.body.appendChild(dlForm);
                    dlForm.submit();
                    document.body.removeChild(dlForm);
                }
            }
        });
        
        return false;
    }

    window.exportTableAsXLSX = async function(table = '', checkedCols = []) {
        const currentTable = table || "<?= htmlspecialchars($currentTable ?? '') ?>";
        const filename = `${currentTable}_${new Date().toISOString().slice(0,10)}.xlsx`;

        try {
            // Fetch full data as JSON using the existing export action
            const formData = new FormData();
            formData.append('action', 'export');
            formData.append('table', currentTable);
            formData.append('format', 'json'); // Request JSON data from the server
            if (checkedCols && checkedCols.length > 0) {
                formData.append('columns', JSON.stringify(checkedCols));
            }

            const response = await fetch('?', {
                method: 'POST',
                body: formData
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const fetchedData = await response.json(); // Parse the JSON response
            if (fetchedData.length === 0) {
                Swal.fire('Info', 'No data to export for this table.', 'info');
                return;
            }
            
            // Create a new workbook
            const wb = XLSX.utils.book_new();
            const ws = XLSX.utils.json_to_sheet(fetchedData); // json to sheet

            // Add the worksheet to the workbook
            XLSX.utils.book_append_sheet(wb, ws, currentTable);
            // Write the workbook to an XLSX file and trigger download
            XLSX.writeFile(wb, filename);

            const toast = Swal.mixin({toast: true, position: 'top-end', showConfirmButton: false, timer: 1500});
            toast.fire({ icon: 'success', title: 'Exported to XLSX!' });

        } catch (error) {
            console.error('Error exporting to XLSX:', error);
            Swal.fire('Error', 'Failed to export to XLSX: ' + error.message, 'error');
        }
    }

    async function downloadExcelTemplate() {
        const currentTable = "<?= htmlspecialchars($currentTable ?? '') ?>";
        const filename = `${currentTable}_template.xlsx`;

        try {
            // Fetch detailed column info
            const formData = new FormData();
            formData.append('action', 'get_table_columns');
            formData.append('table', currentTable);

            const response = await fetch('?', {
                method: 'POST',
                body: formData
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const result = await response.json();
            
            if (result.success) {
                const columns = result.columns;
                const refTables = result.referenced_tables || {};
                
                const headers = [];
                const colWidths = [];
                const fkDataMap = {};

                columns.forEach((col, index) => {
                    let headerName = col.name;
                    if (col.required) headerName += ' *';
                    headers.push(headerName);
                    colWidths.push({ wch: Math.max(headerName.length + 5, 15) });

                    if (col.fk_values && col.fk_values.length > 0) {
                        fkDataMap[index] = col.fk_values;
                    }
                });

                // Create Workbook
                const wb = XLSX.utils.book_new();

                // 1. Create Main Worksheet
                const ws = XLSX.utils.aoa_to_sheet([headers]);
                ws['!cols'] = colWidths;

                // Add Comments
                for (let i = 0; i < columns.length; i++) {
                    const col = columns[i];
                    const cellRef = XLSX.utils.encode_cell({c: i, r: 0});
                    
                    let note = `Type: ${col.type}\n`;
                    note += col.required ? "Required: YES\n" : "Required: NO\n";
                    if (col.fk) {
                        note += `Foreign Key: ${col.fk.table}.${col.fk.col}`;
                    }
                    
                    if(!ws[cellRef]) ws[cellRef] = { t: 's', v: headers[i] };
                    if(!ws[cellRef].c) ws[cellRef].c = [];
                    ws[cellRef].c.push({a: "Adminer", t: note});
                }

                // Append main table sheet
                XLSX.utils.book_append_sheet(wb, ws, currentTable || "Template");

                // 2. Create Reference Sheets (one for each referenced table)
                Object.keys(refTables).forEach(tableName => {
                    const data = refTables[tableName];
                    if (data && data.length > 0) {
                        const refWs = XLSX.utils.json_to_sheet(data);
                        // Add auto-width for ref sheets
                        const refCols = Object.keys(data[0]).map(key => ({ 
                            wch: Math.min(Math.max(key.length, 10), 30) 
                        }));
                        refWs['!cols'] = refCols;
                        
                        // Limit sheet name to 31 chars (Excel limit)
                        const sheetName = tableName.substring(0, 31);
                        XLSX.utils.book_append_sheet(wb, refWs, sheetName);
                    }
                });

                // 3. Validation Data sheet for legacy dropdowns
                const validationSheetName = "Validations";
                const dataVsData = [];
                const dataVsHeaders = [];
                Object.keys(fkDataMap).forEach(idx => {
                    dataVsHeaders.push(`${columns[idx].name} Values`);
                });

                if (dataVsHeaders.length > 0) {
                    dataVsData.push(dataVsHeaders);
                    let maxRows = 0;
                    Object.values(fkDataMap).forEach(arr => maxRows = Math.max(maxRows, arr.length));
                    
                    for(let r=0; r < maxRows; r++) {
                        const row = [];
                        Object.keys(fkDataMap).forEach(idx => {
                            row.push(fkDataMap[idx][r] || "");
                        });
                        dataVsData.push(row);
                    }
                    const vWs = XLSX.utils.aoa_to_sheet(dataVsData);
                    XLSX.utils.book_append_sheet(wb, vWs, validationSheetName);

                    // Add Data Validations to the main sheet
                    let refColIdx = 0;
                    Object.keys(fkDataMap).forEach(colIdx => {
                        const valuesCount = fkDataMap[colIdx].length;
                        if(valuesCount > 0) {
                            const dataColChar = XLSX.utils.encode_col(refColIdx); 
                            const range = `'${validationSheetName}'!$${dataColChar}$2:$${dataColChar}$${valuesCount + 1}`;
                            const templateColChar = XLSX.utils.encode_col(parseInt(colIdx));
                            
                            if (!ws['!dataValidation']) ws['!dataValidation'] = [];
                            ws['!dataValidation'].push({
                                type: 'list',
                                allowBlank: true,
                                operator: 'between', 
                                formula1: range,
                                sqref: `${templateColChar}2:${templateColChar}1000`,
                                showErrorMessage: true,
                                errorTitle: "Invalid Value",
                                error: "Please select a value from the list."
                            });
                           
                            refColIdx++;
                        }
                    });
                }

                // Write File
                XLSX.writeFile(wb, filename);

                const toast = Swal.mixin({toast: true, position: 'top-end', showConfirmButton: false, timer: 1500});
                toast.fire({ icon: 'success', title: 'Template downloaded!' });
            } else {
                throw new Error(result.message || 'Failed to fetch table columns.');
            }
        } catch (error) {
            console.error('Error downloading template:', error);
            Swal.fire('Error', 'Failed to download template: ' + error.message, 'error');
        }
    }

    // --- XLSX Import Logic ---
    let importDataPayload = null; // Store context for confirm

    document.addEventListener('DOMContentLoaded', () => {
        const excelImportForm = document.getElementById('excelImportForm');
        if (excelImportForm) {
            excelImportForm.addEventListener('submit', handleExcelImport);
        }
    });

    function updateImportStatus(message, type = 'info') {
        const statusDiv = document.getElementById('importStatus');
        if (statusDiv) {
            statusDiv.innerHTML = `<div class="alert alert-${type}">${message}</div>`;
        }
    }

    async function handleExcelImport(event) {
        event.preventDefault();
        updateImportStatus('Reading Excel file...', 'info');

        const fileInput = document.getElementById('excelFile');
        const file = fileInput.files[0];
        if (!file) {
            updateImportStatus('Please select an Excel file.', 'danger');
            return;
        }

        const tableName = event.target.querySelector('input[name="table"]').value;
        const importType = event.target.querySelector('input[name="importType"]:checked').value;
        const primaryKeyCol = document.getElementById('primaryKeyCol').value;
        const truncateTable = document.getElementById('truncateTable').checked;

        if ((importType === 'update' || importType === 'upsert') && !primaryKeyCol) {
            updateImportStatus('Primary Key Column is required for Update/Upsert import types.', 'danger');
            return;
        }

        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                
                // Convert sheet to JSON. header:1 means first row is header.
                const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

                if (jsonData.length < 2) {
                    updateImportStatus('Excel file is empty or only contains headers.', 'danger');
                    return;
                }

                // Assume first row is headers
                const headers = jsonData[0];
                const rowsToImport = jsonData.slice(1); // Data rows

                // Store basic payload info
                importDataPayload = {
                    action: 'import_excel',
                    table: tableName,
                    importType: importType,
                    primaryKeyCol: primaryKeyCol,
                    truncateTable: truncateTable,
                    headers: headers
                    // data will be grabbed from table on confirm
                };

                renderPreviewTable(headers, rowsToImport);
                updateImportStatus('Preview loaded. Review data below before confirming.', 'success');

            } catch (error) {
                console.error('Error during Excel import:', error);
                updateImportStatus(`An error occurred during import: ${error.message}`, 'danger');
            }
        };
        reader.readAsArrayBuffer(file);
    }

    function renderPreviewTable(headers, data) {
        const container = document.getElementById('importPreviewContainer');
        const table = document.getElementById('previewTable');
        const thead = table.querySelector('thead');
        const tbody = table.querySelector('tbody');

        container.style.display = 'block';
        thead.innerHTML = '';
        tbody.innerHTML = '';

        // Generate mapping dropdown options
        let colOptions = '<option value="_skip_">-- Skip / Ignore --</option>';
        if (window._currentTableStructure) {
            window._currentTableStructure.forEach(c => {
                colOptions += `<option value="${c.name}">${c.name}</option>`;
            });
        }

        // Headers
        const trHead = document.createElement('tr');
        headers.forEach(h => {
            const th = document.createElement('th');
            if (window._currentTableStructure) {
                th.innerHTML = `<div style="font-size:0.8rem; color:var(--text-secondary); margin-bottom:5px;">CSV: <strong>${h}</strong></div>
                                <select class="form-select import-map-select" style="font-size:0.85rem; padding:4px;">
                                    ${colOptions}
                                </select>`;
                const sel = th.querySelector('select');
                const matchedCol = window._currentTableStructure.find(c => c.name.toLowerCase() === String(h).toLowerCase());
                if (matchedCol) {
                    sel.value = matchedCol.name;
                } else {
                    sel.value = '_skip_';
                }
            } else {
                // Fallback if table structure is missing
                th.innerHTML = `<div style="font-size:0.8rem; color:var(--text-secondary); margin-bottom:5px;">CSV: <strong>${h}</strong></div>
                                <select class="form-select import-map-select" style="font-size:0.85rem; padding:4px;">
                                    <option value="${h}">${h}</option>
                                    <option value="_skip_">-- Skip --</option>
                                </select>`;
            }
            trHead.appendChild(th);
        });
        thead.appendChild(trHead);

        // Body
        data.forEach(row => {
            const tr = document.createElement('tr');
            // Ensure row matches header length
            for(let i=0; i < headers.length; i++) {
                const td = document.createElement('td');
                const val = (row[i] !== undefined && row[i] !== null) ? row[i] : "";
                td.textContent = val;
                td.setAttribute('contenteditable', 'true');
                td.style.border = '1px solid #444'; // Visual cue
                td.addEventListener('blur', function() {
                    // Optional: Validation logic here
                });
                tr.appendChild(td);
            }
            tbody.appendChild(tr);
        });
    }

    function cancelImport() {
        document.getElementById('importPreviewContainer').style.display = 'none';
        updateImportStatus('Import cancelled.');
        importDataPayload = null;
    }

    async function confirmImport() {
        if(!importDataPayload) return;

        updateImportStatus('Sending data to server...', 'info');
        
        const table = document.getElementById('previewTable');
        const selectEls = table.querySelectorAll('thead select.import-map-select');
        const mappedHeaders = [];
        const includeIndices = [];

        selectEls.forEach((sel, index) => {
            if (sel.value !== '_skip_') {
                mappedHeaders.push(sel.value);
                includeIndices.push(index);
            }
        });

        if (mappedHeaders.length === 0) {
            updateImportStatus('Error: No columns mapped for import.', 'danger');
            return;
        }

        // Scrape data from table
        const rows = table.querySelectorAll('tbody tr');
        const finalData = [];

        rows.forEach(tr => {
            const rowData = [];
            const tds = tr.querySelectorAll('td');
            includeIndices.forEach(idx => {
                if (tds[idx]) {
                    rowData.push(tds[idx].textContent);
                } else {
                    rowData.push("");
                }
            });
            // Only add row if it contains at least one non-empty value
            if (rowData.some(v => v.trim() !== '')) {
                finalData.push(rowData);
            }
        });

        importDataPayload.headers = mappedHeaders;
        importDataPayload.data = finalData;

        try {
            const response = await fetch('?', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json' 
                },
                body: JSON.stringify(importDataPayload)
            });

            // Handle non-JSON responses (fatal errors)
            const text = await response.text();
            let result;
            try {
                result = JSON.parse(text);
            } catch (e) {
                throw new Error('Server returned invalid JSON: ' + text.substring(0, 100) + '...');
            }

            if (result.success) {
                updateImportStatus(`Import successful! ${result.insertedRows || 0} inserted, ${result.updatedRows || 0} updated.`, 'success');
                document.getElementById('importPreviewContainer').style.display = 'none';
            } else {
                updateImportStatus(`Import failed: ${result.message || 'Unknown error.'}`, 'danger');
            }

        } catch (error) {
            console.error('Error sending import data:', error);
            updateImportStatus(`An error occurred: ${error.message}`, 'danger');
        }
    }

    // --- DIAGRAM FULLSCREEN HELPER ---
    window.toggleFullscreenDiagram = function(el) {
        if (!document.fullscreenElement) {
            const requestMethod = el.requestFullscreen || el.webkitRequestFullscreen || el.mozRequestFullScreen || el.msRequestFullscreen;
            if (requestMethod) {
                requestMethod.call(el).catch(err => {
                    el.parentElement.requestFullscreen();
                });
            } else {
                el.parentElement.requestFullscreen();
            }
            el.style.maxHeight = 'none';
            if (el.tagName === 'IMG') {
                el.style.height = '100vh';
                el.style.width = '100vw';
                el.style.objectFit = 'contain';
                el.style.background = '#000';
            } else {
                el.style.background = '#000';
            }
        } else {
            document.exitFullscreen();
        }
    };

    document.addEventListener('fullscreenchange', () => {
        if (!document.fullscreenElement) {
            document.querySelectorAll('.mermaid, .erd-img').forEach(el => {
                el.style.maxHeight = '600px';
                el.style.background = el.tagName === 'IMG' ? '#fff' : '#080808';
                if (el.tagName === 'IMG') {
                    el.style.height = 'auto';
                    el.style.width = '100%';
                }
            });
        }
    });
</script>
