        table { width: 100%; border-collapse: collapse; min-width: 600px; }
        th, td { padding: 10px 15px; text-align: left; border-bottom: 1px solid var(--border-color); }
        th { background: var(--bg-input);color: var(--text-primary); font-weight: 600; font-size: 0.8rem; text-transform: uppercase; white-space: nowrap; position: sticky; top: 0; z-index: 5; box-shadow: 0 2px 5px rgba(0,0,0,0.5); }
        tr:hover td { background: var(--bg-hover); }
        td { max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

        /* TABS */
        .tabs { display: flex; gap: 2px; margin-bottom: 20px; border-bottom: 1px solid var(--border-color); }
        .tab { padding: 10px 20px; cursor: pointer; border-bottom: 2px solid transparent; color: var(--text-secondary); font-weight: 500; }
        .tab:hover { color: var(--text-primary); background: var(--bg-hover); border-radius: 4px 4px 0 0; }
        .tab.active { border-bottom-color: var(--accent); color: var(--accent); }

        /* ADVANCED SEARCH */
        .search-bar { display: flex; gap: 10px; flex-wrap: wrap; background: var(--bg-hover); padding: 10px; border-radius: 6px; margin-bottom: 15px; border: 1px solid var(--border-color); align-items: center; }
        .search-group { display: flex; gap: 0; }
        .search-group .form-control, .search-group .form-select { border-radius: 0; }
        .search-group *:first-child { border-radius: 4px 0 0 4px; }
        .search-group *:last-child { border-radius: 0 4px 4px 0; border-left: none; }

        .dashboard-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; margin-bottom: 30px; }
        .stat-card { background: var(--bg-card); padding: 20px; border: 1px solid var(--border-color); border-radius: 6px; }
        .stat-val { font-size: 1.8rem; font-weight: bold; margin: 10px 0 0; }
        .stat-label { color: var(--text-secondary); font-size: 0.85rem; text-transform: uppercase; }

        /* Responsive adjustments */
        @media (max-width: 768px) {
            .sidebar.collapsed {
                width: var(--sidebar-collapsed-width); /* Ensure it stays collapsed */
            }
            /* Adjust sidebar toggle position for mobile if needed, or rely on existing */
            .sidebar-toggle {
                right: -33px;
                margin-top: 260px;
            }
            .search-bar { flex-direction: column; align-items: stretch; }
            .search-group { width: 100%; }
            body {
                flex-direction: row; /* Ensure sidebar and main content stay side-by-side */
            }
        }
        /* --- TOOL MODAL STYLES --- */
.swal2-tabs {
    display: flex;
    border-bottom: 1px solid #333;
    margin-bottom: 15px;
}
.swal2-tabs button {
    background: transparent;
    border: none;
    color: var(--text-secondary);
    padding: 10px 15px;
    cursor: pointer;
    font-weight: 600;
    border-bottom: 2px solid transparent;
    transition: 0.2s;
}
.swal2-tabs button:hover { color: var(--text-primary); }
.swal2-tabs button.active {
    color: var(--accent);
    border-bottom-color: var(--accent);
}
.swal2-tab-content { display: none; }
.swal2-tab-content.active { display: block; }

/* Custom Inputs inside SweetAlert */
.swal2-input, .swal2-textarea, .swal2-select, .swal2-range {
    background-color: var(--bg-input) !important;
    border: 1px solid var(--border-color) !important;
    color: var(--text-primary) !important;
    border-radius: 4px !important;
    font-size: 14px;
}
.swal2-checkbox label {
    color: var(--text-primary) !important;
    font-size: 14px;
    margin-left: 5px;
    cursor: pointer;
}
.tool-row {
    display: flex;
    align-items: center;
    margin-bottom: 10px;
    justify-content: center;
}
.tool-label {
    width: 100px;
    color: var(--text-secondary);
    font-size: 13px;
}
.tool-result {
    background: #000;
    border: 1px solid #333;
    padding: 10px;
    color: var(--accent);
    font-family: monospace;
    font-size: 13px;
    word-break: break-all;
    position: relative;
}

/* Media Preview Styles */
.swal-image-preview {
    max-width: 90vw !important;
    max-height: 80vh !important;
    object-fit: contain;
    border-radius: 8px;
    margin: 0;
    padding: 10px;
    border-radius: 10px;
}

.dark-modal {
    background: var(--bg-card) !important;
    color: var(--text-primary) !important;
}

/* Foreign Key Preview Styles */
.fk-cell-wrapper {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.fk-indicator,
.fk-indicator-convention {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border-radius: 3px;
    font-size: 10px;
    transition: all 0.2s ease;
}

.fk-indicator {
    background: rgba(99, 102, 241, 0.15);
    border: 1px solid rgba(99, 102, 241, 0.3);
    color: #6366f1;
}

.fk-indicator-convention {
    background: rgba(168, 85, 247, 0.15);
    border: 1px solid rgba(168, 85, 247, 0.3);
    color: #a855f7;
}

.fk-cell-wrapper:hover .fk-indicator,
.fk-cell-wrapper:hover .fk-indicator-convention {
    transform: scale(1.1);
    box-shadow: 0 2px 8px rgba(99, 102, 241, 0.3);
}

.fk-link {
    color: var(--accent);
    text-decoration: none;
    border-bottom: 1px dashed var(--accent);
    cursor: pointer;
    transition: all 0.2s ease;
}

.fk-link:hover {
    color: #818cf8;
    border-bottom-color: #818cf8;
}

.fk-label {
    color: #94a3b8;
    font-size: 0.85em;
    font-weight: normal;
}

#fk-tooltip {
    position: fixed;
    background: #1a1a1a;
    border: 1px solid #333;
    border-radius: 8px;
    padding: 12px 16px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
    z-index: 10000;
    max-width: 350px;
    font-size: 0.85rem;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
}

#fk-tooltip img,
#fk-tooltip video {
    border-radius: 6px;
    transition: transform 0.2s;
}

#fk-tooltip img:hover,
#fk-tooltip video:hover {
    transform: scale(1.02);
}

/* FK Inline Edit Styles */
.fk-editable-field {
    position: relative;
    transition: all 0.2s ease;
}

.fk-editable-field:hover::after {
    content: '✎';
    position: absolute;
    right: 4px;
    top: 50%;
    transform: translateY(-50%);
    color: #6366f1;
    font-size: 0.9rem;
    opacity: 0.6;
    pointer-events: none;
}

.fk-editable-field input {
    font-family: inherit;
}

.fk-editable-field input:focus {
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
}

/* Query Builder & Advanced Filters Styles */

.query-builder,
.advanced-filters {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 20px;
}

.qb-section {
    margin-bottom: 25px;
    padding-bottom: 20px;
    border-bottom: 1px solid var(--border-color);
}

.qb-section:last-child {
    border-bottom: none;
    margin-bottom: 0;
}

.qb-section h4 {
    margin: 0 0 15px 0;
    color: var(--text-primary);
    font-size: 1rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
}

.qb-section h4 i {
    color: var(--accent);
}

.qb-columns label {
    cursor: pointer;
    padding: 4px 0;
    transition: color 0.2s;
}

.qb-columns label:hover {
    color: var(--accent);
}

.qb-condition,
.qb-order,
.af-filter {
    animation: slideIn 0.3s ease-out;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.qb-condition select,
.qb-condition input,
.qb-order select,
.af-filter select,
.af-filter input,
.af-filter textarea {
    font-size: 0.9rem;
}

/* Advanced Filters specific */
.af-filter {
    position: relative;
    transition: all 0.2s;
}

.af-filter:hover {
    background: var(--bg-card) !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.af-value-container {
    display: flex;
    align-items: center;
}

/* Responsive */
@media (max-width: 768px) {
    .qb-condition,
    .qb-order,
    .af-filter {
        flex-direction: column;
        align-items: stretch !important;
    }
    
    .qb-condition > *,
    .qb-order > *,
    .af-filter > * {
        width: 100% !important;
        min-width: 100% !important;
    }
}

/* Button styles */
.btn-sm {
    padding: 6px 12px;
    font-size: 0.85rem;
}

/* TomSelect overrides for dark theme */
.ts-wrapper.form-select .ts-control {
    background-color: var(--bg-input) !important;
    border-color: var(--border-color) !important;
}

.ts-dropdown {
    background-color: var(--bg-card) !important;
    border-color: var(--border-color) !important;
}

.ts-dropdown .option {
    color: var(--text-primary) !important;
}

.ts-dropdown .option:hover,
.ts-dropdown .option.active {
    background-color: var(--bg-hover) !important;
    color: var(--accent) !important;
}

/* Query preview */
#qb-generated-query {
    font-family: 'Fira Code', 'Courier New', monospace;
    line-height: 1.6;
    tab-size: 4;
}

/* Loading state */
.qb-loading,
.af-loading {
    position: relative;
    pointer-events: none;
    opacity: 0.6;
}

.qb-loading::after,
.af-loading::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 30px;
    height: 30px;
    margin: -15px 0 0 -15px;
    border: 3px solid var(--border-color);
    border-top-color: var(--accent);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

