                    let currentChartFks = {};

                    function toggleDataCol(mode) {
                        const select = document.getElementById('c_data_col');
                        if (mode === 'COUNT') {
                            select.tomselect.disable();
                            select.tomselect.setValue('*');
                        } else {
                            select.tomselect.enable();
                        }
                    }

                    function checkFk(colName) {
                        const fk = currentChartFks[colName];
                        const container = document.getElementById('fk_display_container');
                        const displaySelect = document.getElementById('c_label_display_col');
                        
                        if (fk) {
                            container.style.display = 'block';
                            displaySelect.tomselect.clearOptions();
                            displaySelect.tomselect.addOption({value: '', text: 'Loading referenced columns...'});
                            
                            fetch('?', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                body: `action=get_columns&table=${encodeURIComponent(fk.table)}`
                            })
                            .then(r => r.json())
                            .then(res => {
                                displaySelect.tomselect.clearOptions();
                                res.columns.forEach(c => displaySelect.tomselect.addOption({value: c.Field, text: c.Field}));
                                // Default to a column that looks like a "name" or "title"
                                const bestGuess = res.columns.find(c => /name|title|label|desc/i.test(c.Field));
                                if (bestGuess) displaySelect.tomselect.setValue(bestGuess.Field);
                            });
                        } else {
                            container.style.display = 'none';
                            displaySelect.tomselect.clearOptions();
                        }
                    }

                    function updateChartCols(table) {
                        if (!table) return;
                        fetch('?', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                            body: `action=get_columns&table=${encodeURIComponent(table)}`
                        })
                            .then(r => r.json())
                            .then(res => {
                                currentChartFks = res.fks || {};
                                const tsL = document.getElementById('c_label_col').tomselect;
                                const tsD = document.getElementById('c_data_col').tomselect;
                                
                                tsL.clearOptions();
                                tsD.clearOptions();
                                tsD.addOption({value: '*', text: 'All (*)'});
                                
                                res.columns.forEach(c => {
                                    tsL.addOption({value: c.Field, text: c.Field});
                                    tsD.addOption({value: c.Field, text: c.Field});
                                });
                                
                                // Initial check for FK
                                checkFk(tsL.getValue());
                            });
                    }

                    function updateWidgetCols(table) {
                        if (!table) return;
                        fetch('?', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                            body: `action=get_columns&table=${encodeURIComponent(table)}`
                        })
                            .then(r => r.json())
                            .then(res => {
                                const ts = document.getElementById('w_col').tomselect;
                                ts.clearOptions();
                                ts.addOption({value: '*', text: '* (All)'});
                                res.columns.forEach(c => {
                                    ts.addOption({value: c.Field, text: c.Field});
                                });
                                ts.setValue('*');
                            });
                    }

                    function openJsonEditor(el) {
                        const raw = el.getAttribute('data-raw');
                        try {
                            const json = JSON.parse(raw);
                            Swal.fire({
                                title: '<i class="fas fa-file-code"></i> JSON Tree Viewer',
                                background: 'var(--bg-card)',
                                color: 'var(--text-primary)',
                                html: `<div id="json-tree-container" class="json-tree" style="text-align:left; max-height:500px; overflow-y:auto; padding:20px; background:#000; border-radius:8px; border:1px solid var(--border-color);"></div>`,
                                width: '700px',
                                showCloseButton: true,
                                showConfirmButton: false,
                                didOpen: () => {
                                    document.getElementById('json-tree-container').innerHTML = ''; // Clear
                                    renderJsonTree(json, document.getElementById('json-tree-container'));
                                }
                            });
                        } catch(e) { 
                            console.error(e); 
                            Swal.fire('Error', 'Invalid JSON data', 'error');
                        }
                    }

                    function renderJsonTree(data, container, key = null) {
                        const item = document.createElement('div');
                        item.style.marginLeft = '20px';
                        
                        const type = typeof data;
                        const isArray = Array.isArray(data);
                        const isObject = type === 'object' && data !== null;

                        if (isObject) {
                            const line = document.createElement('div');
                            
                            const toggle = document.createElement('span');
                            toggle.className = 'json-toggle';
                            toggle.innerHTML = '<i class="fas fa-chevron-down" style="font-size:0.7rem; width:12px;"></i>';
                            line.appendChild(toggle);
                            
                            if (key !== null) {
                                const kSpan = document.createElement('span');
                                kSpan.className = 'json-key';
                                kSpan.textContent = key + ': ';
                                line.appendChild(kSpan);
                            }
                            
                            const bracket = document.createElement('span');
                            bracket.textContent = isArray ? '[' : '{';
                            bracket.style.color = '#fff';
                            line.appendChild(bracket);
                            
                            item.appendChild(line);
                            
                            const content = document.createElement('div');
                            for (let k in data) {
                                renderJsonTree(data[k], content, k);
                            }
                            item.appendChild(content);
                            
                            const closing = document.createElement('div');
                            closing.textContent = isArray ? ']' : '}';
                            closing.style.color = '#fff';
                            closing.style.marginLeft = '12px';
                            item.appendChild(closing);
                            
                            toggle.onclick = (e) => {
                                e.stopPropagation();
                                const collapsed = content.style.display === 'none';
                                content.style.display = collapsed ? 'block' : 'none';
                                toggle.innerHTML = collapsed ? '<i class="fas fa-chevron-down" style="font-size:0.7rem; width:12px;"></i>' : '<i class="fas fa-chevron-right" style="font-size:0.7rem; width:12px;"></i>';
                            };
                        } else {
                            const line = document.createElement('div');
                            if (key !== null) {
                                const kSpan = document.createElement('span');
                                kSpan.className = 'json-key';
                                kSpan.textContent = key + ': ';
                                line.appendChild(kSpan);
                            }
                            const vSpan = document.createElement('span');
                            vSpan.className = 'json-' + type;
                            vSpan.textContent = type === 'string' ? `"${data}"` : data;
                            line.appendChild(vSpan);
                            item.appendChild(line);
                        }
                        container.appendChild(item);
                    }

                    function selectChartType(type) {
                        document.querySelectorAll('.chart-type-item').forEach(item => item.classList.remove('active'));
                        const selected = document.querySelector(`.chart-type-item[data-type="${type}"]`);
                        if (selected) selected.classList.add('active');
                        document.getElementById('c_type').value = type;
                    }

